import{n as e,r as t}from"./rolldown-runtime-CNOWq4Kh.js";var n=t({default:()=>r}),r;function i(){return(i=e((()=>{r={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Kontroller för ACP-körmiljön för att aktivera fördelning, välja backend, begränsa tillåtna målagenter och välja hur strömmade turer projiceras.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Tillåtna ACP-agenter`},help:{"v1-f2mw0d-3a":`Lista över tillåtna ID:n för ACP-målagenter som får användas i ACP-körmiljösessioner. En tom lista innebär ingen ytterligare begränsning.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACP-backend`},help:{"v1-1s1l6bz-2v":`Standard-id för ACP-körmiljöns backend (till exempel: acpx). Måste matcha en registrerad plugin-backend för ACP-körmiljön.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Standardagent för ACP`},help:{"v1-7donnu-2c":`Reserv-id för ACP-målagenten som används när ACP-startåtgärder inte anger ett uttryckligt mål.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`ACP-dispatch aktiverad`},help:{"v1-1ug9t9m-3w":`Oberoende aktiveringskontroll för dispatch av ACP-sessionsturer (standard: true). Ange false för att behålla ACP-kommandon tillgängliga men blockera körning av ACP-turer.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP aktiverat`},help:{"v1-1uonl1v-2a":`Global aktiveringskontroll för ACP-funktioner. Låt den vara inaktiverad om inte ACP-körmiljön och policyn är konfigurerade.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Reservbackender för ACP`},help:{"v1-1wvdifq-5m":`Ordnad lista med id:n för ACP-reservbackender som provas när den primära backendens körning misslyckas med UNAVAILABLE (till exempel: anropsgränsen har nåtts eller kvoten är förbrukad). Varje post måste matcha en registrerad plugin-backend för ACP-körmiljön.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Installationskommando för ACP-körmiljön`},help:{"v1-1jjuv9m-39":"Valfritt installations- eller konfigurationskommando för operatörer som visas av `/acp install` och `/acp doctor` när kopplingen till ACP-backenden saknas."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP-ström`},help:{"v1-1bka5p-2v":`Kontroller för ACP-strömmens projektion: blockstorlek, synlighet för metadata och leverans med borttagna dubbletter.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Leveransläge för ACP-ström`},help:{"v1-19gdmx1-3s":`Leveranssätt för ACP: live strömmar projicerad utdata stegvis, medan final_only buffrar all projicerad ACP-utdata tills händelser som avslutar turen inträffar.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Undertryckning av upprepningar i ACP-strömmen`},help:{"v1-manh32-3d":`När värdet är true (standard) undertrycks upprepade projektionsrader för ACP-status och verktyg under en tur, medan råa ACP-händelser lämnas oförändrade.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Taggsynlighet i ACP-strömmen`},help:{"v1-1ybhx22-34":`Åsidosättningar av synlighet per sessionUpdate för ACP-projektion (till exempel usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agenter`},help:{"v1-2rc4v8-55":`Rot för agenternas körningskonfiguration. Syskonnoder på rotnivån ansvarar för infrastruktur och standardvärden som gäller för alla agenter; agents.defaults ansvarar för agentloopens beteende; agentposter kan åsidosätta båda där det stöds.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Standardinställningar för agenter`},help:{"v1-1af7k5b-5a":`Gemensamma standardinställningar som ärvs av agenter om de inte åsidosätts per post i agents.entries. Använd standardinställningar för att säkerställa ett enhetligt grundbeteende och minska duplicerad konfiguration per agent.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Mål för autentiseringsarv`},help:{"v1-2d16wl-2x":`Ägare till det ärvda lagret för autentiseringsuppgifter för kompatibilitet vid uppgradering, tills autentiseringsuppgifterna har flyttats till respektive agent.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Ägare för autentiseringsarv`},help:{"v1-1a1s7nm-4s":`Agent vars äldre lager för autentiseringsuppgifter förblir arvskälla efter att standardmarkören har tagits bort. Skrivs automatiskt under uppgraderingen när den tidigare ägaren inte var main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Maximalt antal tecken vid initiering`},help:{"v1-drlo3i-37":`Maximalt antal tecken från varje initieringsfil i arbetsytan som infogas i systemprompten före trunkering (standard: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Totalt maxantal tecken för initiering`},help:{"v1-1evwsjb-2c":`Maximalt totalt antal tecken i alla infogade initieringsfiler från arbetsytan (standard: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Komprimering`},help:{"v1-1qxdwz8-5p":`Komprimeringsbeteende när kontexten närmar sig tokengränserna, inklusive strategi och hur minnet sparas före komprimering. Använd detta när långvariga sessioner behöver stabil kontinuitet med begränsade kontextfönster.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Inbyggd automatisk komprimering`},help:{"v1-1et7vwu-5l":`Aktivera inbyggd proaktiv automatisk komprimering (standard: true). Ange false för att stoppa tröskelstyrd inbyggd komprimering men behålla OpenClaw-återställning vid överskridna gränser, förberedande komprimering och manuell /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Identifierarpolicy för komprimering`},help:{"v1-hby01l-4l":`Policy för att bevara identifierare i komprimeringssammanfattningar: "strict" lägger till inbyggda anvisningar för att bevara opaka identifierare i början (standard), medan "off" inaktiverar detta prefix.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Senaste token att behålla vid komprimering`},help:{"v1-tgysub-5h":`Minsta tokenbudget som bevaras från det senaste konversationsfönstret vid komprimering. Använd högre värden för att skydda kontinuiteten i den aktuella kontexten och lägre värden för att behålla mer äldre historik.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-476m1y-11":`Storleksgräns för komprimering av aktiv chatt`},help:{"v1-7p9ney-ah":`Bytetröskel för förberedande lokal komprimering i den inbyggda körmiljön (byte eller strängar som "20mb"). För Codex app-server begränsas i stället den historik som används för att initiera nya trådar: endast ett sammanfattningsförsök på värdsidan, och bara när historik som inte sammanfattats annars skulle utelämnas, aldrig vid vanliga turer eller efter inbyggd /compact. Ange 0 eller lämna värdet oangivet för att inaktivera. Inbyggda skyddsgränser för rollout-storlek och tokenantal är oförändrade.`}},"agents%2Edefaults%2Ecompaction%2EmaxSummaryChars":{label:{"v1-18p81ru-x":`Maximalt antal tecken i komprimeringssammanfattning`},help:{"v1-em0nj5-8b":`Maximalt antal tecken i en sparad komprimeringssammanfattning på klientsidan (standard: 16000; intervall: 1000–200000). Större sammanfattningar bevarar mer genererad kontext men ökar kostnaden för att återanvända den vid senare förfrågningar. Den aktiva modellens tokenbudget kan kräva en mindre sammanfattning. Styr inte leverantörens inbyggda komprimering.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Minnessparning inför komprimering`},help:{"v1-1xbzc1i-6t":`Inställningar för minnessparning före komprimering som låter agenten skriva till minnet med den aktiva sessionens modell och dess vanliga kedja av reservmodeller före omfattande komprimering. Låt detta vara aktiverat för långa sessioner så att viktig kontext sparas innan innehållet kortas ned kraftigt.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Minnessparning inför komprimering aktiverad`},help:{"v1-9xllgp-5o":`Aktiverar minnessparning inför komprimering, innan körmiljön minskar historiken mer kraftigt nära tokengränserna. Behåll detta aktiverat om du inte avsiktligt vill inaktivera sidoeffekter på minnet i begränsade miljöer.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-1mr3mj1-17":`Chattstorleksgräns för minnessparning före komprimering`},help:{"v1-pihai2-8y":`Tvingar fram minnessparning före komprimering när chatthistoriken som modellen kan se når denna gräns (byte eller strängar som "2mb"). Efter komprimering omfattar detta den sparade avslutande delen och efterföljande meddelandeutbyten, inte borttagen historik. Använd detta för att förhindra att långa sessioner hänger sig även när tokenräknarna inte är uppdaterade. Ange 0 för att inaktivera.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Mjuk tröskel för minnessparning före komprimering`},help:{"v1-1dqo2l1-5c":`Tröskelavstånd till komprimering (i token) som utlöser minnessparning före komprimering. Använd tidigare trösklar för säkrare lagring eller snävare trösklar för mindre frekvent minnessparning.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Förkontroll av komprimering under pågående tur`},help:{"v1-12ud1gw-6c":`Valfri tröskel för uppskattad belastning mellan verktygsomgångar som använder komprimeringsreserven. Underhåll av tröskeln baserat på leverantörens mätningar och strikt kontroll mot kontextfönstrets gräns körs oberoende av varandra och återanvänder säker trunkering eller återställning genom komprimering.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Förkontroll av komprimering under pågående tur aktiverad`},help:{"v1-1or5cwa-57":`Aktivera den valfria tröskeln för uppskattad belastning mellan verktygsomgångar. Standardvärde: false. Underhåll av tröskeln baserat på mätningar och den strikta kontrollen mot kontextfönstrets gräns förblir aktiva när detta är inaktiverat.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Komprimeringsläge`},help:{"v1-1unahwc-76":`Läge för komprimeringsstrategi: "safeguard" (det faktiska standardläget när inget anges) tillämpar skyddsåtgärder för att bevara den senaste kontexten, medan "default" använder grundläggande sammanfattning utan dessa. Ange endast "default" om sammanfattning med skyddsåtgärder orsakar problem hos din leverantör.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Alternativ modell för komprimering`},help:{"v1-cfeys9-6q":`Valfri leverantör/modell eller konfigurerat alias utan prefix som endast används för sammanfattning vid komprimering. Alias utan prefix slås upp innan anropet skickas; ett konfigurerat bokstavligt modell-ID har företräde om det krockar med ett alias. Lämna oangivet för att fortsätta använda agentens primära modell.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Meddela användaren om komprimering`},help:{"v1-lvymm8-bv":`När detta är aktiverat skickas korta meddelanden om kontextunderhåll till användaren: när komprimeringen börjar och slutförs (till exempel ”🧹 Komprimerar kontext...” och ”🧹 Komprimeringen är klar”), samt när försöken att spara minnet före komprimeringen är uttömda så att svaret fortsätter med begränsad funktion (till exempel ”⚠️ Minnesunderhållet misslyckades tillfälligt; fortsätter med ditt svar.”). Inaktiverat som standard för att hålla kontextunderhållet tyst och diskret.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Kontextavsnitt efter komprimering`},help:{"v1-1n0ln2u-5f":`Valfria namn på H2/H3-avsnitt i AGENTS.md som återinfogas efter komprimering. Lämna värdet oangivet eller ange [] för att inaktivera återinfogning. Ange uttryckligen ["Session Startup", "Red Lines"] för att aktivera det tidigare standardparet.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Indexsynkronisering efter komprimering`},help:{"v1-ekpjeq-6l":`Styr läget för omindexering av sessionsminnet efter komprimering: "off", "async" eller "await" (standard: "async"). Använd "await" för att säkerställa att indexet är så aktuellt som möjligt, "async" för kortare komprimeringslatens och "off" endast när synkronisering av sessionsminnet hanteras på annat håll.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Komprimeringsleverantör`},help:{"v1-2zoy3b-7v":`Id för ett registrerat tillägg för komprimeringsleverantör som används för sammanfattning. När värdet är angivet och leverantören är registrerad anropas dess summarize()-metod i stället för den inbyggda sammanfattningsbegäran. Återgår till den inbyggda funktionen om leverantören misslyckas. Lämna värdet oangivet för att använda den inbyggda standardsammanfattningen.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Kvalitetskontroll för komprimering`},help:{"v1-u9ognp-4k":`Inställningar för återförsök vid kvalitetsgranskning av komprimeringssammanfattningar i safeguard-läget. Safeguard-läget aktiverar detta som standard; ange enabled: false för att hoppa över granskning och omgenerering av sammanfattningar.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Kvalitetskontroll för komprimering aktiverad`},help:{"v1-1xk2vt3-36":`Aktiverar kvalitetsgranskning av sammanfattningar och återförsök med omgenerering för komprimering i safeguard-läget. Standard: true i safeguard-läget.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Maximalt antal återförsök för komprimeringens kvalitetskontroll`},help:{"v1-n7l46y-3y":`Maximalt antal återförsök att generera sammanfattningen på nytt efter en underkänd kvalitetsgranskning i skyddsläget. Använd låga värden för att begränsa extra fördröjning och tokenkostnader.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Bevara de senaste samtalsturerna vid komprimering`},help:{"v1-y34ihi-5k":`Antal av de senaste användar-/assistentturerna som bevaras ordagrant utanför skyddslägets sammanfattning (standard: 3). Höj värdet för att bevara den senaste dialogens exakta kontext, eller sänk det för att maximera besparingen vid komprimering.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Resonemangsnivå vid komprimering`},help:{"v1-1vafgaw-g1":`Resonemangsnivå som endast används för inbäddade komprimeringssammanfattningar i OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" eller "inherit". Standardvärdet är leverantörens komprimeringspreferens, annars "low"; lokal Ollama med inbyggt stöd föredrar "off". Ange "inherit" för att återanvända sessionens nivå. Uttryckliga inställningar åsidosätter leverantörens standardvärden, och den valda nivån begränsas till vad den faktiska komprimeringsmodellen/körmiljön stöder. Inbyggd komprimering i Codex app-server ignorerar den här inställningen eftersom dess komprimeringsbegäran inte stöder åsidosättning av resonemangsnivån per åtgärd, och OpenClaw loggar en varning.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Tidsgräns för komprimering (sekunder)`},help:{"v1-p0ymcy-c4":`Antal sekunder som en modellbegäran för inbyggd komprimering får pågå utan framsteg (standard: 180). Varje begäransstart och varje strömmad utdatatoken förnyar tidsfönstret, så en långsam begäran som fortsätter att strömma avbryts inte; hela komprimeringen stoppas efter 10 tidsfönster. Komprimering som hanteras av ett plugin får ett tidsfönster om inte motorn uttryckligen deklarerar onProgress i info.acceptedHostParams och rapporterar framsteg; samma gräns på 10 tidsfönster gäller.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Kontextinjektion`},help:{"v1-u18x0-7u":`Styr injektion av arbetsytans initieringsfiler i den inbäddade körmiljön: "always" använder normal injektion (standard), "continuation-skip" hoppar över tillämpliga fortsättningsomgångar efter en registrerad omgång med fullständig initiering, och "never" inaktiverar injektion. Styr inte CLI-baserad promptförberedelse.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Standardgränser för kontext`},help:{"v1-1coeez8-5d":`Riktade standardbudgetar per agentkontext för utvalda stora utdrag och injicerade promptblock. Använd detta för att justera begränsade läs- och injektionsstorlekar utan att åter öppna några obegränsade anropsvägar.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Standardvärde för max antal tecken för memory_get`},help:{"v1-1qb40qv-4v":`Standardvärde för maximalt antal tecken som returneras av memory_get innan metadata om trunkering och ett meddelande om fortsättning läggs till. Öka värdet för att närma dig tidigare större utdrag, men behåll en gräns.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Standardvärde för max antal tecken efter komprimering`},help:{"v1-64qo8g-5r":`Standardvärde för maximalt antal tecken som behålls från AGENTS.md när uppdaterad kontext infogas efter komprimering. Sänk värdet för att minska kostnaden för återställning efter komprimering, eller höj det för agenter som behöver längre startinstruktioner.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Arbetskatalog`},help:{"v1-1y8wlxn-6a":`Arbetskatalog för körningar som genererar agentsvar, separat från arbetsytans initierings- och minnesfiler. Agentspecifik cwd och cwd som anges när en session skapas har företräde. Stöder ~ och relativa sökvägar; en separat cwd kräver en körning utanför sandlådan.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Beslutsmodell`},help:{"v1-7nd7ze-64":`Valfri leverantör/modell för typade val, poäng och booleska sannolikheter. Om värdet inte är angivet eller är tomt inaktiveras beslutsanrop. Insticksprogram med stöd för funktionen skickar avgränsat uppgiftsunderlag till denna leverantör; chatt- och hjälpmodeller förblir oförändrade.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`Inbäddad OpenClaw`},help:{"v1-1keek32-3k":`Säkerhetshärdningsinställningar för den inbäddade OpenClaw-körmiljön som styr hur arbetsytelokala agentinställningar betros och tillämpas i OpenClaw-sessioner.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Reservväxling vid cyberpolicyavslag`},help:{"v1-pl298d-4c":`Automatisk eskalering till Daybreak med samma modell vid avvisningar enligt OpenAI:s cybersäkerhetspolicy som säkert kan köras om i den inbäddade körmiljön, med förbehåll för befintliga åtkomst- och policykontroller.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Väntetid för reservväxling vid cyberpolicyavslag`},help:{"v1-1hhmb1o-2l":`Hur länge otillgänglig Daybreak-åtkomst för den aktiva modellen hoppas över under den aktuella sessionen.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Reservläge för cyberpolicy`},help:{"v1-rzsd2b-2h":`Aktivera automatisk eskalering ("auto", standard) eller låt leverantörens avslag avsluta körningen ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Körningskontrakt för inbäddad OpenClaw`},help:{"v1-1fch2ig-66":`Körningskontrakt för inbäddad OpenClaw: "default" behåller standardbeteendet för körmotorn, medan "strict-agentic" aktiverar strukturerad planuppföljning och återställning av turer i bakgrunden för körningar som stöds med OpenAI/OpenAI Codex i GPT-5-familjen.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Policy för projektinställningar i inbäddad OpenClaw`},help:{"v1-fdyy04-65":'Hur inbäddad OpenClaw hanterar arbetsytans lokala `.openclaw/settings.json`: "sanitize" (standard) tar bort shellPath/shellCommandPrefix, "ignore" inaktiverar projektinställningar helt och "trusted" tillämpar projektinställningar utan ändringar.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Experimentella agentflaggor`},help:{"v1-cvv5cl-2w":`Experimentella flaggor för agentens standardinställningar. Låt dessa vara avstängda om du inte avsiktligt testar en förhandsversion av en funktion.`}},"agents%2Edefaults%2Eexperimental%2EdecisionAssistance":{label:{"v1-1tepbyi-y":`Beslutsstöd (experimentellt)`},help:{"v1-1fmo3r9-ew":`Global aktivering av experimentell assistans från den ansvariga agentens konfigurerade Decision-modell (standard: false; kräver uttryckligen true). Den effektiva decisionModel kan ärvas från globala standardinställningar eller väljas per agent; ett tomt värde för en enskild agent inaktiverar assistansen. Användningsområden som stöds kan innebära att utvalda data skickas till den leverantören och att leverantörsavgifter tillkommer. Se dokumentationen för beslutsassistans för information om användningsområden som stöds, konfiguration och datahantering. Den här inställningen styr inte explicita decision_evaluate-anrop, väljer inte leverantörer och ger inte behörighet till åtgärder.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Aktivera resurssnålt läge för lokala modeller (experimentellt)`},help:{"v1-gj06u6-7b":`Avancerad åsidosättning för felsökning som begränsar valfria verktyg som browser, automations och message. Av som standard; lokala körmiljöer som stöds använder automatisk verktygssökning utan denna begränsning. Uttryckliga verktygstillåtelser och obligatoriska leveransverktyg behålls.`}},"agents%2Edefaults%2Eexperimental%2EusageRankedToolIndex":{label:{"v1-ndslef-12":`Användningsrankat verktygsindex (experimentellt)`},help:{"v1-1jpzjov-bq":`Aktivera användningsrankade promptindex för Code Mode, Tool Search och MCP-verktygskatalogen i den inbäddade OpenClaw-körmiljön (standard: false). Lagrar endast verktygs-ID:n, tidsviktade poäng och tidsstämplar i operatörsägd agentlagring i 90 dagar; inkognitosessioner undantas. Rankningen förblir oförändrad fram till en gräns för promptprefix. Ändrar inte verktygsbehörigheter eller Codex. Granska, importera tidigare användning eller återställ med openclaw tools usage.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Standardläge för agentens snabbläge`},help:{"v1-6q8gx8-3c":`Standardpolicy för snabbläge i agentloopen ("auto", "ultrafast", true eller false). Enskilda agentposter åsidosätter den.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Maximal mänsklig fördröjning (ms)`},help:{"v1-vnmvli-1m":`Maximal fördröjning i ms för anpassad humanDelay (standard: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Minimal mänsklig fördröjning (ms)`},help:{"v1-5nrtr5-1l":`Minimal fördröjning i ms för anpassad humanDelay (standard: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Läge för mänsklig fördröjning`},help:{"v1-k7hyg3-1n":`Typ av fördröjning för svar i block ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Maximal bilddimension (px)`},help:{"v1-1j31o2j-2s":`Maximal sidlängd för bilder i pixlar vid sanering av bilddata i chattar och verktygsresultat (standard: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Reservmodeller för bilder`},help:{"v1-1kgx5i9-1b":`Reservmodeller för bilder i prioritetsordning (leverantör/modell).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Bildmodell`},help:{"v1-dstqyh-2c":`Valfri bildmodell (provider/model) som används när den primära modellen saknar stöd för bildindata.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Bildkvalitet`},help:{"v1-1uyxc5s-6u":`Inställning för bildverktygets mediekomprimering: "auto" anpassar sig efter leverantörens/modellens begränsningar och antalet bilder, "efficient" sparar token och byte, "balanced" behåller den nuvarande balansen och "high" bevarar fler detaljer i skärmbilder och dokumentbilder.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Reservmodeller för bildgenerering`},help:{"v1-oljfk4-1m":`Reservmodeller för bildgenerering i prioritetsordning (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Modell för bildgenerering`},help:{"v1-g4yw0h-2o":`Valfri modell för bildgenerering (provider/model) som används av den gemensamma bildgenereringsfunktionen.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Tidsgräns för bildgenerering (ms)`},help:{"v1-9yesfj-31":`Standardtidsgräns i millisekunder för förfrågningar till leverantören vid image_generate-anrop. timeoutMs för ett enskilt anrop åsidosätter detta.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Reservmodeller för musikgenerering`},help:{"v1-wyg9xe-1m":`Reservmodeller för musikgenerering i prioritetsordning (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Modell för musikgenerering`},help:{"v1-xs1e2h-2o":`Valfri modell för musikgenerering (provider/model) som används av den gemensamma musikgenereringsfunktionen.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Reservmodeller för videogenerering`},help:{"v1-wpbf1e-1m":`Reservmodeller för videogenerering i prioritetsordning (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Modell för videogenerering`},help:{"v1-hfmlbl-2o":`Valfri modell för videogenerering (provider/model) som används av den gemensamma funktionen för videogenerering.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Tidsgräns för videogenerering (ms)`},help:{"v1-1bqj80s-4i":`Standardtidsgräns i millisekunder för förfrågningar till leverantören vid video_generate-anrop. timeoutMs för ett enskilt anrop åsidosätter detta värde, och detta värde åsidosätter leverantörens standardvärden.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Reservmodeller`},help:{"v1-t4djq2-24":`Reservmodeller i prioritetsordning (provider/model). Används när den primära modellen misslyckas.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Primär modell`},help:{"v1-1i8a1v4-v":`Primär modell (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Modellpolicy`},help:{"v1-z0txb7-2e":`Uttrycklig policy för åsidosättande av modellval. Utelämna den eller lämna allow tom för att tillåta alla modeller.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Tillåtna modeller`},help:{"v1-1vy0b57-5c":`Tillåtna modellreferenser vid åsidosättning. Accepterar alias, fullständiga "provider/model"-referenser och prefix med avslutande jokertecken, till exempel "openai/*", "clawrouter/anthropic/*" eller "openai/gpt-*". Om listan är tom tillåts alla modeller.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modeller`},help:{"v1-13cvq23-4i":`Konfigurerad modellkatalog och inställningar per modell. Posterna anger alias, parametrar, metadata för körmiljön och åsidosättningar för kodläge; de begränsar inte åsidosättningar av modellval.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Körmiljö för standardagentens modell`},help:{"v1-6km9kx-41":`Valfri policy för körmiljön per modell för standardagenten. Använd detta för modellspecifika undantag för körmiljön i stället för att ange en körmiljö för hela agenten.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`Körmiljö-ID för standardagentens modell`},help:{"v1-1co96w7-4a":`Körmiljö-ID för standardagentens modell: "openclaw", "auto", ett registrerat ID för ett insticksprograms körningsramverk som "codex", eller ett CLI-backendalias som stöds, som "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Kodläge`},help:{"v1-rsdl5o-6x":`OpenClaw-kodläge för exakt denna leverantör/modell: På tvingar fram aktivering, Av inaktiverar det och Standard ärver tools.codeMode.enabled. Agentspecifika aktiveringsinställningar har företräde. Detta ändrar inte den valda körmiljön eller Codex inbyggda Code Mode.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Omfattning för modellval`},help:{"v1-sj8owq-bl":`Omfattning för chattkommandon och uppdateringar av sessionsmodellen i Gateway utan uttrycklig omfattning: "session" (standard) ändrar endast den aktuella sessionen, "agent" uppdaterar även agentens primära modell och "global" uppdaterar även den gemensamma reservmodellen i agents.defaults.model. Uttryckliga omfatt­ningsflaggor har företräde; ändringar av konfigurerade standardvärden kräver ägar- eller administratörsbehörighet. Telegrams callback-väljare och det inbäddade lokala TUI-gränssnittet gäller fortfarande endast sessionen.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Maximal PDF-storlek (MB)`},help:{"v1-1uig1dr-1u":`Maximal PDF-filstorlek i megabyte för PDF-verktyget (standard: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Maximalt antal PDF-sidor`},help:{"v1-11na7hp-1y":`Maximalt antal PDF-sidor som PDF-verktyget ska bearbeta (standard: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Reservmodeller för PDF`},help:{"v1-89ebd8-19":`Reservmodeller för PDF i prioritetsordning (leverantör/modell).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDF-modell`},help:{"v1-2ktkxt-2y":`Valfri PDF-modell (leverantör/modell) för PDF-analysverktyget. Som standard används imageModel, därefter sessionsmodellen.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Kodförrådets rotkatalog`},help:{"v1-j3sh74-2h":`Valfri rotkatalog för kodförrådet som visas på raden för körningsinformation i systemprompten (åsidosätter automatisk identifiering).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Källportsintervall för sandlådewebbläsarens CDP`},help:{"v1-1jkowdc-2b":`Valfri lista över tillåtna CIDR-intervall för inkommande CDP-trafik vid containergränsen (till exempel 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Nätverk för sandlådewebbläsaren`},help:{"v1-8m74ud-5w":`Docker-nätverk för sandlådewebbläsarens containrar (standard: openclaw-sandbox-browser). Använd det dedikerade standardnätverket eller ett anpassat bryggnätverk; "none" stöds inte eftersom webbläsarstyrning kräver publicerade CDP-portar.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Tillåt anslutning till en containers namnrymd i Docker-sandlådan`},help:{"v1-qm39de-4c":`FARLIG åsidosättning för nödfall som tillåter Docker-nätverksläget container:<id> i sandlådan. Detta ansluter till en annan containers namnrymd och försvagar sandlådans isolering.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU:er för Docker-sandlådan`},help:{"v1-jj0yhw-4k":`Valfritt värde för GPU-genomkoppling i Docker som skickas till --gpus, till exempel "all" eller "device=GPU-uuid". Kräver en kompatibel körmiljö på värden, till exempel NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Mål för äldre sessionslager`},help:{"v1-1xkej6i-2g":`Ägare för uppgraderingskompatibilitet för utfasade huvudagentrader och fasta äldre sessionslager.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Ägare av äldre sessionslager`},help:{"v1-ommm7e-5w":`Agent som äger utfasade huvudagentrader eller rader utan angivet omfång i ett fast äldre sessionslager efter att standardmarkören har tagits bort. Skrivs automatiskt vid uppgradering när den tidigare ägaren varken var main eller den enda agenten.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Valfri standardlista över tillåtna färdigheter som ärvs av agenter som utelämnar agents.entries.*.skills. Utelämna för obegränsade färdigheter, ange [] för att inte ge några färdigheter till agenter som ärver inställningen, och kom ihåg att ett uttryckligt agents.entries.*.skills ersätter denna standardinställning i stället för att slås samman med den.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Hoppa över skapandet av arbetsytans initieringsfiler`},help:{"v1-kbstgw-5v":`Hoppar över automatiskt skapande av initieringsfiler i arbetsytan, men inte injicering av befintliga filer. För den inbäddade körmiljön anger du agents.defaults.contextInjection som "never" för att inaktivera injicering, om inte inställningen åsidosätts för en enskild agent.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Överhoppade valfria initieringsfiler`},help:{"v1-1j2z4yj-4c":`Valfria initieringsfiler som inte ska skapas i agenternas arbetsytor. Giltiga värden: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md accepteras men har ingen effekt).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Startkontext`},help:{"v1-1ugsihy-5o":`Inledning för den första turen som hanteras av körmiljön för "/new" och "/reset" utan argument. Använd detta för att styra om de senaste dagliga minnesfilerna ska förladdas i den första prompten i stället för att be modellen avgöra vad den ska läsa.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Tillämpa startkontext på`},help:{"v1-wav4a5-36":`Väljer vilka återställningskommandon utan argument som får startkontext: inkludera "new", "reset" eller båda (standard: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Antal dagar med dagliga minnen i startkontexten`},help:{"v1-4i5xcm-3p":`Antal daterade minnesfiler som ska läsas in, räknat bakåt från dagens datum i användarens konfigurerade tidszon (standard: 2 för idag + igår).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Aktivera startkontext`},help:{"v1-1d5vz2u-4i":`Aktivera inledningen med startkontext vid rena sessionsåterställningar (standard: true). Inaktivera detta för att återgå till ett beteende som enbart använder prompten, utan dagligt minne som läses in vid körning.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Startkontext: maximalt antal byte per fil`},help:{"v1-11cbian-41":`Maximalt antal byte som tillåts per daglig minnesfil när startkontexten byggs (standard: 16384). Filer som överskrider denna gränssäkra läsgräns hoppas över.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Startkontext: maximalt antal tecken per fil`},help:{"v1-10z53s-2u":`Maximalt antal tecken som behålls från varje inläst daglig minnesfil i startinledningen (standard: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Startkontext: maximalt totalt antal tecken`},help:{"v1-sf676u-54":`Maximalt totalt antal tecken som behålls från alla inlästa dagliga minnesfiler i startinledningen (standard: 2800). Ytterligare filer kapas bort från inledningen när denna gräns nås.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Delegeringsläge för underagenter`},help:{"v1-pqewbk-5o":`Styrkan i delegeringen till underagenter, enbart via prompten. Standardvärdet är "prefer" i varje agents huvudsession och "suggest" i övriga sessioner; "prefer" instruerar tydligt agenten att delegera mer omfattande arbete via sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Mål för systemagenten`},help:{"v1-1wwimo9-34":`Målinställningar för bakgrundsinferens i OpenClaws systemagent och Custodian samt utvalda operatörsläsningar utan avgränsat omfång.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Systemagentens ägare`},help:{"v1-15rvt92-8c":`Agent vars modell och autentiseringsuppgifter används för systemagentens bakgrundskörningar och Custodian-konsultationer. Används även när models.list, models.authStatus, skills.status, doctor.memory.status eller ett infer-CLI-kommando som fastställer agentägd modell- eller autentiseringsstatus utelämnar agentId eller --agent; ett uttryckligt agentId i begäran har alltid företräde.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Skrivindikatorns intervall (sekunder)`},help:{"v1-1y701ox-42":`Styr hur ofta skrivindikatorn hålls aktiv, i sekunder, för alla agenter. Öka värdet för att minska uppdateringsfrekvensen i alla kanaler som stöder skrivindikatorer.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Skrivindikatorns läge`},help:{"v1-m2hvpw-3m":`Styr när skrivindikatorn aktiveras för agenter: "never", "instant", "thinking" eller "message". Ett agentspecifikt typingMode åsidosätter detta standardvärde.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Hjälpmodell`},help:{"v1-1cfea4z-cl":`Valfri modell med lägre kostnad (provider/model, alias eller { primary, fallbacks }) för korta interna uppgifter som att generera titlar och beskriva förlopp. Hjälpmodellens reservmodeller använder samma policy för återförsök, aliasupplösning och modellval som konfigurerade reservmodeller, oberoende av model.fallbacks. Om värdet inte anges används den primära leverantörens deklarerade lilla modell när den finns tillgänglig (annars den primära modellen); ange en tom sträng för att inaktivera routning till hjälpmodellen.`}},"agents%2Edefaults%2EutilityModel%2Efallbacks":{label:{"v1-rlvlnh-n":`Reservmodeller för hjälpmodellen`},help:{"v1-12k3amd-2v":`Ordnad lista över reservmodeller för hjälpmodellen (provider/model eller alias), oberoende av huvudmodellens lista över reservmodeller.`}},"agents%2Edefaults%2EutilityModel%2Eprimary":{label:{"v1-1rpgua8-l":`Primär hjälpmodell`},help:{"v1-11k8uor-1c":`Primär hjälpmodell (leverantör/modell eller alias).`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Reservmodeller för röst`},help:{"v1-faazv4-1b":`Reservmodeller för röst i prioritetsordning (leverantör/modell).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Röstmodell`},help:{"v1-1yeh3h4-2t":`Valfri röstmodell (leverantör/modell) som används för tal, transkribering och röstfunktioner i realtid.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Tidsgräns för röst (ms)`},help:{"v1-1sbergs-32":`Standardtidsgräns i millisekunder för anrop till leverantören vid röstmodellåtgärder när anroparen stöder tidsgränser.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Arbetsyta`},help:{"v1-1u5ipll-5t":`Agentens standardarbetsyta för initierings- och minnesfiler. Används även som arbetskatalog när agents.defaults.cwd inte är angivet. Ange detta uttryckligen vid körning via omslagsskript så att sökvägar tolkas konsekvent.`}},"agents%2Edefaults%2EworkspaceFileMode":{label:{"v1-13trwkt-k":`Behörighetsläge för nya minnesfiler`},help:{"v1-11pw0mp-9b":`Behörigheter för nya DREAMS.md, MEMORY.md och memory/dreaming-rapporter från memory-core: "0600", "0620", "0640" eller "0660". Om inget anges används exakt 0600; konfigurerade lägen respekterar umask på värddatorn som skriver filerna. Befintliga filer, dagligt minne, sessionskorpus och privat tillstånd förblir oförändrade. Behörighet att traversera kataloger och standard-ACL:er måste konfigureras separat.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Agentlista`},help:{"v1-1e0blk1-5i":`Uttrycklig lista över konfigurerade agenter med ID:n och valfria åsidosättningar för modell, verktyg, identitet och arbetsyta. Behåll samma ID:n över tid så att bindningar, godkännanden och sessionsroutning förblir konsekventa.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Äldre agentkörmiljö`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID för äldre agentkörmiljö`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Maximalt antal tecken för agentinitiering`},help:{"v1-rsf1es-4j":`Agentspecifik åsidosättning av maximalt antal tecken i varje initieringsfil i arbetsytan som infogas i agentens systemprompt. Utelämna för att ärva agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Maximalt totalt antal tecken för agentinitiering`},help:{"v1-1bal68p-4y":`Agentspecifik åsidosättning av maximalt totalt antal tecken i alla initieringsfiler i arbetsytan som infogas i agentens systemprompt. Utelämna för att ärva agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2Ecompaction":{label:{"v1-1kqcx8z-g":`Agentkomprimering`},help:{"v1-ioyi1g-2o":`Agentspecifika åsidosättningar för komprimering på klientsidan. Utelämnade inställningar ärvs från agents.defaults.compaction.`}},"agents%2Eentries%2E*%2Ecompaction%2EmaxSummaryChars":{label:{"v1-1vend8r-13":`Maximalt antal tecken i agentens komprimeringssammanfattning`},help:{"v1-1fwu60v-58":`Agentspecifik teckengräns för sparade sammanfattningar på klientsidan (1000–200000), som åsidosätter agents.defaults.compaction.maxSummaryChars. Den aktiva modellens tokenbudget kan kräva en mindre sammanfattning.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Kontextinfogning för agent`},help:{"v1-1j68ys8-50":`Agentspecifik åsidosättning för infogning av arbetsytans initieringsfiler i den inbäddade körmiljön. Utelämna för att ärva agents.defaults.contextInjection. Styr inte CLI-baserad promptförberedelse.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Kontextgränser för agent`},help:{"v1-f1qxq8-3c":`Valfria agentspecifika åsidosättningar för de riktade inställningarna för kontextbudget. Utelämnade fält ärver agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Maximalt antal tecken för agentens memory_get`},help:{"v1-12hlmsv-1v":`Agentspecifik åsidosättning av standardbudgeten för maximalt antal tecken i memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Maximalt antal tecken för agent efter komprimering`},help:{"v1-15s0npd-1w":`Agentspecifik åsidosättning av budgeten för utdrag ur AGENTS.md efter komprimering.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Agentens arbetskatalog`},help:{"v1-mv43ak-6a":`Arbetskatalog för den här agentens svarskörningar. Åsidosätter agents.defaults.cwd men inte cwd som skapats av sessionen; bootstrap- och minnesfiler stannar i arbetsytan. Stöder ~ och relativa sökvägar; en separat cwd kräver en körning utanför sandlådan.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Agentens beslutsmodell`},help:{"v1-1mih8bf-3j":`Beslutsmodell per agent. Om värdet inte anges ärvs agents.defaults.decisionModel; en tom sträng inaktiverar beslutsanrop för den här agenten.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`Agentens inbäddade OpenClaw`},help:{"v1-uoomza-4b":`Valfria åsidosättningar för inbäddat OpenClaw per agent. Använd detta för att aktivera striktare GPT-5-körningsbeteende för specifika agenter utan att ändra den globala standardinställningen.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Körningskontrakt för agentens inbäddade OpenClaw`},help:{"v1-1d1jaoi-7k":`Valfri åsidosättning av körningskontraktet för inbäddat OpenClaw per agent. Ange "strict-agentic" för att aktivera strukturerad planuppföljning och återställning av turer som inte är synlig för användaren för den agenten vid körningar med stöd för modeller i OpenAI/OpenAI Codex GPT-5-familjen, eller "default" för att ärva körmotorns standardbeteende.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Agentens experimentella flaggor`},help:{"v1-1r06jov-2a":`Experimentella flaggor per agent. Utelämnade fält ärver agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Agentens resurssnåla läge för lokala modeller`},help:{"v1-5o3tgx-58":`Agentspecifik åsidosättning för felsökning av resurssnålt läge för lokala modeller. Aktivera endast när en begränsning av valfria verktyg löser ett påvisat modellfel, utan att ta bort verktyg från alla agenter.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Standardinställning för agentens snabbläge`},help:{"v1-ev6028-41":`Valfri agentspecifik standardinställning för snabbläge ("auto", "ultrafast", true eller false). Gäller när ingen åsidosättning av snabbläget har angetts för meddelandet eller sessionen.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Identitetsavatar`},help:{"v1-pzp9gr-1t":`Agentens avatar (sökväg relativ till arbetsytan, http(s)-URL eller data-URI).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Agentens modellpolicy`},help:{"v1-17d5je8-2r":`Agentspecifik policy för åsidosättning av modellval. En uttrycklig lista över tillåtna modeller ersätter standardpolicyn för denna agent.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Tillåtna agentmodeller`},help:{"v1-1enipb-5w":`Tillåtna modellreferenser vid åsidosättning för den här agenten. Accepterar alias, fullständiga "provider/model"-referenser och prefix med avslutande jokertecken, till exempel "provider/*", "provider/namespace/*" eller "provider/family-*". Om listan är tom tillåts alla modeller.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Agentens modellåsidosättningar`},help:{"v1-nld1vq-1v":`Agentspecifika åsidosättningar av modellkatalogen med fullständiga provider/model-ID:n som nycklar.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Körmiljö för agentens modell`},help:{"v1-7b59y-3s":`Valfri modellspecifik körmiljöpolicy för den här agenten. Använd detta för agentspecifika modellundantag i stället för att ange en körmiljö för hela agenten.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Körmiljö-ID för agentens modell`},help:{"v1-1ckfc39-46":`Agentspecifikt körmiljö-ID för modellen: "openclaw", "auto", ett registrerat ID för en plugin-körmiljö, som "codex", eller ett CLI-backendalias som stöds, som "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Kodläge`},help:{"v1-91zu7f-7m":`OpenClaw-kodläge för den här agenten och exakt denna provider/model: På tvingar fram aktivering, Av inaktiverar det och Standard ärver först agentens aktiveringsinställning, sedan den delade modellåsidosättningen och därefter tools.codeMode.enabled. Detta ändrar inte den valda körmiljön eller det inbyggda kodläget i Codex.`}},"agents%2Eentries%2E*%2EnativeRuntimeConsent":{label:{"v1-r2vkr2-11":`Sparade behörigheter för inbyggda körmiljöer`},help:{"v1-1uktqfm-79":`ID:n för körmiljöer som får använda sina inbyggda behörigheter för den här agenten. Nya chattar använder full åtkomst med sandlådan avstängd. Ta bort ett ID för att omedelbart återkalla sparat samtycke; uttryckligt samtycke per chatt påverkas inte. Obligatoriska sandlåde- och arbetsytegränser gäller fortfarande.`}},"agents%2Eentries%2E*%2EnewSessionPermissionMode":{help:{"v1-15v8f6l-5p":`Behörighetsläge som sparas för nya övervakade operatörssessioner med profil när inget uttryckligt läge anges. Ändrar inte befintliga, förgrenade, delegerade eller autonoma sessioner. Full kräver fortfarande operator.admin.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Standardinställning för agentens resonemang`},help:{"v1-13ly0xf-3m":`Valfri standardinställning per agent för resonemangets synlighet (on|off|stream). Gäller när ingen åsidosättning för resonemang har angetts för meddelandet eller sessionen.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Agentens körmiljö`},help:{"v1-avjgkf-3l":`Valfri körmiljöbeskrivning för den här agenten. Använd embedded för standardkörning i OpenClaw eller acp för standardinställningar för externa ACP-körmiljöer.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Agentens ACP-körmiljö`},help:{"v1-91zvdk-3i":`Standardinställningar för den här agentens ACP-körmiljö när runtime.type=acp. ACP-åsidosättningar på bindningsnivå har fortfarande företräde per konversation.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agent i agentens ACP-körmiljö`},help:{"v1-1pm98vp-37":`Valfritt agent-ID för ACP-körmiljön som ska användas för den här OpenClaw-agenten (till exempel codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Agentens ACP-backend`},help:{"v1-1u3cdsg-2n":`Valfri åsidosättning av ACP-backend för den här agentens ACP-sessioner (använder annars globala acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Agentens ACP-arbetskatalog`},help:{"v1-d9p9rf-1t":`Valfri standardarbetskatalog för agentens ACP-sessioner.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Agentens ACP-läge`},help:{"v1-yatuk4-21":`Valfritt standardläge för agentens ACP-sessioner (persistent eller oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Agentens körmiljötyp`},help:{"v1-139fbk6-2r":`Körmiljötyp för agenten: "embedded" (OpenClaws standardkörmiljö) eller "acp" (standardinställningar för ACP-körsystemet).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`CDP-källintervall för agentens sandlådewebbläsare`},help:{"v1-1q1qyso-1d":`Agentspecifik åsidosättning av tillåtelselistan för CDP-källor i CIDR-format.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Nätverk för agentens sandlådewebbläsare`},help:{"v1-13bdfww-4c":`Agentspecifik åsidosättning av Docker-nätverket för sandlådewebbläsaren. Använd ett bryggnätverk; "none" stöds inte eftersom webbläsarstyrning kräver publicerade CDP-portar.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Tillåt anslutning till containerns namnrymd i agentens Docker-sandlåda`},help:{"v1-1xtnseb-2i":`FARLIG agentspecifik åsidosättning för anslutningar till containerns namnrymd i sandlådans Docker-nätverksläge.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`GPU:er för agentens Docker-sandlåda`},help:{"v1-1kek1n2-1t":`Agentspecifik åsidosättning av Docker-inställningen för GPU-genomkoppling till sandlådecontainrar.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Filter för agentens färdigheter`},help:{"v1-igchue-6v":`Valfri lista över tillåtna färdigheter för denna agent. Om den utelämnas ärver agenten agents.defaults.skills om det är angivet; annars förblir färdigheterna obegränsade. Ange [] för inga färdigheter. En uttrycklig lista ersätter ärvda standardvärden helt i stället för att slås samman med dem.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Agentens gränser för Skills`},help:{"v1-1sv10v9-4y":`Valfria agentspecifika åsidosättningar av budgetar för färdighetsundersystemet. Använd detta när en agent behöver en annan promptbudget för färdigheter utan att införa en andra generell sökväg för kontextgränser.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Maximalt antal tecken i agentens prompt för Skills`},help:{"v1-dys63y-52":`Agentspecifik åsidosättning av teckenbudgeten för färdighetsprompten. Detta utökar den befintliga sökvägen skills.limits.maxSkillsPromptChars i stället för att styra samma budget via contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegateToolsTo":{label:{"v1-bycm06-m":`Målagenter för verktygsdelegering`},help:{"v1-y7q6z7-d6":`Exakt angivna, konfigurerade inbyggda målagenter som får utelämna den begärande agentens tools.deny när de startas. Kräver även allowAgents separat. Överlämningar med enbart nekanderegler bevarar alla icke-lokala begränsningar; restriktiva initiala profiler eller tillåtelselistor, eller transportmekanismer som inte stöds, gör att överlämningen nekas i stället för att begränsningarna lättas. Inbyggda hjälpagenter med samma mål behåller sina egna ytterligare gränser. Avsändarbegränsade begäranden och ACP-begäranden använder aldrig denna behörighet. Vid återkallelse återställs den ursprungliga ögonblicksbilden av den begärande agenten.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Delegeringsläge för underagenter`},help:{"v1-1rkgh6p-4s":`Agentspecifik åsidosättning av delegeringsstyrkan för underagenter. Utelämna för att använda "prefer" i agentens huvudsession och "suggest" i övriga sessioner; ett uttryckligt "prefer" eller "suggest" har alltid företräde.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Agentens standardnivå för resonemang`},help:{"v1-173q7vy-43":`Valfri agentspecifik standardnivå för resonemang. Åsidosätter agents.defaults.thinkingDefault för den här agenten när ingen åsidosättning har angetts för meddelandet eller sessionen.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent":{label:{"v1-q7r7ya-o":`Agentens utgående meddelanden`},help:{"v1-xo2o9d-5d":`Policy enbart för agentens utgående meddelanden. Uttryckligen angivna sändningsmål ger inte läsbehörighet till sessioner eller åtkomst till status och omfattas fortfarande av globala begränsningar för deltagande i kommunikation mellan agenter och av sandlådebegränsningar.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent%2Esend":{label:{"v1-1lxwft1-w":`Agentens lista över tillåtna sändningsmål`},help:{"v1-tfolqu-ar":`Agent-id:n eller *-mönster som den här agenten får kontakta med sessions_send, även när tools.sessions.visibility är begränsad. Om värdet utelämnas ärvs synligheten; [] nekar vanliga sändningar mellan agenter. Globala tools.agentToAgent och sandlådebegränsningar gäller fortfarande. Ger inte åtkomst till listning, historik, sökning, status eller bevakning; svar tillhör endast den skickade turen. Åtkomsten till underordnade sessioner som ägs av den begärande parten är oförändrad.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Tillägg till agentens lista över tillåtna verktyg`},help:{"v1-1550ui9-46":`Agentspecifik lista över ytterligare tillåtna verktyg utöver den globala policyn och profilpolicyn. Håll listan begränsad för att undvika att specialiserade agenters behörigheter utökas av misstag.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Agentens verktygspolicy per leverantör`},help:{"v1-mthxv9-4t":`Leverantörsspecifika åsidosättningar av verktygspolicyn per agent för kanalavgränsad funktionskontroll. Använd detta när en enskild agent behöver striktare begränsningar hos en leverantör än hos andra.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Agentens kodläge`},help:{"v1-118t8u5-65":`Alternativ för kodläge per agent. Ett uttryckligt enabled åsidosätter den delade modellens och de globala standardinställningarna för aktivering; en agentspecifik åsidosättning av modellens codeMode har företräde. Övriga alternativ slås samman med tools.codeMode och har företräde utan att ändra aktiveringen.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Agentens tidsgräns för körning (sekunder)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Åsidosättning av agentens GitHub CLI-identitet`},help:{"v1-mjwdh4-38":`Fullständig åsidosättning av hanterad GitHub CLI-identitet och Git-författare för den här agenten. Utelämna den för att ärva systemets identitet.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EallowInSandbox":{label:{"v1-1rxew98-12":`Tillåt agentens GitHub-identitet i sandlådan`},help:{"v1-17rsbdj-6g":`Tillåter agentens hanterade GitHub-autentiseringsuppgifter och Git-författare i dess egen Docker- eller Podman-sandlåda (standard: false). Delat omfång tillåter inte identitetsinjektion; andra backend-system avvisar provisionering. Säkerhetsgranskningen varnar medan detta är aktiverat.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Agentens Git-författaradress`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Agentens Git-författarnamn`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Typ av GitHub-autentiseringsuppgifter för agenten`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Version av agentens GitHub-profil`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Agentens lista över tillåtna meddelandeåtgärder`},help:{"v1-1g5gov3-67":`Lista över tillåtna meddelandeåtgärder per agent för meddelandeverktyget. Ange en minimal lista, till exempel ["send"], för offentliga sandbox-agenter så att läsning, redigering, radering, reaktioner och andra leverantörsspecifika meddelandeåtgärder förblir dolda och blockerade.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Agentens meddelanden mellan kontexter (mellan leverantörer)`},help:{"v1-pehesn-49":`Agentspecifik åsidosättning för att skicka mellan leverantörer. Ärver den globala inställningen (standard: true). Ange false för att blockera meddelanden mellan leverantörer för den här agenten.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Agentens meddelanden mellan kontexter (samma leverantör)`},help:{"v1-s9u09h-4t":`Agentspecifikt meddelandeskydd för att skicka till andra konversationer hos samma leverantör. Ange false för både den här inställningen och allowAcrossProviders för offentliga agenter som endast ska kunna skicka i den aktuella konversationen.`}},"agents%2Eentries%2E*%2Etools%2Eopenclaw":{label:{"v1-1fc612h-p":`Agentens delegering till OpenClaw`},help:{"v1-wjtvl7-25":`Agentspecifik godkännandepolicy för ändringar som delegeras till systemagenten OpenClaw.`}},"agents%2Eentries%2E*%2Etools%2Eopenclaw%2EautoApproveChanges":{label:{"v1-lxqapd-10":`Godkänn agentens delegerade ändringar automatiskt`},help:{"v1-1ok03hg-a1":`Åsidosätter tools.openclaw.autoApproveChanges för den här agenten. true ger ett stående tillstånd för delegerad administration som kan möjliggöra kodkörning på Gateway-värden; false kräver individuellt godkännande, även med fullständig åtkomst. Om inställningen utelämnas ärvs den globala inställningen, därefter den begärande körningens effektiva behörighet. Begränsningar för filsystem, sandlåda och åtgärder gäller fortfarande.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Agentens verktygsprofil`},help:{"v1-1du76ix-57":`Agentspecifik åsidosättning av verktygsprofilvalet när en agent behöver en annan grunduppsättning funktioner. Använd detta sparsamt så att policyskillnader mellan agenter förblir avsiktliga och möjliga att granska.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Agentsvärm`},help:{"v1-420ljs-2c":`Åsidosättning av svärminställningar per agent. Värdena slås samman med och har företräde framför konfigurationen i tools.swarm på toppnivå.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Agentens skrivindikatorläge`},help:{"v1-oxir52-2e":`Åsidosätter standardpolicyn för när skrivindikatorn startar för en agent utan att ändra andra agenter.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Agentens hjälpmodell`},help:{"v1-ccb32g-5u":`Hjälpmodell per agent som en sträng eller { primary, fallbacks }. Om värdet inte anges ärvs agents.defaults.utilityModel. Ett uttryckligt primary utan fallbacks rensar ärvda reservmodeller; en tom sträng inaktiverar routning till hjälpmodeller.`}},"agents%2Eentries%2E*%2EutilityModel%2Efallbacks":{label:{"v1-17pzdxs-t":`Agentens reservmodeller för hjälpmodellen`},help:{"v1-v419a0-2k":`Ordnad lista över reservmodeller för hjälpmodellen per agent. En tom lista rensar ärvda reservmodeller för hjälpmodellen.`}},"agents%2Eentries%2E*%2EutilityModel%2Eprimary":{label:{"v1-lbcmz5-r":`Agentens primära hjälpmodell`},help:{"v1-1d8oent-1z":`Primär hjälpmodell per agent. Utelämna för att ärva den primära standardhjälpmodellen.`}},"agents%2Eentries%2E*%2EworkspaceFileMode":{label:{"v1-13trwkt-k":`Behörighetsläge för nya minnesfiler`},help:{"v1-8mxas6-56":`Åsidosätter agents.defaults.workspaceFileMode för den här agentens nyskapade, människoläsbara minnesutdata. Befintliga filbehörigheter bevaras; värddatorn som skriver filerna tillämpar sin egen umask.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generation för agentägarskap`},help:{"v1-1g8mxd3-8u":`Beständig generationsmarkör för ägarskap i miljöer med flera agenter. "explicit" innebär att bakgrundskanaler, konsultationer med systemagenter, Talk, cron och fristående CLI-åtgärder måste fastställa en ytspecifik ägare eller avbrytas om ingen ägare kan identifieras. OpenClaw anger detta automatiskt när en agentflotta skapas eller migreras. Utelämna det för en ensam agent.`}},approvals:{label:{"v1-1m405m7-9":`Godkännanden`},help:{"v1-4y3in-5w":`Inställningar för att vidarebefordra förfrågningar om godkännande för exec och insticksprogram till chattdestinationer utanför den ursprungliga sessionen. Låt dessa vara inaktiverade om inte operatörer behöver kunna se godkännandeförfrågningar i en separat kanal.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Vidarebefordran av exec-godkännanden`},help:{"v1-1r2mozk-5v":`Samlar inställningar för vidarebefordran av exec-godkännanden, inklusive aktivering, routningsläge, filter och uttryckliga mål. Konfigurera här när godkännandeförfrågningar måste nå driftkanaler i stället för enbart den ursprungliga tråden.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Agentfilter för godkännanden`},help:{"v1-xip9a-4k":'Valfri lista över tillåtna agent-ID:n vars godkännandeförfrågningar får vidarebefordras, till exempel `["primary", "ops-agent"]`. Använd detta för att undvika att skicka aviseringar till kanaler för orelaterade agenter.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Vidarebefordra exec-godkännanden`},help:{"v1-1t0whe8-5s":`Aktiverar vidarebefordran av förfrågningar om exec-godkännande till konfigurerade leveransdestinationer (standard: false). Låt detta vara inaktiverat i miljöer med låg risk och aktivera endast när personer som ska godkänna behöver se förfrågningarna i kanaler.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Läge för vidarebefordran av godkännanden`},help:{"v1-1dedfo4-69":`Styr vart godkännandeförfrågningar skickas: "session" använder den ursprungliga chatten, "targets" använder konfigurerade mål och "both" skickar via båda vägarna. Använd "session" som utgångspunkt och utöka endast när driftarbetsflödet kräver redundans.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Sessionsfilter för godkännanden`},help:{"v1-smeg8e-5u":'Valfria sessionsnyckelfilter som matchas som delsträngar eller regex-liknande mönster, till exempel `["discord:", "^agent:ops:"]`. Använd snäva mönster så att endast avsedda godkännandekontexter vidarebefordras till delade destinationer.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Mål för vidarebefordran av godkännanden`},help:{"v1-17ah848-5u":`Uttryckliga leveransmål som används när vidarebefordringsläget inkluderar mål, vart och ett med kanal- och destinationsuppgifter. Begränsa mållistorna enligt principen om minsta behörighet och validera varje destination innan du aktiverar bred vidarebefordran.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`Konto-ID för godkännandemål`},help:{"v1-16zopng-5e":`Valfri kontoväljare för kanalkonfigurationer med flera konton när godkännanden måste skickas via en specifik kontokontext. Använd detta endast när målkanalen har flera konfigurerade identiteter.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Kanal för godkännandemål`},help:{"v1-ji1igl-59":`Kanal-/leverantörs-ID som används för leverans av vidarebefordrade godkännanden, till exempel discord, slack eller ett kanal-ID för ett insticksprogram. Använd endast giltiga kanal-ID:n så att godkännanden inte misslyckas utan förvarning på grund av okända routningsvägar.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`Tråd-ID för godkännandemål`},help:{"v1-1axynw7-59":`Valfri måltråd eller målämne för kanaler som stöder trådad leverans av vidarebefordrade godkännanden. Använd detta för att hålla godkännandetrafiken i drifttrådar i stället för i huvudkanaler.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Destination för godkännandemål`},help:{"v1-1ijng7e-5n":`Destinationsidentifierare i målkanalen (kanal-ID, användar-ID eller trådrot beroende på leverantör). Kontrollera innebörden för varje leverantör eftersom destinationsformatet skiljer sig mellan kanalintegrationer.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Vidarebefordran av plugin-godkännanden`},help:{"v1-1m6pzxv-6b":`Samlar inställningar för vidarebefordran av plugin-godkännanden, inklusive aktivering, routningsläge, filter och uttryckliga mål. Oberoende av vidarebefordran av körningsgodkännanden. Konfigurera här när förfrågningar om plugin-godkännande måste nå driftkanaler.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Agentfilter för plugin-godkännanden`},help:{"v1-b3test-4y":'Valfri lista över tillåtna agent-ID:n vars plugin-godkännanden får vidarebefordras, till exempel `["primary", "ops-agent"]`. Använd detta för att välja vilka agenters godkännandeförfrågningar som vidarebefordras.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Vidarebefordra plugin-godkännanden`},help:{"v1-1ntctaf-3v":`Aktiverar vidarebefordran av förfrågningar om plugin-godkännande till konfigurerade leveransdestinationer (standard: false). Oberoende av approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Läge för vidarebefordran av plugin-godkännanden`},help:{"v1-1h62vy4-3z":`Styr vart förfrågningar om plugin-godkännande skickas: "session" använder ursprungschatten, "targets" använder konfigurerade mål och "both" skickar till båda.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Sessionsfilter för plugin-godkännanden`},help:{"v1-1eppxmt-57":'Valfria filter för sessionsnycklar som matchas som delsträngar eller mönster i form av reguljära uttryck, till exempel `["discord:", "^agent:ops:"]`. Använd snäva mönster så att endast godkännandeförfrågningar från avsedda sammanhang vidarebefordras.'}},"approvals%2Eplugin%2Eslack":{label:{"v1-o7dlxi-m":`Slack-granskare för plugin-godkännanden`},help:{"v1-1svd0ag-4x":`Granskningspolicy i Slack för plugin-godkännanden. Utelämna standardlistan över godkännare för att behålla kontots behörighetskontroll via allowFrom/defaultTo; ange [] för att neka beslut via Slack som standard.`}},"approvals%2Eplugin%2Eslack%2Eapprovers":{label:{"v1-r39jnl-u":`Standardgranskare i Slack för plugin-godkännanden`},help:{"v1-auy576-5v":`Standardgranskare i Slack för plugin-godkännanden, angivna som råa U/W-användar-ID:n inom det valda Slack-kontot eller som arbetsytespecifika värden i formatet team:<team-id>:user:<user-id>. Plugin- och verktygslistor åsidosätter den här listan för sina egna förfrågningar.`}},"approvals%2Eplugin%2Eslack%2Eplugins":{label:{"v1-13wg4dk-v":`Åsidosättningar av Slack-granskare för plugin-godkännanden`},help:{"v1-16kb0vj-2r":`Åsidosättningar av granskare med det valda inbyggda verktygspluginets ID som nyckel. Verktygsnycklar kodar det råa verktygsnamnet.`}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Mål för vidarebefordran av plugin-godkännanden`},help:{"v1-o92qze-3k":`Uttryckliga leveransmål som används när läget för vidarebefordran av plugin-godkännanden inkluderar targets, vart och ett med kanal- och destinationsuppgifter.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`Konto-ID för plugin-godkännandets mål`},help:{"v1-1wf3lqn-3j":`Valfri kontoväljare för kanalkonfigurationer med flera konton när plugin-godkännanden måste dirigeras via ett specifikt konto.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Målkanal för plugin-godkännanden`},help:{"v1-1mzhzi9-34":`Kanal-/leverantörs-ID som används för leverans av vidarebefordrade plugin-godkännanden, till exempel discord, slack eller ett plugin-kanal-ID.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`Måltrådens ID för plugin-godkännanden`},help:{"v1-1scaw9c-2v":`Valfri måltråd eller målämne för kanaler som stöder trådad leverans av vidarebefordrade plugin-godkännanden.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Måldestination för plugin-godkännanden`},help:{"v1-sh5te1-31":`Destinationsidentifierare i målkanalen (kanal-ID, användar-ID eller trådens rotmeddelande beroende på leverantör).`}},attachments:{label:{"v1-8925gh-b":`Bilagor`},help:{"v1-1xvgkss-40":`Övergripande lagringsbeteende som delas av leverantörer och verktyg som lagrar media. Använd ttlHours när allmänna mellanlagrade media behöver rensas efter en viss tid.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`Lagringstid för bilagor, TTL (timmar)`},help:{"v1-r7enyq-98":`Valfri lagringstid i timmar för sparade medier som hanteras av den allmänna mtime-rensningen. Lämna utan värde för att inaktivera rensningen, eller ange värden som 24 (1 dag) eller 168 (7 dagar) för att regelbundet ta bort äldre mellanlagrade medier. Hanterade utgående medier (bilagor som genererats i chatten) undantas och följer egna lagringsregler som tar hänsyn till SQLite och chattar.`}},audio:{label:{"v1-11wczsp-5":`Ljud`}},auth:{label:{"v1-5xz433-4":`Autentisering`},help:{"v1-1eu3aud-5c":`Rot för autentiseringsprofiler som används för leverantörsuppgifter med flera profiler och en reservordning baserad på väntetider. Håll profilerna minimala och tydliga så att den automatiska reservväxlingen förblir granskningsbar.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Ordning för autentiseringsprofiler`},help:{"v1-1x6kknp-1w":`Ordnade autentiseringsprofil-ID:n per leverantör (används för automatisk reservväxling).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Autentiseringsprofiler`},help:{"v1-kzoqcn-1j":`Namngivna autentiseringsprofiler (leverantör + läge + valfri e-postadress).`}},bindings:{label:{"v1-1hcih9f-8":`Bindningar`},help:{"v1-y7hrzb-4i":`Bindningsregler på toppnivå för routning och beständigt ägarskap av ACP-konversationer. Använd type=route för normal routning och type=acp för beständiga bindningar till ACP-körmiljöer.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Åsidosättningar för ACP-bindning`},help:{"v1-1t4lisi-44":`Valfria ACP-åsidosättningar per bindning för bindings[].type=acp. Detta lager åsidosätter standardvärdena i agents.entries.*.runtime.acp för den matchande konversationen.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend för ACP-bindning`},help:{"v1-rsrbkp-2x":`Åsidosättning av ACP-backend för denna bindning (faller tillbaka på ACP-backend i agentens körmiljö, därefter på globala acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Arbetskatalog för ACP-bindning`},help:{"v1-ngpkj0-1y":`Åsidosättning av arbetskatalog för ACP-sessioner som skapas från denna bindning.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Etikett för ACP-bindning`},help:{"v1-azce82-23":`Lättläst etikett för ACP-status och diagnostik i denna bundna konversation.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Läge för ACP-bindning`},help:{"v1-cgq8xv-1v":`Åsidosättning av ACP-sessionsläge för denna bindning (persistent eller oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`Agent-ID för bindning`},help:{"v1-17ra0cl-4m":`ID för målagenten som tar emot trafik när motsvarande matchningsregel för bindningen uppfylls. Använd endast giltiga konfigurerade agent-ID:n så att routningen inte misslyckas vid körning.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Matchningsregel för bindning`},help:{"v1-sc1w2e-51":`Objekt med matchningsregler som avgör när en bindning gäller, inklusive kanal och valfria begränsningar för konto och motpart. Håll reglerna snäva för att undvika att agenter oavsiktligt tar över i andra sammanhang.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`Konto-ID för bindning`},help:{"v1-1d209g7-56":`Valfri kontoväljare för kanalkonfigurationer med flera konton, så att bindningen endast gäller en identitet. Använd detta när routningen behöver avgränsas till ett konto och lämna det annars oangivet.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Kanal för bindning`},help:{"v1-d22m5-54":"Identifierare för den kanal eller leverantör som bindningen gäller, till exempel `telegram`, `discord` eller ett kanal-ID för ett insticksprogram. Använd den konfigurerade kanalnyckeln exakt så att utvärderingen av bindningen fungerar tillförlitligt."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`Guild-ID för bindning`},help:{"v1-jzzfj1-4x":`Valfri begränsning till ett guild-/server-ID av Discord-typ för utvärdering av bindningar i installationer med flera servrar. Använd detta när samma motpartsidentifierare kan förekomma i olika guilder.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Motpartsmatchning för bindning`},help:{"v1-gcjxff-4i":`Valfri motpartsmatchning för specifika konversationer, inklusive motpartstyp och motparts-ID. Använd detta när endast en direktkonversation, grupp eller kanal ska vara fast kopplad till en agent.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`Motparts-ID för bindning`},help:{"v1-86fbh7-4b":`Konversationsidentifierare som används vid motpartsmatchning, till exempel ett chatt-ID, kanal-ID eller grupp-ID från leverantören. Ange detta exakt för att undvika uteblivna matchningar utan felmeddelande.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Motpartstyp för bindning`},help:{"v1-uufscp-4x":`Motpartens konversationstyp: "direct", "group", "channel" eller äldre "dm" (föråldrat alias för direct). Använd helst "direct" för nya konfigurationer och håll kind i linje med kanalens semantik.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Bindningens roller`},help:{"v1-6s891m-4k":`Valfri rollbaserad filterlista som används av leverantörer som kopplar roller till chattkontexten. Använd detta för att dirigera trafik från privilegierade eller operativa roller till specialiserade agenter.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`Bindningens team-ID`},help:{"v1-hh9ps2-48":`Valfri begränsning till ett team- eller arbetsyte-ID som används av leverantörer som organiserar chattar under team. Lägg till detta när du behöver avgränsa bindningar till en enda arbetsytekontext.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Bindningens session`},help:{"v1-x325l2-4v":`Valfria åsidosättningar av ruttens sessionsinställningar för konversationer som matchas av denna bindning. Använd detta när en snävt avgränsad rutt ska behålla samma agent men hantera sessionens kontinuitet separat på ett annat sätt.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`DM-omfång för bindningens session`},help:{"v1-10sg3xw-4s":`Valfri åsidosättning av DM-sessionens omfång för denna ruttbindning. Behåll till exempel den globala inställningen session.dmScope="main" och använd samtidigt "per-account-channel-peer" för utvalda direktkontakter.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Gruppomfång för bindningens session`},help:{"v1-1ys2u7k-6n":`Valfri åsidosättning av grupp-/kanalsessionens omfång för denna ruttbindning. "per-group" håller matchade rum åtskilda och låter agentens huvudsession bevaka dem i bakgrunden oavsett dmScope; "main" slår samman deras kontext med huvudsessionen och kräver ingen bevakning.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Bindningstyp`},help:{"v1-172mhtk-3o":`Typ av bindning. Använd "route" (eller utelämna för äldre routningsposter) för vanlig routning och "acp" för beständiga ACP-konversationsbindningar.`}},broadcast:{label:{"v1-awqjh0-j":`Agentgrupptrådar`},help:{"v1-1tz72sr-6b":`Använd agentgrupptrådar för att köra flera konfigurerade agenter i en inkommande konversation, var och en i en egen session. Kanalkvalificerade poster stöder ett begränsat antal uppföljningsrundor. Äldre arrayer med WhatsApp-motparter behåller beteendet med en enda körning.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Deltagare och alternativ för agentgrupper`},help:{"v1-1b63zmt-7d":`Använd ett kanalkvalificerat motparts-ID (till exempel "telegram:-100123") för att konfigurera en array med agent-ID:n eller ett strikt objekt med agents, mentionGating, maxRounds och maxTurns. Kvalificerade poster har företräde framför äldre motpartsnycklar för WhatsApp och tillåter högst 16 agenter.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Deltagare i agentgruppen`},help:{"v1-g5o0ky-43":`Deltagande agenters ID:n från agents.entries (högst 16). Varje deltagare använder en egen session för denna kanal, detta konto, denna konversation och denna tråd.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Maximalt antal rundor för agentgruppen`},help:{"v1-i6v4jc-5a":`Maximalt antal rundor per inkommande meddelande, inklusive den första rundan (heltal: 1–4, standard: 1). Uppföljningsrundor delar en begränsad mängd svar från övriga deltagare med angiven avsändare och avslutas när alla deltagare avstår.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Maximalt antal turer för agentgruppen`},help:{"v1-1kiv8dy-72":`Maximalt antal deltagarturer per inkommande meddelande över alla omgångar (heltal: 1–32, standard: agents.length). Platser reserveras före parallell körning; detta begränsar agentturer, inte faktiska meddelandedelar eller verktygssändningar. Budgetar återupptas inte efter omstart.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Val av deltagare i agentgrupp via omnämnanden`},help:{"v1-uay9zu-5u":`Välj endast uttryckligen @omnämnda deltagare om någon matchar; kör annars alla deltagare (standard: true). Enbart namn eller emoji väljer inte deltagare. Kanalernas tillåtelselistor och tillträdesregler gäller fortfarande.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Strategi för agentgrupp`},help:{"v1-p4k9hu-4q":`Körordning för deltagare: "parallel" (standard) kör agenter samtidigt, medan "sequential" kör dem i konfigurerad ordning. Varje omgång slutförs innan nästa börjar.`}},browser:{label:{"v1-13dzmen-7":`Webbläsare`},help:{"v1-5b74wi-5l":`Inställningar för webbläsarkörning med lokal CDP-anslutning eller fjärranslutning via CDP, profilroutning och beteende för skärmbilder/ögonblicksbilder. Behåll standardvärdena om inte ditt automatiseringsflöde kräver anpassade transportinställningar för webbläsaren.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Tillåt import av systemprofil`},help:{"v1-1lsvlxw-5w":`Tillåter macOS-värdar att importera kakor från en lokal systemprofil i Chrome-familjen till en hanterad OpenClaw-webbläsarprofil. Inaktivera detta för att förhindra import av kakor från webbläsarprofiler och den tillhörande samtyckesfrågan för macOS-nyckelringen.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Webbläsarläge för enbart anslutning`},help:{"v1-xaw7xm-4s":`Begränsar webbläsarläget till enbart anslutning utan att starta lokala webbläsarprocesser. Använd detta när alla webbläsarsessioner hanteras externt av en fjärrleverantör av CDP.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`Webbläsarens CDP-URL`},help:{"v1-2n72jb-65":`URL till en CDP/DevTools-ändpunkt som används för att ansluta till en externt hanterad webbläsarinstans. Använd detta för centrala webbläsarvärdar, tunnlar eller anslutning till befintliga sessioner, och begränsa åtkomsten till URL:en till betrodda nätverksvägar.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Webbläsarens standardprofil`},help:{"v1-a6xo96-52":`Namnet på den webbläsarprofil som väljs som standard när anroparen inte uttryckligen väljer en profil. Använd en stabil profil med begränsade behörigheter som standard för att minska risken för oavsiktlig användning av tillstånd från andra kontexter.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Webbläsare aktiverad`},help:{"v1-1m3zcs-5g":`Aktiverar webbläsarfunktioner i Gateway så att webbläsarverktyg och CDP-drivna arbetsflöden kan köras. Inaktivera när webbläsarautomatisering inte behövs för att begränsa tillgängliga funktioner och minska arbetet vid uppstart.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Skriptutvärdering i webbläsaren aktiverad`},help:{"v1-1oa79mq-59":`Aktiverar hjälpfunktioner i webbläsaren för utvärdering av skript under körning där detta stöds. Låt vara inaktiverat om dina arbetsflöden inte kräver utvärderingsfunktioner utöver ögonblicksbilder och navigering.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Sökväg till webbläsarens körbara fil`},help:{"v1-1dshhkn-6g":`Uttrycklig sökväg till webbläsarens körbara fil när automatisk identifiering inte räcker i din värdmiljö. Använd en stabil absolut sökväg, eller en sökväg som börjar med ~ för operativsystemets hemkatalog, så att startbeteendet förblir förutsägbart mellan omstarter.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Relä för webbläsartillägg`},help:{"v1-6ywlwr-4e":`Kompatibilitetsinställningar för autentisering via Chrome-tilläggets relä. Behåll stödet för äldre autentisering endast så länge äldre parkopplade tillägg eller externa CDP-klienter fortfarande behöver det.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Tillåt äldre autentisering för webbläsarrelä`},help:{"v1-pj2e90-63":`Accepterar tillfälligt äldre reläautentisering med Bearer, Basic och token-subprotokoll. Standardvärde: true under en migreringsperiod. Ange false när alla tillägg och externa CDP-klienter använder Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Webbläsarläge utan grafiskt gränssnitt`},help:{"v1-hlkywz-56":`Lokalt hanterade webbläsare körs utan grafiskt gränssnitt som standard. Ange false för att visa ett webbläsarfönster. Webbläsare som använder en befintlig session, ett tillägg, fjärranslutning eller enbart anslutning behåller sitt externt valda läge.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Webbläsarläge utan sandlåda`},help:{"v1-slntux-4w":`Inaktiverar Chromiums flaggor för sandlådeisolering i miljöer där sandlådan inte fungerar vid körning. Låt detta vara avstängt när det är möjligt eftersom skyddet genom processisolering försvagas.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Webbläsarprofiler`},help:{"v1-1x8lf05-51":`Anslutningsmappning för namngivna webbläsarprofiler som används för explicit dirigering till CDP-portar eller URL:er med valfria metadata. Använd konsekventa profilnamn och undvik överlappande definitioner av slutpunkter.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Läge för enbart anslutning för webbläsarprofil`},help:{"v1-2b5zs0-5a":`Profilspecifik åsidosättning för enbart anslutning som hoppar över lokal start av webbläsaren och endast ansluter till en befintlig CDP-slutpunkt. Användbart när en profil hanteras externt men andra startas lokalt.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`CDP-port för webbläsarprofil`},help:{"v1-gx1yiq-49":`Lokal CDP-port per profil som används vid anslutning till webbläsarinstanser via port i stället för URL. Använd unika portar för varje profil för att undvika anslutningskonflikter.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`CDP-URL för webbläsarprofil`},help:{"v1-x491r0-64":`URL till CDP/DevTools-ändpunkten per profil som används för explicit webbläsarroutning efter profilnamn. Använd detta för fjärranslutna CDP-värdar, tunnlar eller profiler med befintliga sessioner som ska ansluta via en aktiv Chrome DevTools-ändpunkt.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Drivrutin för webbläsarprofil`},help:{"v1-17byyx6-5r":`Drivrutinsläge för webbläsaren per profil. Använd "openclaw" (eller det äldre "clawd") för CDP-baserade profiler, "existing-session" för anslutning via Chrome DevTools MCP eller "extension" för det autentiserade reläet via Chrome-tillägget.`}},"browser%2Eprofiles%2E*%2Eengine":{label:{"v1-w0e8eg-m":`Motor för webbläsarprofil`},help:{"v1-1n0drki-ab":`Förinställning för webbläsarmotorns funktioner: "chromium" (standard) eller experimentella "lightpanda" / "kitesurf" för extern webbsurfning via CDP. Externa motorer kräver en uttryckligen angiven ws/wss cdpUrl som är dedikerad till en enda profil samt attachOnly: true. De startar aldrig en lokal webbläsare och tillhandahåller endast de operationer som de stöder. Lightpanda saknar stöd för skärmbilder; Kitesurf renderar skärmbilder med experimentellt stöd.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Sökväg till körbar fil för webbläsarprofil`},help:{"v1-29azyv-4w":`Sökväg till webbläsarens körbara fil per profil för hanterade webbläsarprofiler som startas lokalt. Åsidosätter browser.executablePath och accepterar sökvägar som börjar med ~ för operativsystemets hemkatalog.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Läge utan grafiskt gränssnitt för webbläsarprofil`},help:{"v1-p4jtgv-4u":`Profilspecifik åsidosättning av läget utan grafiskt gränssnitt för lokalt startade webbläsarinstanser. Använd detta när en profil ska köras utan grafiskt gränssnitt utan att tvinga fram browser.headless för alla andra profiler.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Chrome MCP-argument för webbläsarprofil`},help:{"v1-rc45ke-5g":`Extra profilspecifika argument till Chrome DevTools MCP för anslutning till en befintlig session, till exempel --no-usage-statistics. Ändpunktsargument här åsidosätter den inbyggda automatiska anslutningen eller valet av webbläsar-URL.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Chrome MCP-kommando för webbläsarprofil`},help:{"v1-1xpty8o-2h":`Profilspecifikt Chrome DevTools MCP-kommando för anslutning till en befintlig session. Standardvärdet är npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Katalog för användardata för webbläsarprofil`},help:{"v1-5xvgex-9h":`Profilspecifik katalog för Chromium-användardata för anslutning till en befintlig session via Chrome DevTools MCP. Använd detta för Brave, Edge, Chromium eller andra Chrome-profiler än standardprofilen när den inbyggda automatiska anslutningen skulle välja fel katalog för webbläsardata på den valda värden eller webbläsarnoden. Sökvägar som börjar med ~ expanderas till operativsystemets hemkatalog.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Standardinställningar för webbläsarögonblicksbilder`},help:{"v1-v19wdy-4y":`Standardkonfiguration för att ta ögonblicksbilder som används när anropare inte anger uttryckliga alternativ för ögonblicksbilder. Justera detta för ett enhetligt beteende i olika kanaler och automatiseringsflöden.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Läge för webbläsarögonblicksbilder`},help:{"v1-joeyxp-5c":`Standardläge för extrahering av ögonblicksbilder som styr hur sidinnehåll omvandlas för agentens användning. Välj det läge som ger rätt balans mellan läsbarhet, återgivningsnoggrannhet och tokenåtgång för dina arbetsflöden.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`SSRF-policy för webbläsaren`},help:{"v1-1qbp9im-5e":`Skyddsinställningar mot förfalskade förfrågningar på serversidan (SSRF) för hämtningsvägar i webbläsare och nätverk som kan nå interna värdar. Behåll restriktiva standardinställningar i produktionsmiljö och öppna endast för uttryckligen godkända mål.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Tillåtna värdnamn för webbläsaren`},help:{"v1-1rng39-2k":`Exakta värdnamn eller IP-adresser i literalform som tillåts av webbläsarens SSRF-policykontroller. Håll listan så kort som möjligt.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Tillåt IPv6-intervallet för unika lokala adresser i webbläsaren`},help:{"v1-1glx5cy-2c":`Tillåt unika lokala IPv6-adresser (fc00::/7) för betrodda proxymiljöer med simulerade IP-adresser.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Tillåt RFC 2544-intervallet för prestandatestning i webbläsaren`},help:{"v1-10ateu3-2i":`Tillåt IP-adresser i RFC 2544-intervallet för prestandatestning (198.18.0.0/15) för betrodda proxymiljöer med simulerade IP-adresser.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Blockerade värdnamn för webbläsaren`},help:{"v1-nug0we-6k":`Värdnamnsmönster som nekas före DNS och tillåtelseregler, även när åtkomst till privata nätverk är aktiverad. Stöder exakta värdnamn och "*.example.com" för enbart underdomäner; lägg till "example.com" separat för att blockera rotdomänen. Ett tomt eller ej angivet värde lägger inte till några blockeringar.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Tillåt privata nätverk i webbläsaren (riskfyllt)`},help:{"v1-17103pi-4m":`Tillåter åtkomst till privata nätverks adressintervall från webbläsarverktyg. Inaktiverat som standard om inget anges. Aktivera endast för uttryckligen betrodda destinationer i privata nätverk.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Rensning av webbläsarflikar`},help:{"v1-1ctwaad-4y":`Policy för rensning efter bästa förmåga av webbläsarflikar som öppnats av primäragentens sessioner. Behåll aktiverad för att undvika att inaktuella flikar i sandlådor eller hanterade webbläsare samlas i långlivade gatewayinstanser.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Rensning av webbläsarflikar aktiverad`},help:{"v1-4sv97p-3u":`Aktiverar rensning av inaktiva, spårade webbläsarflikar för primäragentens sessioner. Inaktivera endast när externa verktyg helt hanterar flikarnas livscykel.`}},channels:{label:{"v1-1ju93md-8":`Kanaler`},help:{"v1-18k1gv4-50":`Konfigurationer för kanalleverantörer samt gemensamma standardinställningar som styr åtkomstpolicyer och beteende per yta. Håll standardinställningarna centraliserade och åsidosätt dem per leverantör endast vid behov.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Standardinställningar för kanaler`},help:{"v1-uz6veb-4p":`Standardbeteende för kanaler som tillämpas för alla leverantörer när leverantörsspecifika inställningar saknas. Använd detta för att säkerställa en konsekvent grundpolicy före anpassning per leverantör.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Standardskydd mot botloopar`},help:{"v1-1lpznyk-4w":`Standardinställningar för parvist loopskydd hos kanalleverantörer som stöder skydd mot loopar mellan botar. Använd leverantörsspecifika åsidosättningar endast när en kanal behöver en annan budget.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Standardväntetid för botloopar i sekunder`},help:{"v1-1yl5ird-2z":`Väntetid i sekunder som tillämpas på ett par när det överskrider loopbudgeten. Standardvärdet för kanaler som stöder detta är 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Skydd mot botloopar aktiverat som standard`},help:{"v1-3ruik-4r":`Aktiverar som standard skydd mot loopar mellan par för kanaler som stöder detta när meddelanden skrivna av botar kan nå meddelandeförmedlingen. Leverantörer kan fortfarande inaktivera skyddet när botar ignoreras.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Standardantal händelser per tidsfönster för botloopar`},help:{"v1-1u0mdjc-41":`Maximalt antal händelser som ett avsändar-/mottagarpar får utbyta inom det konfigurerade tidsfönstret innan blockeringen börjar. Standardvärdet för kanaler som stöder detta är 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Standardlängd för botloopars tidsfönster i sekunder`},help:{"v1-12xpmen-2m":`Längden på det glidande tidsfönstret i sekunder för loopbudgetar per par. Standardvärdet för kanaler som stöder detta är 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Standardsynlighet för kontext`},help:{"v1-1hze3g1-5o":`Standardsynlighet för kompletterande kontext från hämtade citat, trådar och historik: "all" (behåll all kontext), "allowlist" (endast tillåtna avsändare) eller "allowlist_quote" (tillåtna avsändare + behåll uttryckliga citat).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Standardpolicy för grupper`},help:{"v1-ntl9m4-4n":`Standardpolicy för grupper i alla kanaler: "open", "disabled" eller "allowlist". Behåll "allowlist" för säkrare produktionsmiljöer om inte brett gruppdeltagande är avsikten.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Implicita omnämnanden som standard`},help:{"v1-4gtdyv-48":`Standardpolicy för om svar till botten, citerade botmeddelanden och trådar där botten har deltagit aktiverar meddelandekanaler som stöder detta utan ett uttryckligt omnämnande.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Implicita omnämnanden vid botcitat som standard`},help:{"v1-va1u5v-2v":`Behandla citerade botmeddelanden som implicita omnämnanden som standard. Standardvärdet är true för bakåtkompatibilitet.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Implicita omnämnanden vid svar till botten som standard`},help:{"v1-lm44c3-39":`Behandla svar på bottens egna meddelanden som implicita omnämnanden som standard. Standardvärdet är true för bakåtkompatibilitet.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Implicita omnämnanden vid tråddeltagande som standard`},help:{"v1-160205h-3o":`Behandla uppföljningar i trådar där botten har deltagit som implicita omnämnanden som standard. Standardvärdet är true för bakåtkompatibilitet.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Modellåsidosättningar per kanal`},help:{"v1-1b01spx-2p":`Mappa leverantör -> kanal-id / DM-motparts-id -> modellåsidosättning (värdena är leverantör/modell eller alias).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Molnarbetare`},help:{"v1-10carc4-5v":`Valfria molnarbetarprofiler för tillfälliga fjärrmiljöer. Om det här avsnittet utelämnas eller saknar profiler går det fortfarande inte att skapa molnarbetare, och befintligt beteende för gateway-/nodstatus förblir oförändrat.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Skrivbord för molnarbetare (Labs)`},help:{"v1-sly85c-3k":`Aktiverar det experimentella gränssnittet worker.desktop.observe och panelen Skrivbord i webbappen för molnarbetarmiljöer med skrivbordsstöd.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Pool med förberedda molnarbetare`},help:{"v1-rw51o5-6b":`Gränser för förberedda molnarbetare som hålls redo för senare sessioner. Reserver debiteras som körande maskiner tills leverantörens rensning är klar. Deras fasta förfallotid följer den faktiska projektefterfrågan och leverantörens befintliga inaktivitetspolicy.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Tak för molnarbetare i beredskap`},help:{"v1-1mpd1dt-7u":`Gemensamt tak för hela Gateway för otilldelade, förberedda molnarbetare över alla projekt och profiler (standard: 4). Arbetare som förbereds och reserver vars rensning inte har bekräftats räknas mot taket. Ange 0 för att avveckla otilldelade reserver och inaktivera påfyllning, men behålla återanvändning av ögonblicksbilder och aktiva sessioner.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Molnarbetarprofiler`},help:{"v1-eii67l-3j":`Namngivna molnarbetarprofiler. Varje profil väljer en arbetarleverantör som registrerats av ett insticksprogram och innehåller leverantörsspecifika inställningar.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Molnarbetarprofil`},help:{"v1-1v2w7jl-4u":`En molnarbetarprofil som väljs med namn när en miljö skapas. Lagra leverantörens autentiseringsuppgifter i referenser som stöds i stället för att bädda in hemliga uppgifter i det här blocket.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Installationsmetod för molnarbetare`},help:{"v1-blrtbf-74":`Installationsmetod för arbetare: "bundle" (standard) överför gatewayens installerade bygge med innehållshash och stöder publicerade versioner, utvecklingsversioner och opublicerade versioner; "npm" installerar exakt samma version som gatewayen och är endast tillgängligt när den versionen har publicerats.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Leverantör av molnarbetare`},help:{"v1-1p4s4c1-44":`Leverantörs-id för arbetare som registrerats av ett insticksprogram. Det konfigurerade insticksprogrammet måste exponera detta id innan gatewayen kan etablera miljöer från profilen.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Målantal för reserv av förberedda molnarbetare`},help:{"v1-1nwve9s-7w":`Önskat antal otilldelade, förberedda arbetare per kvalificerat projekt som använder den här profilen (standard: 1), begränsat av det gemensamma taket för poolen av förberedda arbetare i Gateway. Ange 0 för att inaktivera profilens reserver men behålla återanvändning av ögonblicksbilder. Arbetare som håller på att förberedas och reserver vars rensning inte har bekräftats räknas med i målantalet.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Inställningar för leverantör av molnarbetare`},help:{"v1-mq7u32-4j":`Leverantörsspecifika inställningar som valideras av det valda insticksprogrammet. Använd SecretRef-objekt för värden som innehåller hemligheter; opaka inställningar får inte automatisk upplösning av hemligheter.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Inaktivitetstid innan molnarbetare pausas`},help:{"v1-1keuwgh-4w":`Frigör automatiskt en inaktiv molnarbetare efter den här tiden, till exempel 45m eller 2h; nästa meddelande etablerar en ersättare. Minimum: 1m. Lämna värdet oangivet för att låta arbetarna fortsätta köras.`}},"cloudWorkers%2Eprofiles%2E*%2EworkspaceDurability":{label:{"v1-1yi22sz-v":`Beständighet för kodarkivets arbetsyta`},help:{"v1-1r6ow8r-6o":`Speglas som standard. Kodarkiv med kvarhållen disk kräver en leverantör av hanterade noder med exakt resursmatchning och ett uttryckligt, ändligt beräkningsfönster i sekunder. Den ursprungliga disken förblir den auktoritativa källan mellan turerna; Flytta till Gateway exporterar och avvecklar den.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Projektprofiler för molnarbetare`},help:{"v1-1kkfrif-46":`Standardprofilnamn för molnarbetare med normaliserad arkividentitet i gemener (host/owner/repo) som nyckel. Explicit angivna profil-id:n vid tilldelning har företräde.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Projektprofil för molnarbetare`},help:{"v1-1mux5u0-30":`Profilnamn för molnarbetare som används som standard när origin för en sessions arbetsträd matchar denna arkividentitet.`}},"cloudWorkers%2ErequiredProfile":{label:{"v1-1rqoa9j-n":`Obligatorisk arbetarprofil`},help:{"v1-1q30qf7-57":`Kräv att varje session körs med denna arbetarprofil. Sessioner placeras automatiskt och kan inte använda körning på Gateway som reserv. Otillgängliga arbetare blockerar turer, inte starten av Gateway.`}},commands:{label:{"v1-15x4mpf-8":`Kommandon`},help:{"v1-1gi0dr2-5a":`Styr gränssnitt för chattkommandon, ägarbegränsningar och åtkomst till kommandon med utökade behörigheter hos olika leverantörer. Behåll standardinställningarna om du inte behöver striktare operatörskontroller eller bredare kommandotillgänglighet.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Regler för utökad kommandoåtkomst`},help:{"v1-7azkw-5g":`Definierar regler per kanal och avsändare för att tillåta kommandon med utökade behörigheter i kommandogränssnitt på ägarnivå. Använd snävt avgränsade, leverantörsspecifika identiteter så att privilegierade kommandon inte blir tillgängliga för breda grupper av chattanvändare.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Tillåt chattkommando för Bash`},help:{"v1-83ah7w-36":"Tillåt chattkommandot för bash (`!`; alias `/bash`) att köra skalkommandon på värden (standard: false; kräver tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Förgrundstid för Bash (ms)`},help:{"v1-1o0o4dw-2c":`Hur länge bash väntar innan körningen flyttas till bakgrunden (standard: 2000; 0 flyttar den till bakgrunden direkt).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Tillåt /config`},help:{"v1-151bb7c-21":`Tillåt chattkommandot /config att läsa och skriva konfiguration på disk (standard: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Tillåt /debug`},help:{"v1-y1lc3j-1y":`Tillåt chattkommandot /debug för åsidosättningar som endast gäller under körning (standard: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Tillåt /mcp`},help:{"v1-1rtwcgd-2o":`Tillåt chattkommandot /mcp att hantera OpenClaws MCP-serverkonfiguration under mcp.servers (standard: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Inbyggda kommandon`},help:{"v1-dighr2-5n":`Registrerar inbyggda snedstrecks- och menykommandon i kanaler som stöder kommandoregistrering (Discord, Slack, Telegram). Låt detta vara aktiverat så att kommandona är lätta att hitta, om du inte avsiktligt använder enbart textbaserade kommandoflöden.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Inbyggda färdighetskommandon`},help:{"v1-19gtqci-5h":`Registrerar inbyggda färdighetskommandon så att användare kan anropa färdigheter direkt från leverantörens kommandomenyer där det stöds. Anpassa detta efter din färdighetspolicy så att tillgängliga kommandon motsvarar operatörernas förväntningar.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Kommandoägare`},help:{"v1-1di38gv-3y":`Uttrycklig lista över tillåtna ägare för kommandon som är begränsade till ägare. Använd kanalspecifika ID:n (valfritt med prefix som "whatsapp:+15551234567"). '*' ignoreras.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Tillåt /plugins`},help:{"v1-akwy9y-33":`Tillåt chattkommandot /plugins att lista upptäckta insticksprogram och aktivera eller inaktivera dem i konfigurationen (standard: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Tillåt omstart`},help:{"v1-m32fv2-27":`Tillåt /restart, /update och externa omstartsbegäranden via SIGUSR2 (standard: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Textkommandon`},help:{"v1-1utu76s-5j":`Aktiverar tolkning av textkommandon i chattinmatning utöver inbyggda kommandogränssnitt där sådana finns. Låt detta vara aktiverat för kompatibilitet mellan kanaler som inte stöder inbyggd kommandoregistrering.`}},cron:{label:{"v1-1qlte4b-b":`Automatiseringar`},help:{"v1-4md8ic-5u":`Globala schemaläggningsinställningar för lagrade automatiseringar, samtidiga körningar, reservleverans och lagringstid för körningssessioner. Behåll standardvärdena om du inte skalar upp automatiseringsvolymen eller integrerar externa webhook-mottagare.`}},"cron%2Eagents":{label:{"v1-13sapf2-u":`Standardinställningar för automatiseringar per agent`},help:{"v1-15ynqdo-4x":`Standardinställningar för automatiseringar per agent, med agent-id som nyckel. Varje automatisering använder posten för sin faktiska agent (dess agentId, annars agenten i dess sessionsnyckel, annars standardagenten).`}},"cron%2Eagents%2E*%2Edelivery":{label:{"v1-106qeoh-y":`Standardleverans för agentens automatiseringar`},help:{"v1-fgez3q-5r":"Standarddestination för meddelanden från den här agentens automatiseringar som inte anger någon rutt. Ersätter `cron.delivery` helt för den här agenten; fälten slås inte samman. En standardinställning för personen som skapade jobbet har företräde."}},"cron%2Eagents%2E*%2EfailureAlert":{label:{"v1-15hpccn-11":`Rutt för felvarningar för agentens automatiseringar`},help:{"v1-ppqxgd-6j":"Standardrutt för felvarningar (`mode`, `channel`, `to`, `threadId`, `accountId`) för den här agentens automatiseringar. Ersätter ruttfälten i `cron.failureAlert` helt; `enabled`, `after`, `cooldownMs` och `includeSkipped` förblir gemensamma för hela Gateway."}},"cron%2Ecreators":{label:{"v1-8luomx-w":`Standardinställningar för automatiseringar per skapare`},help:{"v1-12liwzq-9q":`Standardinställningar för automatiseringar per skapare, med Gateway-profil-id för personen som skapade automatiseringen som nyckel. Gäller endast när automatiseringen registrerar en personprofil som skapare (direkt eller som den profil som delegerade skapandet till en agent); äldre automatiseringar och skapare som enbart är kanaler, är okända eller är agenter eller system använder ingen skaparpost. Nycklar måste matcha exakt.`}},"cron%2Ecreators%2E*%2Edelivery":{label:{"v1-85aipy-10":`Standardleverans för skaparens automatiseringar`},help:{"v1-ybgvfk-4j":"Standarddestination för meddelanden från den här personens automatiseringar som inte anger någon rutt. Har företräde framför `cron.agents.<agentId>.delivery` och `cron.delivery`; ersätter dem helt."}},"cron%2Ecreators%2E*%2EfailureAlert":{label:{"v1-1e8apq2-13":`Rutt för felaviseringar för skaparens automatiseringar`},help:{"v1-mlj76p-7m":"Standardrutt för felaviseringar (`mode`, `channel`, `to`, `threadId`, `accountId`) för den här personens automatiseringar. Har företräde framför den ägande agentens rutt och ersätter ruttfälten i `cron.failureAlert` i sin helhet; `enabled`, `after`, `cooldownMs` och `includeSkipped` förblir gemensamma för hela Gateway."}},"cron%2EdefaultTools":{label:{"v1-huhclk-o":`Standardverktyg för automatisering`},help:{"v1-1x80rr1-7x":`Verktyg som läggs till när automatiseringsverktyget skapar eller uttryckligen ändrar en toolsAllow-lista som inte är tom, före kontroller av skaparens policy och godkännande. Om inget anges läggs inget till. Använd toolsAllowMode: "exact" i den begäran för att avstå; [] förblir utan verktyg. Befintliga jobb och orelaterade ändringar påverkas inte.`}},"cron%2Edelivery":{label:{"v1-11v82ye-s":`Standardleverans för automatiseringar`},help:{"v1-1rndf98-aj":"Standarddestination för aviseringar, gemensam för hela Gateway, för automatiseringar som inte anger någon egen rutt (ingen annan kanal än `last`, inget `to`, `threadId` eller `accountId` och ingen ägarinriktning). Den ersätter den sparade sessionsrutten vid körning och gäller aldrig för leverans med `none` eller `webhook`. Ett standardvärde i `cron.creators.<profileId>.delivery` eller `cron.agents.<agentId>.delivery` har företräde framför detta."}},"cron%2Edelivery%2EaccountId":{label:{"v1-192kjm5-10":`Standardkonto för leverans av automatiseringar`},help:{"v1-1ishqby-2j":`Valfritt kanalkonto för standarddestinationen när kanalen har flera konton.`}},"cron%2Edelivery%2Echannel":{label:{"v1-b4tjph-10":`Standardkanal för leverans av automatiseringar`},help:{"v1-x3hpfs-39":"Kanal för standarddestinationen, till exempel `telegram`. Utelämna för att använda `last` för att bestämma kanal utifrån standardmottagaren."}},"cron%2Edelivery%2EthreadId":{label:{"v1-16jecza-z":`Standardtråd för leverans av automatiseringar`},help:{"v1-12h3hbw-2g":`Valfri tråd eller valfritt forumämne för standarddestinationen, till exempel ett ämnes-id i Telegram.`}},"cron%2Edelivery%2Eto":{label:{"v1-1iipxgp-12":`Standardmottagare för leverans av automatiseringar`},help:{"v1-1odj9jz-3j":"Mottagare för standarddestinationen, angiven med kanalens målsyntax (till exempel ett chatt-id i Telegram som `-100123456789`)."}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automatiseringar aktiverade`},help:{"v1-y8otx6-5i":`Aktiverar körning av automatiseringar för lagrade scheman som hanteras av Gateway. Låt detta vara aktiverat för normala påminnelse- och automatiseringsflöden, och inaktivera det endast för att pausa all automatiseringskörning utan att ta bort jobb.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Lagringstid för automatiseringssessioner`},help:{"v1-4wagu6-7e":"Styr hur länge slutförda automatiseringssessioner sparas före rensning (`24h`, `7d`, `1h30m` eller `false` för att inaktivera rensning; en varaktighet på noll, till exempel `0h`, inaktiverar också rensning; standard: `24h`). Använd kortare lagringstid för att begränsa lagringstillväxten vid scheman med hög körningsfrekvens."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Hoppa över missade återkommande automatiseringar`},help:{"v1-w9wfmo-66":`Hoppar över missade återkommande cron/every-körningstillfällen när Gateway startar och schemalägger nästa framtida tillfälle i stället för att köra ikapp. Standard: false. Aktivera för att undvika inaktuella påminnelser efter driftavbrott; engångsjobb av typen at körs fortfarande ikapp.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`SSRF-policy för automatiseringars webhooks`},help:{"v1-1xlfqnu-5h":`SSRF-policy som tillämpas på varje utgående webhook för automatiseringar. Privata adresser, loopback-adresser, länklokala adresser och interna mål förblir blockerade om inte denna policy uttryckligen tillåter dem. Lämna utan värde för strikt leveranskontroll.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Tillåtna värdnamn för automatiseringars webhooks`},help:{"v1-1i94hyz-3n":`Exakta värdnamn eller IP-adresser som tillåts för leverans av automatiseringars webhooks, inklusive mål som annars blockeras. Håll listan så kort som möjligt.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Tillåt IPv6-intervallet för unika lokala adresser för automatiseringars webhooks`},help:{"v1-rke0oj-3b":`Tillåter automatiseringars webhooks till unika lokala IPv6-adresser (fc00::/7). Använd endast med betrodda proxymiljöer med falska IP-adresser.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Tillåt RFC 2544-intervallet för prestandatestning för automatiseringars webhooks`},help:{"v1-x1usg4-3h":`Tillåter automatiseringars webhooks till IP-adresser i RFC 2544-intervallet för prestandatestning (198.18.0.0/15). Använd endast med betrodda proxymiljöer med falska IP-adresser.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Blockerade värdnamn för automatiseringars webhooks`},help:{"v1-16cv1ic-6a":`Värdnamnsmönster som nekas före DNS och tillåtelseregler vid leverans av automatiseringars webhooks. Stöder exakta värdnamn och "*.example.com" för enbart underdomäner; lägg till "example.com" separat för att blockera rotdomänen. Om värdet är tomt eller inte anges läggs inga blockeringar till.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Tillåt privat nätverk för automatiseringars webhooks (riskfyllt)`},help:{"v1-1n9710c-3t":`Tillåter webhooks för automatiseringar till privata och interna nätverksmål. Låt vara inaktiverat om inte alla konfigurerade webhook-destinationer är betrodda.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Bearer-token för automatiseringars webhooks`},help:{"v1-1l90hxg-5l":`Bearer-token som bifogas POST-leveranser till automatiseringars webhooks när webhook-läget används. Använd helst substitution med hemligheter eller miljövariabler och rotera denna token regelbundet om delade webhook-slutpunkter är åtkomliga från internet.`}},database:{label:{"v1-1ur2pjs-8":`Databas`},help:{"v1-zxclpq-90":`Val av databasmotor. SQLite är standard; PostgreSQL är ett alternativ som stöds för de fem konfigurerbara familjerna. Doctor rapporterar konfigurerade och observerade motorer och varnar om avvikelser, saknade funktioner eller otillgängliga datalager. Se driftguiden för PostgreSQL för begränsningar i kvalificeringen av plattformar och uppgraderingar.`}},"database%2Eengine":{label:{"v1-we5l2i-f":`Databasmotor`},help:{"v1-6hsgz2-6j":`Standardmotor för datalager (standard: sqlite). PostgreSQL stöder state, agent, workboard, logbook och team-reports om inte database.families åsidosätter dessa inställningar; säkerhetslager förblir lokala SQLite-lager. Byte av motor migrerar inte befintliga data.`}},"database%2Efamilies":{label:{"v1-1xrm7s9-n":`Databasmotorer per familj`},help:{"v1-12i1jst-75":`Valfria åsidosättningar av motor för state, agent, workboard, logbook och team-reports. Varje åsidosättning kräver engine. Familjerna state och agent kan använda olika motorer; lokala säkerhetsjournaler är inte konfigurerbara. Alla PostgreSQL-familjer delar database.postgres.`}},"database%2Efamilies%2Eagent%2Eengine":{label:{"v1-1e7sns0-m":`Databasmotor för familj`},help:{"v1-fv44v3-77":`Åsidosätt database.engine för den här familjen. Byte av motor kräver database port --family och en omstart; ändringar i konfigurationen migrerar inte befintliga data. Säkerhetskopiering/återställning med blandade motorer bevarar motorn för varje datalager, och uppdateringar kräver att den nya versionen stöder familjen.`}},"database%2Efamilies%2Elogbook%2Eengine":{label:{"v1-1e7sns0-m":`Databasmotor för familj`},help:{"v1-fv44v3-77":`Åsidosätt database.engine för den här familjen. Byte av motor kräver database port --family och en omstart; ändringar i konfigurationen migrerar inte befintliga data. Säkerhetskopiering/återställning med blandade motorer bevarar motorn för varje datalager, och uppdateringar kräver att den nya versionen stöder familjen.`}},"database%2Efamilies%2Estate%2Eengine":{label:{"v1-1e7sns0-m":`Databasmotor för familj`},help:{"v1-fv44v3-77":`Åsidosätt database.engine för den här familjen. Byte av motor kräver database port --family och en omstart; ändringar i konfigurationen migrerar inte befintliga data. Säkerhetskopiering/återställning med blandade motorer bevarar motorn för varje datalager, och uppdateringar kräver att den nya versionen stöder familjen.`}},"database%2Efamilies%2Eteam-reports%2Eengine":{label:{"v1-1e7sns0-m":`Databasmotor för familj`},help:{"v1-fv44v3-77":`Åsidosätt database.engine för den här familjen. Byte av motor kräver database port --family och en omstart; ändringar i konfigurationen migrerar inte befintliga data. Säkerhetskopiering/återställning med blandade motorer bevarar motorn för varje datalager, och uppdateringar kräver att den nya versionen stöder familjen.`}},"database%2Efamilies%2Eworkboard%2Eengine":{label:{"v1-1e7sns0-m":`Databasmotor för familj`},help:{"v1-fv44v3-77":`Åsidosätt database.engine för den här familjen. Att byta motor kräver database port --family och en omstart; att redigera konfigurationen migrerar inte befintliga data. Säkerhetskopiering och återställning med blandade motorer bevarar varje datalagers motor, och uppdateringar kräver att uppdateringskandidaten stöder familjen.`}},"database%2Epostgres":{label:{"v1-11caiz7-a":`PostgreSQL`},help:{"v1-1hstnlv-7j":`PostgreSQL-anslutning och schemanamngivning. PostgreSQL 16–18 är verifierade för drift; andra tillåtna huvudversioner förblir experimentella tills överensstämmelsen har verifierats. Säkerhetskopiera varje lagringsschema tillsammans med dess lokala SQLite-ankare. Se driftguiden för PostgreSQL för begränsningar av vilka driftsättningar som har verifierats.`}},"database%2Epostgres%2Econnection":{label:{"v1-17ej0zp-l":`PostgreSQL-anslutning`},help:{"v1-1gbko0p-9s":`Delad PostgreSQL-DSN, krävs när någon familjs aktiva motor är postgres. Stöder SecretRefs av typerna env, file och exec samt TLS-anslutningar; se driftguiden för PostgreSQL för konfiguration och begränsningar för verifierade miljöer. Referenser som stöds av ett datalager kan inte användas för att initiera databasen. Värden slår upp den en gång för databasens arbetsprocesser. Anslutningsfel leder aldrig till att SQLite används som reserv.`}},"database%2Epostgres%2Eownership":{label:{"v1-87ucg-s":`Ägarskap för Gateway-tillstånd i PostgreSQL`},help:{"v1-1e7fkqn-cj":`Omfattning för ägarskap av Gateway-tillstånd (standard: state-directory, en lokal låsfil). installation håller även ett rådgivande sessionslås i PostgreSQL med databasen och schemaprefixet som nyckel, så att en andra Gateway eller underhållsägare för samma installation nekas på alla värdar. Om sessionen förloras stoppas Gateway. Kräver att varje konfigurerbar familj använder postgres. Lagringsankare och andra lokala filer förblir oförändrade; se driftguiden för PostgreSQL.`}},"database%2Epostgres%2ErecoveryCaptures":{label:{"v1-dlnk9p-s":`Återställningskopior för PostgreSQL`},help:{"v1-1qes8ml-9m":`Var återställningskopior för uppdateringar och återställning med Doctor lagrar PostgreSQL-rader (standard: portable). portable skriver en lokal SQLite-exportavbildning. server behåller raderna i ett restore_-schema i samma databas och skriver endast ankaret och manifestet lokalt. Det sparar lokalt diskutrymme och exporttid, men kopiorna går förlorade om servern förloras. Användarsäkerhetskopior förblir portabla.`}},"database%2Epostgres%2EschemaPrefix":{label:{"v1-1s0mt2q-o":`Schemaprefix för PostgreSQL`},help:{"v1-1a5738a-7o":`Prefix för nya lagringsscheman i PostgreSQL (standard: openclaw). Använd 1–27 gemener, siffror eller understreck, med en bokstav eller ett understreck först. Prefixet pg och prefix som börjar med pg_ genererar reserverade schemanamn i PostgreSQL. Befintliga ankare behåller sitt schema.`}},desktop:{label:{"v1-rs698z-7":`Skrivbord`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Lokalt skrivbord`},help:{"v1-99weio-30":`Skrivbordsövervakning för parkopplade noder eller den experimentella Gateway-värdkällan, med en lokal VNC-server som grund.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Skrivbordsdelning`},help:{"v1-m9lbcj-83":`Aktiverar den här datorns skrivbordskälla. Parkopplade macOS-, Windows- och Linux-noder är aktiverade som standard; en uttrycklig delningsinställning i skrivbordsappen har företräde. Gateway-värdens Labs-källa är inaktiverad som standard och tillämpar ändringar direkt. Starta om en parkopplad nod efter att du har ändrat dess skrivbordskonfiguration.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Hanterat skrivbord på Linux-värd`},help:{"v1-1r7n22m-49":`Kör och övervakar ett skärmlöst TigerVNC/XFCE-skrivbord på Linux som endast är tillgängligt via loopback. En uttryckligen angiven port eller en befintlig VNC-server på standardporten har fortfarande företräde.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Lokal VNC-lösenordsfil`},help:{"v1-1m5lsox-37":`Absolut sökväg till VNC-lösenordsfilen. Utelämna på macOS för att ange kontouppgifter när skrivbordsvisaren öppnas.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Lokal VNC-port`},help:{"v1-1ku4w9b-2b":`RFB-port på loopback för en VNC-server som redan körs på den här datorn (standard: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnostik`},help:{"v1-1d5rnym-5p":`Diagnostikinställningar för riktad spårning, telemetriexport och cachegranskning vid felsökning. Håll den grundläggande diagnostiken minimal i produktion och aktivera mer detaljerad diagnostik endast när du undersöker problem.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Cachespårning`},help:{"v1-10523zm-5b":`Loggningsinställningar för cachespårning som visar cachebeslut och nyttolastens kontext vid inbäddade körningar. Aktivera tillfälligt för felsökning och inaktivera efteråt för att minska mängden känsliga uppgifter i loggarna.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Cachespårning aktiverad`},help:{"v1-2c1umi-1v":`Logga ögonblicksbilder av cachespårning för inbäddade agentkörningar (standard: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnostik aktiverad`},help:{"v1-a46pxt-4h":`Huvudreglage för diagnostikinstrumenteringens utdata i loggar och telemetrikopplingar. Aktiverat som standard; ange false endast i mycket begränsade miljöer.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Diagnostikflaggor`},help:{"v1-x4w5ok-33":`Aktivera riktade diagnostikloggar med flaggor (t.ex. ["telegram.http"]). Stöder jokertecken som "telegram.*" eller "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Exportinställningar för OpenTelemetry för spårningar, mätvärden och loggar som genereras av Gateway-komponenter. Använd detta vid integrering med centraliserade backend-system för observerbarhet och pipelines för distribuerad spårning.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Innehållsinsamling för OpenTelemetry`},help:{"v1-19tid4t-2t":`Valfri insamling av innehåll i OTEL-spann. Avstängd som standard; true samlar in verktygsinnehåll och innehåll från meddelanden som inte är systemmeddelanden.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry aktiverat`},help:{"v1-193bm0-5b":`Aktiverar OpenTelemetry-exportens pipeline för spårningar, mätvärden och loggar utifrån konfigurerade inställningar för slutpunkt och protokoll. Låt vara inaktiverat om inte insamlarens slutpunkt och autentisering är fullständigt konfigurerade.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Slutpunkt för OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL till insamlarens slutpunkt som används för OpenTelemetry-export, inklusive schema och port. Använd en nåbar och betrodd insamlarslutpunkt och övervaka inläsningsfel efter utrullning.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Tömningsintervall för OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Intervall i millisekunder för periodisk tömning av telemetri från buffertar till insamlaren. Öka värdet för att minska exporttrafiken, eller sänk det för snabbare insyn under aktiv incidenthantering.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`HTTP-huvuden för OpenTelemetry`},help:{"v1-s26t2a-52":`Ytterligare HTTP-huvuden som skickas med exportförfrågningar från OpenTelemetry, ofta för klientautentisering eller routning. Lagra hemligheter i värden som hämtas från miljövariabler och undvik onödigt många huvuden.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`OpenTelemetry-loggar aktiverade`},help:{"v1-12wo6rv-4k":`Aktivera export av loggsignaler via OpenTelemetry utöver lokala loggmål. Använd detta när centraliserad loggkorrelation krävs mellan tjänster och agenter.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Slutpunkt för OpenTelemetry-loggar`},help:{"v1-1vgzldu-40":`Signalspecifik OTLP/HTTP-slutpunkt för loggar. När den är angiven åsidosätter den diagnostics.otel.endpoint och OTEL_EXPORTER_OTLP_ENDPOINT endast för loggexport.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Exportör för OpenTelemetry-loggar`},help:{"v1-9bzywd-5q":`Loggexportmål för diagnostics.otel.logs. Använd "otlp" för den konfigurerade OTLP-slutpunkten för loggar, "stdout" för en JSON-post per stdout-rad i loggpipelines för containrar och "both" när båda målen behövs.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Prefix för OpenTelemetry-måttnamn`},help:{"v1-1epdpi9-b2":`Ersätter standardprefixet "openclaw." i namn på mätvärden som tillhör OpenClaw. Använd en tom sträng för att ta bort prefixet, eller upp till 128 ASCII-bokstäver, siffror, understreck, punkter, bindestreck och snedstreck med en bokstav först. Inkludera eventuell avgränsare, till exempel "acme."; standardnamn på mätvärden av typen gen_ai.* ändras inte. Om du ändrar detta värde måste du uppdatera instrumentpaneler och larm som använder de gamla namnen i sina frågor.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`OpenTelemetry-mätvärden aktiverade`},help:{"v1-13r4cf4-4x":`Aktivera export av mätvärdessignaler till den konfigurerade slutpunkten för OpenTelemetry-insamlaren. Låt detta vara aktiverat för instrumentpaneler som visar driftstatus och inaktivera endast om mängden mätvärden måste minimeras.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Slutpunkt för OpenTelemetry-mätvärden`},help:{"v1-qlfh7x-47":`Signalspecifik OTLP/HTTP-slutpunkt för mätvärden. När den anges åsidosätter den diagnostics.otel.endpoint och OTEL_EXPORTER_OTLP_ENDPOINT endast för export av mätvärden.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`OpenTelemetry-protokoll`},help:{"v1-17ine8s-5e":`OTel-transportprotokoll för telemetriexport. Endast "http/protobuf" godtas; kör "openclaw doctor --fix" för att korrigera ett sparat äldre "grpc"-värde eller få källspecifik vägledning för manuell redigering.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Samplingsfrekvens för OpenTelemetry-spårningar`},help:{"v1-brcwep-50":`Samplingsfrekvens för spårningar (0-1) som styr hur mycket spårningstrafik som exporteras till backend-system för observerbarhet. Lägre frekvenser minskar resursåtgång och kostnader, medan högre frekvenser ger ett mer detaljerat underlag för felsökning.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`OpenTelemetry-tjänstenamn`},help:{"v1-1hpiqon-5d":`Tjänstenamn som rapporteras i telemetrins resursattribut för att identifiera denna Gateway-instans i övervakningssystem. Använd stabila namn så att instrumentpaneler och larm förblir konsekventa mellan driftsättningar.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`OpenTelemetry-spårning aktiverad`},help:{"v1-j7zrrp-4s":`Aktivera export av spårningssignaler till den konfigurerade OpenTelemetry-insamlarens slutpunkt. Behåll detta aktiverat när spårning för latensanalys eller felsökning behövs, och inaktivera det om du bara vill ha mätvärden och loggar.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Slutpunkt för OpenTelemetry-spårning`},help:{"v1-8yw5p1-43":`Signalspecifik OTLP/HTTP-slutpunkt för spårning. När den anges åsidosätter den diagnostics.otel.endpoint och OTEL_EXPORTER_OTLP_ENDPOINT enbart för spårningsexport.`}},discovery:{label:{"v1-l2sr05-9":`Upptäckt`},help:{"v1-1sqleij-4w":`Inställningar för tjänsteupptäckt via lokal mDNS-annonsering och valfri närvarosignalering över större nätverk. Begränsa upptäckt till avsedda nätverk för att undvika att tjänstemetadata läcker.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS-upptäckt`},help:{"v1-vtbyyq-4w":`Konfigurationsgrupp för mDNS-upptäckt som styr annonsering i det lokala nätverket och anpassning av upptäcktsbeteendet. Behåll minimalt läge för vanlig LAN-upptäckt om inte extra metadata krävs.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Läge för mDNS-upptäckt`},help:{"v1-1p28pd5-2m":`Läge för mDNS-utsändning ("minimal" är standard, "full" inkluderar cliPath/sshPort, "off" inaktiverar mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Upptäckt över större nätverk`},help:{"v1-1akkqjm-53":`Konfigurationsgrupp för upptäckt över större nätverk som gör upptäcktssignaler tillgängliga utanför lokala länkar. Aktivera endast i driftsmiljöer som avsiktligt samlar information om Gateway-närvaro från flera platser.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domän för upptäckt över större nätverk`},help:{"v1-rxrygo-4m":`Valfri unicast-DNS-SD-domän för upptäckt över större nätverk, till exempel openclaw.internal. Använd detta när du avsiktligt publicerar information för Gateway-upptäckt utanför lokala mDNS-områden.`}},env:{label:{"v1-1zc80q-b":`Miljö`},help:{"v1-1ao5po6-55":`Inställningar för import och åsidosättning av miljövariabler som tillhandahåller variabler till Gateway-processen vid körning. Använd det här avsnittet för att styra inläsning av skalmiljön och explicit tillförsel av variabler.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Import av skalmiljö`},help:{"v1-1gw487t-4y":`Inställningar för import av skalmiljön som läser in variabler från ditt inloggningsskal vid start. Låt detta vara aktiverat om du är beroende av hemligheter som definieras i profilen eller anpassningar av PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Import av skalmiljö aktiverad`},help:{"v1-5tiuup-5u":`Aktiverar inläsning av miljövariabler från användarens skalprofil under initieringen vid start. Låt detta vara aktiverat på utvecklardatorer, eller inaktivera det i låsta tjänstemiljöer med explicit hantering av miljövariabler.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Tidsgräns för import av skalmiljö (ms)`},help:{"v1-nsk2yf-5c":`Maximal tid i millisekunder för att läsa in skalmiljön innan reservbeteendet används. Använd kortare tidsgränser för snabbare start, eller öka dem om skalinitieringen är tidskrävande.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Åsidosättningar av miljövariabler`},help:{"v1-1uloveo-5t":`Explicita åsidosättningar av miljövariabler med nyckel/värde-par som slås samman med processmiljön för OpenClaw vid körning. Använd detta för förutsägbar miljökonfiguration i stället för att enbart förlita dig på skalprofilens sidoeffekter.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-1hooncl-5s":`Gateway-inställningar för bindningsläge, autentisering, webbapp, fjärrtransport och driftsäkerhetskontroller. Behåll försiktiga standardinställningar om du inte avsiktligt exponerar gatewayen utanför betrodda lokala gränssnitt.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Tillåt x-real-ip som reserv för Gateway`},help:{"v1-1wr3qmw-4c":`Aktiverar x-real-ip som reserv när x-forwarded-for saknas i proxyscenarier. Låt detta vara inaktiverat om inte din ingressmiljö kräver detta kompatibilitetsbeteende.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Autentisering för Gateway`},help:{"v1-70b6ni-50":`Autentiseringspolicy för HTTP/WebSocket-åtkomst till Gateway, inklusive läge, autentiseringsuppgifter, beteende för betrodda proxyservrar och frekvensbegränsning. Behåll autentisering aktiverad för alla driftsättningar som inte är begränsade till loopback.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Tillåt Tailscale-identitet för Gateway-autentisering`},help:{"v1-vqtmgw-53":`Tillåter att betrodda Tailscale-identiteter uppfyller autentiseringskontrollerna för Gateway när detta är konfigurerat. Använd detta endast när identitetssäkerheten i ditt tailnet är stark och operatörernas arbetsflöden är beroende av det.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Identitetsbaserade behörighetstilldelningar för Gateway`},help:{"v1-1h0zxy7-5n":`Mappar verifierade identiteter från betrodda proxyservrar eller Tailscale till operatörsbehörigheter som endast gäller anslutningen. E-postnycklar matchas utan hänsyn till skiftläge. Tilldelningarna utökar enhetsbehörigheterna innan anslutningens behörighetsgräns tillämpas.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Autentiseringsläge för Gateway`},help:{"v1-j8rodq-9t":`Autentiseringsläge för Gateway: "none", "token", "password" eller "trusted-proxy" beroende på din edge-arkitektur. Läget token/password väljer den konfigurerade hemligheten (gateway.auth.token eller gateway.auth.password); klienter kan skicka den i valfritt autentiseringsfält för anslutningen. Använd token/password vid direkt exponering och trusted-proxy endast bakom säkerhetshärdade, identitetsmedvetna proxyservrar.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Lösenord för Gateway`},help:{"v1-1ndt0u2-4g":`Delad hemlighet som väljs med gateway.auth.mode=password. Klienter kan skicka den i antingen auth.token eller auth.password. Lösenordsläge krävs för Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Frekvensbegränsning för autentisering i Gateway`},help:{"v1-1kstr42-54":`Inställningar för begränsning av inloggnings- och autentiseringsförsök för att minska risken för brute force-attacker mot inloggningsuppgifter vid Gateway-gränsen. Låt detta vara aktiverat i exponerade miljöer och anpassa tröskelvärdena efter din normala trafiknivå.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Token för Gateway`},help:{"v1-16i7cxs-5q":`Delad hemlighet som väljs med gateway.auth.mode=token, standardläget vid ny lokal konfiguration. Klienter kan skicka den i antingen auth.token eller auth.password. Bindningar till andra adresser än loopback kräver ett aktiverat autentiseringsläge.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Autentisering via betrodd proxy för Gateway`},help:{"v1-12fsi5d-58":`Mappning av autentiseringshuvuden för trusted-proxy för uppströms identitetsleverantörer som infogar användaranspråk. Använd endast med kända CIDR-intervall för proxyservrar och strikta tillåtelselistor för huvuden för att förhindra förfalskade identitetshuvuden.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`GitHub-identitet via Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Valfri verifierad GitHub-identitet från en vald Cloudflare Access OIDC-leverantör. Kräver standardrubrikerna för e-post och intyg från Access. Om anspråk saknas behålls profiler med enbart e-post; befintliga profilroller och inställningar för medförfattarskap bevaras.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Anspråk för GitHub-konto-ID`},help:{"v1-qd4qvh-87":`Exakt vidarebefordrat OIDC-anspråk vars värde är ett verifierat GitHub-konto-ID i form av en sträng med ett positivt decimaltal. Konfigurera Access för att vidarebefordra det och granska sedan det autentiserade identitetssvaret från Access. OpenClaw läser oidc_fields, eller custom om oidc_fields saknas. Använd aldrig ett overifierat anspråk som användaren kan redigera.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Cloudflare Access-utfärdare`},help:{"v1-gykv03-56":`Exakt HTTPS-ursprung för det betrodda Cloudflare Access-teamet, till exempel https://example.cloudflareaccess.com, utan avslutande snedstreck. Anspråk från andra utfärdare tillhandahåller ingen GitHub-identitet.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Leverantörs-ID för Cloudflare Access OIDC`},help:{"v1-kbyo5w-44":`Exakt ID för identitetsleverantören i Access för den betrodda OIDC-integrationen. Enbart leverantörens visningsnamn eller ett matchande anspråksnamn räcker inte för att etablera tillit.`}},"gateway%2Eauth%2EtrustedProxy%2Edelegation":{label:{"v1-gzv594-t":`Webbläsardelegering för företag`},help:{"v1-1i9071w-4d":`Acceptera revisionsbundna OCE-webbläsaridentiteter och behörighetstilldelningar via den privata betrodda proxyn. Delegerade profiler använder inte e-postalias eller enhetsbehörigheter.`}},"gateway%2Eauth%2EtrustedProxy%2Edelegation%2EcredentialFile":{label:{"v1-vi5w92-q":`Fil med autentiseringsuppgifter för delegering`},help:{"v1-1tfpp2u-4t":`Absolut sökväg till en privat fil som innehåller revisionens autentiseringsuppgift på 32 byte som 64 hexadecimala tecken med gemener. Om filen ersätts eller tas bort blir befintliga behörighetstilldelningar ogiltiga.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Automatiskt enhetsgodkännande via betrodd proxy`},help:{"v1-uh32ha-6z":`Valfri policy för att automatiskt godkänna nya operatörsenheter i webbläsare och inbyggda användargränssnitt samt utökade behörigheter för samma nyckel efter autentisering via betrodd proxy. Beviljade behörigheter begränsas av deviceAutoApprove.scopes och proxyns x-openclaw-scopes-header när den finns.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Automatiskt enhetsgodkännande via betrodd proxy aktiverat`},help:{"v1-1nntwls-78":`Godkänner automatiskt nya operatörsenheter i webbläsare och inbyggda användargränssnitt samt utökade behörigheter för samma nyckel efter att den omvända proxyn har autentiserat en tillåten användare. Standard: false. Aktivera endast när proxyns identitetsskydd är tillräckligt starkt för att ersätta manuell enhetsparkoppling.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Behörigheter för automatiskt enhetsgodkännande via betrodd proxy`},help:{"v1-raeila-g3":`Maximala behörigheter som beviljas automatiskt godkända operatörsenheter. Standardvärdet är operator.read, operator.write, operator.approvals och operator.questions. Begärda behörigheter begränsas till denna lista; förfrågningar utan angivna behörigheter tilldelas denna lista. När inget värde har angetts lägger automatiskt godkännande även till operator.questions för äldre UI-klienter; en uttryckligen angiven lista utökas aldrig. Om operator.admin uttryckligen anges kan varje proxyautentiserad användare automatiskt godkänna fullständiga administratörsbehörigheter, och förfrågningar utan angivna behörigheter får automatiskt fullständiga administratörsbehörigheter. Detta utlöser även en kritisk anmärkning vid säkerhetsgranskning och en varning vid start av Gateway.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor":{help:{"v1-dai5ie-71":`Valfria standarduppgifter för organisationens medförfattarskap från autentiserade proxyhuvuden. Proxyn måste skriva över dessa fält. De verifierar inte GitHub-identitet och ger inga behörigheter. Angivna e-postadresser kräver sparat samtycke innan de visas i commit-historiken.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EemailHeader":{help:{"v1-1j8gxp7-2h":`Huvud som innehåller organisationens e-postadress för att ange den autentiserade identitetens medförfattarskap i committar.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EemailVerifiedHeader":{help:{"v1-64bvpw-49":`Valfritt huvud som måste vara lika med true innan organisationens standarduppgifter importeras. Utelämna det endast om proxyns intygande av e-postadressen är tillräckligt enligt din policy.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EnameHeader":{help:{"v1-14uvheq-2c":`Header som innehåller organisationens medförfattarnamn för den autentiserade identiteten.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Bindningsläge för Gateway`},help:{"v1-1unqude-4y":`Nätverksbindningsprofil: "auto", "lan", "loopback", "custom" eller "tailnet" för att styra exponeringen av gränssnitt. Behåll "loopback" för enbart lokal drift; "auto" kan exponera alla gränssnitt.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI-agenter`},help:{"v1-1unx5p8-57":`Identifiering i webbappen av externa CLI-sessionsmotorer som tillgängliggörs via Gateway-sessionskatalogen. Aktiverat som standard. Inaktivera för att förhindra att dessa motorer startas från modellväljaren för nya sessioner.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI-agenter aktiverade`},help:{"v1-9ei1mn-8m":`Visar katalogbaserade CLI-agenter i webbappens modellväljare för nya sessioner när värdet är true (standard: true). Ange false för att inaktivera CLI-agenter och skapande av inbyggda CLI-sessioner. Endast kataloger som anger stöd för att skapa sessioner visas, och väljaren förblir dold när Gateway inte anger stöd för sessionskataloger.`}},"gateway%2EcontrolUi":{label:{"v1-zyppo6-7":`Webbapp`},help:{"v1-v2rtyb-5f":`Inställningar för webbappens drift, inklusive aktivering, sökvägar och säkerhetsförstärkning för webbläsarursprung och autentisering. Begränsa exponeringen av gränssnittet och använd starka autentiseringskontroller innan driftsättning med internetåtkomst.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-14ny3x-n":`Tillåtna ursprung för webbappen`},help:{"v1-1br04sw-aq":`Tillåtna webbläsarursprung för anslutningar till webbappen/WebChat (endast fullständiga ursprung, t.ex. https://control.example.com). Om detta utelämnas används gateway.publicOrigin som standard, om det har konfigurerats. En uttrycklig lista, även [], åsidosätter standardvärdet. Befintliga regler för lokala/privata ursprung gäller fortfarande. Inställningen ["*"] tillåter alla webbläsarursprung och bör undvikas utanför strikt kontrollerad lokal testning.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-ylb79x-x":`Tillåt externa URL:er för inbäddning i webbappen`},help:{"v1-y8g73z-62":`FARLIG inställning som tillåter att inbäddat innehåll som tillhandahålls av servern läser in absoluta externa http(s)-URL:er. Låt den vara avstängd om inte webbappen avsiktligt bäddar in betrodda tredjepartssidor. Dokument som tillhandahålls via /__openclaw__/canvas behöver den inte.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Hämta länkarnas webbplatsikoner automatiskt`},help:{"v1-1dimlov-ac":`Hämta länkarnas favikoner och sidförhandsvisningar för externa länkar via Gateway (aktiverat som standard). Sidförhandsvisningar läser in offentlig sidmetadata och angivna bilder utan webbläsarcookies eller inloggningsuppgifter för webbplatsen. Alla förfrågningar använder strikta SSRF-kontroller och resursbegränsad HTML- och bildbearbetning. Ange false för att inaktivera automatisk hämtning av både favikoner och sidförhandsvisningar. Skärmbilder från webbläsaren i realtid påverkas inte.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-zclsby-h":`Webbappens bassökväg`},help:{"v1-npn03b-1t":`Valfritt URL-prefix där webbappen tillhandahålls (t.ex. /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-13uozha-s":`Inbjudan till webbappens community`},help:{"v1-1m3mu0g-7i":`Visa ett communitykort som kan döljas i webbappens sidofält (aktiverat som standard), med länkar till Discord, Reddit och X. Ange false för att dölja det i alla webbläsare som använder den här gränssnittsinstansen. Ändringar börjar gälla när webbläsaren uppdateras eller återansluter. Tidigare val att dölja kortet lokalt i webbläsaren respekteras fortfarande.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Tillåt farlig reservlösning för ursprung via Host-header`},help:{"v1-1i3oa94-7s":`FARLIG inställning som aktiverar reservhantering av ursprung baserad på Host-headern vid WebSocket-kontroller för webbappen/WebChat. Det här läget stöds när din driftsättning avsiktligt förlitar sig på en ursprungspolicy baserad på Host-headern; en explicit gateway.controlUi.allowedOrigins är fortfarande det rekommenderade säkerhetsförstärkta standardvalet.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-kc00jb-q":`Sandlådeläge för inbäddningar i webbappen`},help:{"v1-176jrc2-79":'Sandlådepolicy för iframe-inbäddningar i den värdbaserade webbappen. "strict" inaktiverar skript, "scripts" tillåter interaktiva inbäddningar med bibehållen ursprungsisolering (standard), och "trusted" lägger till `allow-same-origin` för dokument från samma webbplats som avsiktligt behöver utökade behörigheter.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-vpzojz-f":`Webbapp aktiverad`},help:{"v1-1u14fve-4l":`Gör att webbappen tillhandahålls från gatewayens HTTP-process när värdet är true. Behåll aktiverad för lokal administration och inaktivera när ett externt kontrollgränssnitt ersätter den.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-1d85isf-j":`Webbappens miljö`},help:{"v1-vlhh70-4k":`Valfri offentlig miljöidentitet som visas i webbappens färgband, agentavatar, etikettmärken, webbläsartitel och flikikon. Utelämna den för att behålla standardutseendet.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-1h2k80-p":`Webbappens miljöfärg`},help:{"v1-mp6cta-2i":`Namngiven färgskala för miljön: teal, amber, purple, coral, pink, blue, green, red eller gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-vrxwqd-p":`Webbappens miljöetikett`},help:{"v1-1l8ng2x-3w":`Miljöetikett som visas i webbappen och webbläsarfliken; inledande och avslutande blanktecken tas bort och etiketten måste innehålla 1 till 24 tecken.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-1oh9bbh-t":`Experimentella webbappsfunktioner`},help:{"v1-d3p8ng-3m":`Experimentella funktioner i webbappen och bibehållna avancerade åsidosättningar. Experimentella funktioner är inaktiverade som standard om inget annat anges i dokumentationen för respektive inställning.`}},"gateway%2EcontrolUi%2Eexperimental%2EchatBubbles":{label:{"v1-1i4j62s-e":`Pratbubblor`},help:{"v1-19ex4en-5j":`Aktivera experimentella pratbubblor i webbappen (standard: false). Hemvyn använder bubblor som standard när funktionen är aktiverad; sessionsspecifika val som lagras lokalt i webbläsaren har företräde. Ändringar tillämpas utan att Gateway behöver startas om.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Anpassat gränssnitt för insticksprogram`},help:{"v1-18073xm-by":`Tillåt aktiverade, användarinstallerade insticksprogram att köra JavaScript direkt i webbappen (standard: true). Behålls som en avancerad möjlighet till inaktivering enbart via konfigurationen; befintliga false-värden förblir inaktiverade. Vyer från medföljande insticksprogram påverkas inte. Det inbyggda gränssnittet delar den inloggade operatörens Gateway-behörigheter; installera endast betrodda insticksprogram. Ändringar tillämpas utan att Gateway behöver startas om. Efter inaktivering ska du ladda om öppna webbappsidor för att rensa tidigare inläst instickskod.`}},"gateway%2EcontrolUi%2Eexperimental%2Etemplates":{label:{"v1-it5x1k-9":`Mallar`},help:{"v1-1879y2q-3u":`Aktivera sökning i ClawHub och enkelriktad tilläggning via webbappen och Gateway (standard: false). Befintliga agenter fortsätter att köras när detta är inaktiverat.`}},"gateway%2EcontrolUi%2Egithub%2Ehost":{label:{"v1-rjp3f8-r":`Värd för webbappens GitHub-tjänst`},help:{"v1-qaa5xb-3z":`Värd som dessa tjänsteautentiseringsuppgifter får åtkomst till. Utelämna för github.com; ange gateway.github.host för projektidentifiering och kontometadata i Enterprise.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1ia5u0n-x":`Autentiseringsuppgift för webbappens GitHub-tjänst`},help:{"v1-uw4wdq-b5":`SecretRef-baserad autentiseringsuppgift för tjänsten, för projektsökning i webbappen och GitHub-förhandsvisningar vid hovring utan en hanterad identitet. Ange gateway.controlUi.github.host för Enterprise; om värden utelämnas används github.com. Förhandsvisningar vid hovring använder i första hand den valda agentens konfigurerade GitHub-identitet. GH_TOKEN/GITHUB_TOKEN används som reserv endast för github.com. Begäranden som använder en felmatchad eller otillgänglig autentiseringsuppgift avvisas.`}},"gateway%2EcontrolUi%2EnewSessionModelDefaults":{label:{"v1-bxfhmu-q":`Standardinställningar för modell i nya sessioner`},help:{"v1-1r6o74t-98":`Välj "configured" för att starta nya utkast i webbappen med den valda agentens konfigurerade standardinställningar för modell, körmiljö och resonemang i stället för tidigare sparade val. Standard: "last-used". Uttryckliga val för utkast och konversationer kan fortfarande ändras; snabbläge och placeringsinställningar påverkas inte. Gäller efter att webbläsaren har uppdaterats eller anslutningen återupprättats.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-1ke8erh-j":`Rotkatalog för webbappens resurser`},help:{"v1-192j3ry-22":`Valfri rotkatalog i filsystemet för webbappens resurser (standard är dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-zsqsj8-o":`Sessionsobservatör för webbappen`},help:{"v1-1uilm4q-87":`Skapa sammanfattningar av sessionsstatus i realtid för prenumererande webbappsklienter med varje agents hjälpmodell (aktiverat som standard). Ange false för att inaktivera observatörens modellanrop i hela gatewayen; om agents.defaults.utilityModel anges som en tom sträng inaktiveras observation med hjälpmodell för agenter som inte åsidosätter inställningen.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Anpassad bindningsvärd för Gateway`},help:{"v1-lwjcyo-4d":`IPv4-adress som används för en anpassad bindning. Specifika IPv4-adresser kräver också samma Gateway-port på 127.0.0.1. Undvik 0.0.0.0 om exponering på alla gränssnitt inte krävs.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`HTTP-API för Gateway`},help:{"v1-9vup6v-4y":`Konfiguration av Gateways HTTP-API som samlar reglage för ändpunkter och kontroller för API-exponering på transportnivå. Aktivera endast nödvändiga ändpunkter för att begränsa vad fjärrklienter kan komma åt.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`HTTP-ändpunkter för Gateway`},help:{"v1-1a0r104-55":`Funktionsreglage för HTTP-ändpunkter i Gateways API för kompatibilitetsrutter och valfria integrationer. Aktivera ändpunkter medvetet och övervaka åtkomstmönster efter driftsättning.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Ändpunkt för OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Aktivera den OpenAI-kompatibla ändpunkten `POST /v1/chat/completions` (standard: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Bildgränser för OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Kontroller för hämtning och validering av bilder för OpenAI-kompatibla `image_url`-delar."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`OpenAI Chat Completions – tillåtna MIME-typer för bilder`},help:{"v1-1guijf3-1t":"Tillåtna MIME-typer för `image_url`-delar (listan är inte skiftlägeskänslig)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`OpenAI Chat Completions – tillåt bild-URL:er`},help:{"v1-55cb3n-47":"Tillåt hämtning från URL:er på serversidan för `image_url`-delar (standard: false; data-URI:er stöds fortfarande). Sätt detta till `false` för att inaktivera URL-hämtning helt."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`OpenAI Chat Completions – maximalt antal byte per bild`},help:{"v1-d920yx-1s":"Maximalt antal byte per hämtad/avkodad `image_url`-bild (standard: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`OpenAI Chat Completions – maximalt antal omdirigeringar för bilder`},help:{"v1-1enujsk-1z":"Maximalt antal tillåtna HTTP-omdirigeringar vid hämtning från `image_url`-URL:er (standard: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`OpenAI Chat Completions – tidsgräns för bilder (ms)`},help:{"v1-89w2b9-1x":"Tidsgräns i millisekunder för hämtning från `image_url`-URL:er (standard: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`OpenAI Chat Completions – tillåtna bild-URL:er`},help:{"v1-n4hlt1-4r":"Valfri lista över tillåtna värdnamn för URL-hämtningar med `image_url`; stöder exakta värdnamn och jokertecken som `*.example.com`. Tomma eller utelämnade listor innebär ingen begränsning av tillåtna värdnamn."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`HTTP-säkerhetsrubriker för Gateway`},help:{"v1-n8z1hb-44":`Valfria säkerhetsrubriker för HTTP-svar som tillämpas av själva gateway-processen. Ställ helst in dessa i din omvända proxy när TLS avslutas där.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Rubrik för strikt transportsäkerhet`},help:{"v1-1buwhc3-3v":`Värde för svarsrubriken Strict-Transport-Security. Ange endast för HTTPS-ursprung som du har full kontroll över; använd false för att uttryckligen inaktivera.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Driftläge för Gateway`},help:{"v1-nfjirv-5m":`Driftläge för Gateway: "local" kör kanaler och agentens körmiljö på den här värden, medan "remote" ansluter via fjärrtransport. Behåll "local" om du inte avsiktligt använder en uppdelad topologi med en fjärrgateway.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills för Gateway-noder aktiverade`},help:{"v1-1xwu6at-3g":`Acceptera färdigheter som publiceras av parkopplade noder medan de är anslutna (standard: true). Ange false för att ignorera färdigheter som publiceras av noder.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Webbläsarläge för Gateway-noder`},help:{"v1-oeu1nc-69":`Routning av nodwebbläsare ("auto" = föredra värdens webbläsare, använd en enda ansluten webbläsarnod när lokal funktionalitet saknas; "manual" = kräv ett uttryckligt nodval eller en konfigurerad bindning; "off" = inaktivera nodroutning).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Fast nod för webbläsarroutning i Gateway`},help:{"v1-1cykty2-1p":`Lås webbläsarroutningen till ett specifikt nod-id eller nodnamn (valfritt).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Tillåtelselista för Gateway-noder (extra kommandon)`},help:{"v1-6l4otb-5m":"Extra node.invoke-kommandon som tillåts utöver standardkommandona i Gateway (en array med kommandosträngar). Att aktivera farliga kommandon här är ett säkerhetskänsligt åsidosättande som flaggas av `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Blockeringslista för Gateway-noder`},help:{"v1-u7c8wx-53":"Namn på nodkommandon som ska blockeras även om de finns i nodens deklarerade behörigheter eller standardtillåtelselistan (endast exakt matchning av kommandonamn, t.ex. `system.run`; granskar inte skaltext inuti kommandot)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Parkoppling av Gateway-noder`},help:{"v1-gldsi2-4s":`Policyinställningar för nodparkoppling. SSH-verifierat automatiskt godkännande är aktiverat som standard; automatiskt godkännande via CIDR förblir inaktiverat om inte uttryckliga tillåtelselistor med betrodda CIDR/IP-adresser konfigureras.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR-intervall för automatiskt godkännande av Gateway-nodparkoppling`},help:{"v1-jeel9f-6u":`Valfri CIDR/IP-lista över tillåtna adresser för automatiskt godkännande av första parkopplingen av enheter med nodroll utan begärda behörighetsomfång. Inaktiverat om inget anges. Parkoppling för operatörer, webbläsare och webbappar samt all parkoppling som uppgraderar roll, behörighetsomfång, metadata eller publik nyckel kräver fortfarande manuellt godkännande.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Automatiskt godkännande av lokal Gateway-nodparkoppling`},help:{"v1-glzm36-41":`Godkänn automatiskt betrodd lokal parkoppling och utökade åtkomsträttigheter (standard: true); ange false för att kräva uttryckligt godkännande av varje enhet i stället.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`SSH-verifiering av nodparkoppling i Gateway`},help:{"v1-1e4da92-ct":"SSH-verifierat automatiskt godkännande vid första parkopplingen av en enhet med nodroll (standard: aktiverat). Gateway ansluter tillbaka till parkopplingsvärden via SSH (BatchMode, strikt kontroll av värdnycklar) och godkänner endast när utdata från fjärrkommandot `openclaw node identity` matchar den väntande enhetens nyckel. Ange false för att inaktivera SSH-verifiering (oberoende av autoApproveCidrs, som förblir aktivt); ta även bort inställningen autoApproveCidrs om parkoppling endast ska ske manuellt. Ange ett objekt för att åsidosätta user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Pluginverktyg för Gateway-noder`},help:{"v1-1c24iq3-28":`Styr om parkopplade noder får publicera beskrivningar av pluginverktyg som är synliga för agenter.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Pluginverktyg för Gateway-noder aktiverade`},help:{"v1-14lgfu6-47":`Acceptera beskrivningar av pluginverktyg som är synliga för agenter och publiceras av parkopplade noder (standard: true). Ange false för att ignorera och ta bort alla pluginverktyg som publicerats av noder.`}},"gateway%2EopenclawId":{label:{"v1-ezzq9b-p":`Fjärråtkomst med OpenClaw ID`},help:{"v1-1ulzsn4-95":`Experimentell fjärråtkomst med OpenClaw ID (Labs). När funktionen är aktiverad övervakar Gateway en underprocess för tunneln som accepterar iroh-anslutningar från godkända enheter och vidarebefordrar dem till denna Gateway. Avstängd som standard. När funktionen är avstängd startar Gateway ingen underprocess, öppnar inga tunnelsocklar och kontaktar inte OpenClaw ID, Discovery eller någon relätjänst.`}},"gateway%2EopenclawId%2EclientId":{label:{"v1-1g7ikna-t":`Klient-ID för webbappen för OpenClaw ID`},help:{"v1-4vjfwu-8r":`Publik OAuth-klient (auktoriseringskod med PKCE) som webbappen använder för att logga in med OpenClaw ID via kontomenyn. Dess omdirigerings-URI är <web app origin>/openclaw-id/callback. På den här datorn används denna omdirigering vid inloggning; en webbapp som nås via en personlig inloggning, till exempel Tailscale, använder utfärdarens enhetsauktorisering.`}},"gateway%2EopenclawId%2EdiscoveryUrl":{label:{"v1-hnez1c-p":`URL för OpenClaw ID Discovery`},help:{"v1-14rpvwb-5h":`Discovery-tjänst som speglar claw-beskrivningen och ögonblicksbilden av medlemskapet samt vidarebefordrar brevlådemeddelanden. Den betraktas inte som betrodd: varje påstående den returnerar verifieras mot claw-enhetens fastlåsta ägarrot.`}},"gateway%2EopenclawId%2Eenabled":{label:{"v1-c5v95y-x":`Fjärråtkomst med OpenClaw ID aktiverad`},help:{"v1-19yjuzt-66":`Aktiverar experimentell fjärråtkomst med OpenClaw ID (standard: false). Ändringar tillämpas utan att Gateway startas om. Fjärråtkomst kräver även relayUrl; för att länka en claw krävs dessutom issuerUrl, discoveryUrl och loaderDomain.`}},"gateway%2EopenclawId%2EissuerUrl":{label:{"v1-g27qab-m":`URL för OpenClaw ID-utfärdare`},help:{"v1-dmrsc-4e":`OpenClaw ID-utfärdare som används vid inloggning enbart för identitetsverifiering när en claw länkas. Den betraktas aldrig som betrodd för medlemskap, enhetsgodkännande eller valet av server som en klient ansluter till.`}},"gateway%2EopenclawId%2EloaderDomain":{label:{"v1-1m8dm2q-p":`Domän för OpenClaw ID-laddaren`},help:{"v1-1xj9br0-4o":`DNS-domän utan protokoll eller sökväg för OpenClaw ID-laddaren. En länkad claw kan nås på https://<name>-<account tag>.<loaderDomain> och dess serverbindning är signerad för det värdnamnet.`}},"gateway%2EopenclawId%2EmemberDeviceInactivityDays":{label:{"v1-bv2n4v-17":`Inaktivitet för medlemsenhet i OpenClaw ID (dagar)`},help:{"v1-1n802ug-3g":`Antal dagar som en medlems webbläsare får vara utan kontakt med denna claw innan den tar bort webbläsaren (standard: 30). Medlemmen finns kvar i listan.`}},"gateway%2EopenclawId%2EownerDeviceInactivityDays":{label:{"v1-1elnzyi-16":`Inaktivitet för ägarenhet i OpenClaw ID (dagar)`},help:{"v1-cy2c02-3x":`Antal dagar som en ägarenhet får vara utan kontakt med denna claw innan den tar bort enheten från sin lista över tillåtna enheter (standard: 90). Enheter som ägarenheten har godkänt finns kvar.`}},"gateway%2EopenclawId%2ErelayUrl":{label:{"v1-1r8to4f-l":`Relä-URL för OpenClaw ID`},help:{"v1-1f4exuo-3w":`Det enda iroh-reläet i tunneländpunktens reläkarta (inga offentliga n0-reläer, DNS eller pkarr). Webbläsare når endast denna claw via detta relä.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway-port`},help:{"v1-af1nrn-51":`TCP-port som gatewayens lyssnare använder för inkommande trafik till API, webbapp och kanaler. Använd en dedikerad port och undvik konflikter med omvända proxyservrar eller lokala utvecklingstjänster.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gateway-portaler`},help:{"v1-1v2lkw9-1c":`Inställningar för portalpublicering och privat inkommande trafik.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Privat portal-ingress`},help:{"v1-20w4gq-69":`Valfri operatörshanterad privat omvänd HTTPS-proxy med jokertecken. Vidarebefordra ursprunglig Host, sökvägar och WebSocket-uppgraderingar till den dedikerade loopback-lyssnaren. Bearer-autentisering för portalen krävs fortfarande. Kräver omstart av Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Jokerteckendomän för portalen`},help:{"v1-1ffvdzt-50":`DNS-domän utan prefix för slumpmässiga portalunderdomäner (till exempel previews.example.net). Konfigurera wildcard-DNS och HTTPS separat; dela inte namnrymd för värdnamn med Gateway eller webbappen.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Loopback-port för portal-ingress`},help:{"v1-1mb98cv-4g":`Dedikerad HTTP-port på loopback som tar emot trafik från den privata HTTPS-proxyn med jokertecken. Måste skilja sig från porten för Gateway. Detta är backend-porten, inte den publika HTTPS-porten.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Publikt ursprung för Gateway`},help:{"v1-1c6onp0-ae":`Externt åtkomligt HTTPS-ursprung för Gateway. Även standardursprung för webbläsaren när gateway.controlUi.allowedOrigins utelämnas. HTTP tillåts endast för localhost, 127.0.0.1 eller [::1]. MCP OAuth per anropare använder detta för att skapa återanropsadressen på /oauth/mcp/callback; länkar till kanalsessioner och visningslänkar som genereras av insticksprogram använder det för att nå webbappen och Gateway-rutter.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Pushleverans för Gateway`},help:{"v1-h23oz7-5s":`Inställningar för pushleverans som används av gatewayen när den behöver väcka eller avisera parkopplade enheter. Konfigurera reläbaserad APNs här för officiella iOS-byggen; direkt APNs-autentisering förblir baserad på miljövariabler för lokala/manuella byggen.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`APNs-leverans för Gateway`},help:{"v1-4bbafr-4e":`Inställningar för APNs-leverans till iOS-enheter som är parkopplade med denna gateway. Använd reläinställningar för officiella App Store-versioner som registreras via det externa pushreläet.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`APNs-relä för Gateway`},help:{"v1-7glbel-6x":`Inställningar för externt relä för reläbaserade APNs-sändningar. Gateway använder som standard OpenClaws värdbaserade relä, eller detta anpassade relä för push.test, väckningssignaler och väckningar för återanslutning efter att en parkopplad officiell iOS-version har publicerat en reläbaserad registrering.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Bas-URL för Gateways APNs-relä`},help:{"v1-1o8mgnq-69":`Valfri anpassad HTTPS-bas-URL för den externa APNs-relätjänsten som används av officiella iOS-versioner från App Store. Se till att den matchar reläets URL som är inbyggd i iOS-versionen så att registrerings- och sändningstrafik når samma driftsättning.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Tidsgräns för Gateways APNs-relä (ms)`},help:{"v1-a0jkb1-4z":`Tidsgräns i millisekunder för sändningsbegäranden från gateway till APNs-reläet (standard: 10000). Öka värdet för långsammare reläer eller nätverk, eller sänk det för att avbryta misslyckade väckningsförsök snabbare.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Omladdning av konfiguration`},help:{"v1-d02mvq-4w":`Policy för omladdning av konfiguration under drift som styr hur ändringar tillämpas och när fullständiga omstarter utlöses. Behåll hybridbeteendet för säkrast möjliga uppdateringar under drift, om du inte felsöker omladdningens interna funktioner.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Läge för omladdning av konfiguration`},help:{"v1-1q1etcf-3m":`Styr hur konfigurationsändringar tillämpas: "off" ignorerar ändringar under drift och "hybrid" tillämpar ändringar som är säkra att göra under drift och startar sedan om vid behov.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Fjärransluten Gateway`},help:{"v1-6xv7gd-5a":`Anslutningsinställningar för fjärransluten Gateway via direktanslutning eller SSH när denna instans fungerar som proxy till en annan körningsvärd. Använd fjärrläge endast när drift över flera värdar avsiktligt har konfigurerats.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`HTTP-huvuden för kantautentisering till fjärransluten Gateway`},help:{"v1-jg9p7d-5o":`HTTP-huvuden med värden från hemligheter som skickas till en identitetsmedveten proxy framför den konfigurerade fjärranslutna Gateway. Huvudena skickas endast till exakt det ursprung som anges av gateway.remote.url via WSS och följer aldrig omdirigeringar.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Lösenord för fjärransluten Gateway`},help:{"v1-16jc0yx-7y":`Delad hemlighet som skickas i lösenordsfältet för att autentisera denna klient mot en fjärransluten Gateway. Serverns gateway.auth.mode väljer dess konfigurerade hemlighet; både klientens tokenfält och lösenordsfält accepteras. Hantera denna hemlighet externt och undvik klartextvärden i versionshanterad konfiguration.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Policy för SSH-värdnycklar för fjärransluten Gateway`},help:{"v1-7qoxtb-49":`Policy för verifiering av SSH-värdnycklar i macOS. "strict" kräver en redan betrodd värdnyckel; "openssh" överlåter uttryckligen verifieringen till den gällande OpenSSH-konfigurationen.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`SSH-identitet för fjärransluten Gateway`},help:{"v1-hz2hsm-1f":`Valfri sökväg till SSH-identitetsfil (skickas till ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`SSH-mål för fjärransluten Gateway`},help:{"v1-85w39w-2t":`Fjärransluten Gateway via SSH (tunnlar Gateway-porten till localhost). Format: user@host eller user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`TLS-fingeravtryck för fjärr-Gateway`},help:{"v1-1ri16lk-23":`Förväntat sha256-TLS-fingeravtryck för fjärr-Gateway (lås till detta för att undvika MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token för fjärr-Gateway`},help:{"v1-1pb9q8w-7v":`Delad hemlighet som skickas i tokenfältet för att autentisera den här klienten mot en fjärr-Gateway. Serverns gateway.auth.mode väljer dess konfigurerade hemlighet; både klientens tokenfält och lösenordsfält godtas. Lagra via substitution av hemligheter eller miljövariabler och rotera i samband med ändringar av autentiseringen för fjärr-Gateway.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transport för fjärr-Gateway`},help:{"v1-1acfs7m-54":`Transport för fjärranslutning: "direct" använder den konfigurerade URL:en för anslutning, medan "ssh" tunnlar genom SSH. Använd SSH när du behöver en krypterad tunnel utan att exponera fjärrportar.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL för fjärr-Gateway`},help:{"v1-va7exe-1b":`WebSocket-URL för fjärr-Gateway (ws:// eller wss://).`}},"gateway%2ErepositoryIntegration":{label:{"v1-9msrgf-m":`Integration med kodförråd`},help:{"v1-10mbwuf-7d":`Plugin-ID som krävs för att ge arbetare åtkomst till källkod i kodförråd, inklusive inbyggd åtkomst, GitHub App och hanterade OAuth- eller PAT-autentiseringsuppgifter. Om ägarpluginen saknas, är inaktiverade eller inte har lästs in nekas åtkomst. Utelämna detta för att använda det inbyggda beteendet för kodförråd; att enbart aktivera en plugin innebär inte att den väljs.`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Operatörsroller för Gateway`},help:{"v1-1h5f6fh-84":`Namngivna operatörsrolldefinitioner för teamets Gateways. Om gateway.roles.default anges aktiveras profilbunden tillämpning av regler för sessionsåtkomst, sandlådeisolering, agenter och operatörsbehörigheter. Definitioner utan ett standardvärde utgör endast en katalog och bevarar beteendet hos en Gateway utan gateway.roles.`}},"gateway%2Eroles%2Eassignments":{label:{"v1-hv31t1-p":`Tilldelning av operatörsroller`},help:{"v1-do2i61-55":`Valfria deklarativa rolltilldelningar för autentiserade profiler. En giltig uttrycklig tilldelning som gjorts med users.setRole har företräde framför dessa mappningar, som i sin tur har företräde framför standardrollen.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin":{label:{"v1-wujwr5-u":`Operatörsroller efter GitHub-användarnamn`},help:{"v1-ecgzr1-95":`Kräver gateway.roles.default, även för en tom mappning. Mappar cachade GitHub-identiteters inloggningsnamn till konfigurerade rollnamn. Matchningen är skiftlägesokänslig och görs efter att inledande och avslutande blanksteg har tagits bort. Ogiltiga inloggningsnamn, duplicerade normaliserade inloggningsnamn och okända roller avvisas. Profiler utan en cachad GitHub-identitet använder sin uttryckliga tilldelning eller standardrollen.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin%2E*":{label:{"v1-1wr68uf-q":`Operatörsroll för GitHub-användarnamn`},help:{"v1-dad5ey-5e":`Konfigurerat rollnamn för detta GitHub-användarnamn. Gäller när profilen har en matchande cachad GitHub-identitet och saknar en giltig uttrycklig rolltilldelning. Ändringar tillämpas utan omstart när omladdning av konfigurationen är aktiverad.`}},"gateway%2Eroles%2Edefault":{label:{"v1-12e6yd7-17":`Standardroll för operatörer (aktiverar regeltillämpning)`},help:{"v1-18k9r00-7c":`Valfri standardroll som aktiverar tillämpning av namngivna roller och gäller för autentiserade profiler utan en giltig uttrycklig tilldelning eller tilldelning via GitHub-inloggningsnamn. Namnet måste matcha en konfigurerad definition. Om den utelämnas förblir tillämpning av namngivna roller avstängd, även om definitioner finns.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definitioner av operatörsroller`},help:{"v1-11qtcgr-6w":`Icke-tom katalog med roller som namnges av administratören och samlar policyer för sessionsdelning, sandlådeisolering, agentåtkomst och operatörsbehörigheter. Enbart definitioner aktiverar inte regeltillämpning. Ange gateway.roles.default för att tillämpa namngivna roller på autentiserade profiler.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definition av operatörsroll`},help:{"v1-p8tfws-6q":`En namngiven operatörsroll. Varje definition måste uttryckligen ange sin policy för sessionsdelning, tillåtna agenter för sessioner och körningar samt den övre gränsen för operatörsbehörigheter. Den kan också kräva sandlådeisolering för nyskapade sessioner och en åtkomstpolicy för insticksprogram.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin för operatörsrollens åtkomstpolicy`},help:{"v1-1gq4q08-9n":`Valfritt exakt plugin-ID vars åtkomstpolicy för Gateway måste godkänna denna roll. Åtkomst nekas om pluginet saknas, är inaktiverat, inte kan laddas eller inte tillhandahåller någon aktuell behörighet. Plugin-ID:n som inte är tillgängliga förblir giltiga i konfigurationen så att oberoende personalroller och ägaren av Gateway kan återställa åtkomsten. Om detta fält utelämnas tillkommer inget pluginberoende.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Tillåtna agenter för operatörsrollen`},help:{"v1-fvun18-4v":`Agenter som är tillgängliga när denna roll skapar sessioner eller startar körningar: ange "*" för att tillåta alla agenter, lista agent-ID:n för att endast tillåta dessa agenter eller använd en tom lista för att inaktivera båda åtgärderna.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy":{label:{"v1-1b2q6cc-q":`Modellpolicy för operatörsrollen`},help:{"v1-r9daa-e8":`Valfri övre gräns för modellåtkomst för denna rolls förfrågningar och deras underordnade förfrågningar. Ett tomt objekt tillåter endast ursprungsagentens konfigurerade primära modeller och reservmodeller. Om policyn utelämnas förblir modellåtkomsten oförändrad. Modellalias löses innan policyn tillämpas, och nekade modeller kan inte användas vid återförsök eller som reservmodeller. När omladdning av konfigurationen är aktiverad tillämpas ändringar som endast berör befintliga rollers modellpolicyer när de sparas, utan att tillåtet arbete startas om. Andra rolländringar tillämpas direkt och klienterna återansluts med aktuell behörighet.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Eallow":{label:{"v1-zdw95f-s":`Tillåtna modeller för operatörsrollen`},help:{"v1-1dutf3o-8u":`Valfri ersättningslista över tillåtna modellreferenser, konfigurerade alias eller prefixmönster med avslutande jokertecken, till exempel "provider/*" eller "provider/family-*". Om listan utelämnas används källagentens primära modell och reservmodeller; en tom lista nekar alla modeller. Den första tillåtna källmodellen förblir standardvalet, följd av uttryckligen tillåtna modeller.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Edeny":{label:{"v1-1hx2vzz-t":`Uteslutna modeller för operatörsrollen`},help:{"v1-1kx70ze-7o":`Modellreferenser, källagentens alias eller prefixmönster med avslutande jokertecken som utesluts från den här rollen. Ett mönster som "provider/family-*" utesluter även framtida modeller i den familjen. Uteslutningar matchas mot modellernas faktiska identiteter och har företräde framför tillåtna modeller och källagentens modeller.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2EsourceAgent":{label:{"v1-8bg4yu-w":`Källagent för operatörsrollens modeller`},help:{"v1-yf7mu-62":`Agent vars primära modell, reservmodeller och modellalias ligger till grund för den här rollens modellpolicy. Standardvärdet är den konfigurerade system- eller standardagenten, eller den enda agenten. Ange detta uttryckligen när en Gateway med flera agenter saknar en ägare i den aktuella kontexten.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Sandlådeisolering för operatörsrollen`},help:{"v1-11bb0ps-6a":`Körningsisolering för nyskapade sessioner: "inherit" (standard) använder agentens policy; "required" kräver permanent en sandlåda, även när agentens sandlådeläge är avstängt, och blockerar körning om backend inte är tillgänglig.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Övre behörighetsgräns för operatörsrollen`},help:{"v1-1selr2i-4s":`Sluten lista över operatörsbehörigheter som utgör rollens maximala behörighet vid anslutning. Begärda, parkopplade, identitetstilldelade och utökade behörigheter begränsas till de som också finns i denna lista.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Operatörsrollens sessionsåtkomst`},help:{"v1-hsoiop-45":`Behörigheter för sessionsdelning som tilldelas denna roll för sessioner skapade av andra autentiserade personer. En persons egna sessioner förblir åtkomliga för ägaren.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Operatörsrollens åtkomst till andra sessioner`},help:{"v1-1pmaa4o-al":`Åtkomst till andra personers sessioner: "none" döljer dem även vid uttryckligt sessionsmedlemskap, "view" tillåter läsning, "suggest" tillåter förslagsflödet och "write" tillåter deltagande utan medlemskap. Uttryckligt sessionsmedlemskap kan utöka åtkomsten från "view" eller "suggest" för en specifik session. Sessionsskapare och anslutningar med operator.admin behåller sin sessionsåtkomst.`}},"gateway%2Eroles%2Edefinitions%2E*%2EworkerProfiles":{label:{"v1-o0hlzf-t":`Arbetarprofiler för operatörsrollen`},help:{"v1-v6xpap-5r":`Arbetarprofiler i molnet som den här rollen uttryckligen får skicka sina egna sessioner till. Om fältet utelämnas eller är tomt tillåts inte sändning till molnet; administratörer behåller åtkomsten. Konfiguration och flytt till molnprofiler är fortfarande endast tillåtna för administratörer.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale för Gateway`},help:{"v1-6ar9o-4x":`Inställningar för Tailscale-integrering för exponering via Serve/Funnel och livscykelhantering när Gateway startas eller avslutas. Låt vara avstängt om inte distributionen avsiktligt använder inkommande trafik via Tailscale.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Tailscale-läge för Gateway`},help:{"v1-6l2099-5a":`Publiceringsläge för Tailscale: "off", "serve" eller "funnel" för privat eller offentlig exponering. Använd "serve" för åtkomst enbart inom tailnet och "funnel" endast när tillgänglighet via det offentliga internet krävs.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Migreringsskydd för extern Funnel via Tailscale i Gateway`},help:{"v1-1mntkor-7q":`Föråldrat migreringsskydd för mode='serve'. Om en extern Funnel fortfarande pekar på den vanliga Gateway-lyssnaren lämnar OpenClaw exponeringen oförändrad och varnar för att endast plugin-autentiserade webhooks förblir användbara tills lösenordsautentisering har konfigurerats och mode har migrerats till 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Operatörsterminal`},help:{"v1-1qtq5dc-88":`Operatörsterminal som tillhandahålls till webbappen och mobilklienter: ett PTY-baserat skal på gatewayvärden, begränsat till operatörssessioner med administratörsbehörighet. Det startar i målagentens arbetsyta och nekas för helt sandlådeisolerade agenter (sandbox.mode 'all') i stället för att ge tillgång till ett obegränsat skal på värden.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Tidsgräns för frånkopplade sessioner i operatörsterminalen`},help:{"v1-k6qbgr-9e":`Antal sekunder som en terminalsession finns kvar efter att anslutningen bryts (bärbar dator i viloläge, omladdning av sidan). Under den tiden kan sessionen återanslutas via terminal.attach, med den senaste utmatningen återvisad. Ange 0 för att avsluta sessioner så snart anslutningen bryts. Standardvärde: 300 (5 minuter). Frånkopplade sessioner fortsätter att köra sina kommandon, så förkorta tiden på delade eller exponerade värdar.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Operatörsterminal aktiverad`},help:{"v1-1nez06v-7p":`Aktiverar operatörsterminalen för klienter med administratörsbehörighet (standardvärde: true). Detta exponerar ett skal för webbläsare och mobilklienter med Gateway-processens miljö. Ange false för att inaktivera det i driftsättningar där administratörsoperatörer inte ska få tillgång till ett skal på värden. Ändringar tillämpas utan att Gateway behöver startas om.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Skal för operatörsterminalen`},help:{"v1-19mfe6t-5i":`Den körbara skalfil som operatörsterminalen startar. Lämna detta odefinierat för att använda värdsystemets inloggningsskal ($SHELL på Unix, %ComSpec% på Windows), eller ange en specifik tolk för en enhetlig operatörsmiljö.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS för Gateway`},help:{"v1-1dx77dq-4z":`Inställningar för TLS-certifikat och nycklar för att terminera HTTPS direkt i gateway-processen. Använd uttryckligen angivna certifikat i produktion och undvik exponering i klartext på nätverk som inte är betrodda.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Generera TLS-certifikat automatiskt för Gateway`},help:{"v1-1ld6uiu-4w":`Genererar automatiskt ett lokalt TLS-certifikat med tillhörande nyckel när inga specifika filer har konfigurerats. Använd endast i lokala miljöer och utvecklingsmiljöer och ersätt med riktiga certifikat för produktionstrafik.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Sökväg till TLS-CA för Gateway`},help:{"v1-andqlu-52":`Valfri sökväg till en CA-samling för klientverifiering eller anpassade krav på tillitskedjan vid gatewayens nätverksgräns. Använd detta när privat PKI eller anpassade certifikatkedjor ingår i driftsättningen.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Sökväg till TLS-certifikat för Gateway`},help:{"v1-1wznaof-4q":`Sökväg i filsystemet till den TLS-certifikatfil som gatewayen använder när TLS är aktiverat. Använd hanterade certifikatsökvägar och se till att automatisk förnyelse använder samma plats.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS aktiverat för Gateway`},help:{"v1-ykhwp0-4o":`Aktiverar TLS-terminering i gatewayens lyssnare så att klienter ansluter direkt via HTTPS/WSS. Låt detta vara aktiverat vid direkt exponering mot internet eller vid alla gränser mot nätverk som inte är betrodda.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Sökväg till TLS-nyckel för Gateway`},help:{"v1-15knri0-4i":`Sökväg i filsystemet till filen med den privata TLS-nyckel som används av Gateway när TLS är aktiverat. Begränsa åtkomsten till nyckelfilen med filbehörigheter och rotera nyckeln enligt din säkerhetspolicy.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Policy för verktygsexponering i Gateway`},help:{"v1-1ffol26-5a":`Policy på Gateway-nivå som tillåter eller nekar exponering av verktyg och kan begränsa verktygens tillgänglighet under körning oberoende av agent- och verktygsprofiler. Använd detta för övergripande nödåtgärder och säkerhetshärdning i produktion.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Lista över tillåtna verktyg i Gateway`},help:{"v1-163khb1-4y":`Uttrycklig lista över tillåtna verktyg på Gateway-nivå när du vill att endast ett begränsat urval av verktyg ska vara tillgängligt under körning. Använd detta i låsta miljöer där verktygsutbudet måste kontrolleras strikt.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Lista över blockerade verktyg i Gateway`},help:{"v1-1lhssnf-4o":`Uttrycklig lista över blockerade verktyg på Gateway-nivå för att blockera riskfyllda verktyg även om policyer på lägre nivå tillåter dem. Använd blockeringsregler för nödåtgärder och säkerhetshärdning med skydd i flera lager.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR-intervall för betrodda proxyservrar i Gateway`},help:{"v1-n5zcvf-4f":`Lista över tillåtna CIDR-intervall/IP-adresser för uppströmsproxyservrar som får tillhandahålla vidarebefordrade HTTP-huvuden med klientidentitet. Håll listan snäv så att obetrodda mellanhänder inte kan utge sig för att vara användare.`}},"gateway%2Euploads":{label:{"v1-pn01yp-m":`Fil- och bilduppladdningar`},help:{"v1-ger7hh-3a":`Policy för klienters uppladdning av filer och bilder till Gateway och webbappen. Nedladdningar och agentgenererade medier förblir tillgängliga.`}},"gateway%2Euploads%2Eenabled":{label:{"v1-1m4q5zw-f":`Uppladdningar aktiverade`},help:{"v1-1tqoi1v-93":`Tillåter klientuppladdningar av filer och bilder (standard: true). Ange false för att avvisa bilagor, uppladdningar från arbetsytor och terminaler, avataruppladdningar och arkivimporter vid Gateway, även via direkta API-anrop. Ändringar tillämpas utan omstart. Detta är inte en sandlåda eller en begränsning av kanalmedier, agentverktyg eller operatörens skalåtkomst.`}},hooks:{label:{"v1-j9ywl7-5":`Hookar`},help:{"v1-1mzh0ry-5v":`Automatiseringsgränssnitt för inkommande webhookar som mappar externa händelser till väcknings- eller agentåtgärder i OpenClaw. Skydda detta med uttryckliga kontroller för token, sessioner och agenter innan det exponeras utanför betrodda nätverk.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Tillåtna agent-ID:n för hookar`},help:{"v1-1imjux7-79":`Lista över tillåtna effektiva agent-ID:n som hook-anrop och mappningar får riktas till, inklusive routning till standardagenten när agentId utelämnas. Använd detta för att begränsa automatiseringshändelser till dedikerade tjänsteagenter och begränsa skadan om en hook-token röjs.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Tillåtna sessionsnyckelprefix för hookar`},help:{"v1-b346oh-4r":`Lista över tillåtna sessionsnyckelprefix för inkommande hook-anrop när nycklar som anges av anroparen är aktiverade. Använd snäva prefix för att förhindra injicering av godtyckliga sessionsnycklar.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Tillåt sessionsnyckel i hook-anrop`},help:{"v1-11n9ps-52":`Tillåter anropare att ange en sessionsnyckel i hook-anrop när värdet är true, vilket möjliggör anroparstyrd routning. Behåll false om inte betrodda integratörer uttryckligen behöver anpassad sessionstrådning.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Standardsessionsnyckel för hookar`},help:{"v1-bzdgkn-57":`Reservnyckel för sessionen som används vid hook-leveranser när en begäran inte anger någon via tillåtna kanaler. Använd en stabil men avgränsad nyckel för att undvika att blanda ihop orelaterade automatiseringskonversationer.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooks aktiverade`},help:{"v1-1mixmjf-4n":`Aktiverar hook-slutpunkten och körningsflödet för mappningar för inkommande webhook-begäranden. Låt detta vara inaktiverat om du inte aktivt dirigerar externa händelser till Gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail-hook`},help:{"v1-4cibmt-4r":`Inställningar för Gmail-pushintegrering som används för Pub/Sub-aviseringar och valfri lokal hantering av återanrop. Begränsa om möjligt detta till särskilda Gmail-konton för automatisering.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Konto för Gmail-hook`},help:{"v1-12l1h96-4v":`Identifierare för det Google-konto som används för bevaknings- och prenumerationsåtgärder i Gmail i denna hook-integrering. Använd ett särskilt e-postkonto för automatisering för att isolera driftbehörigheter.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Tillåt osäkert externt innehåll i Gmail-hook`},help:{"v1-1w3gdvs-55":`Tillåter att externt Gmail-innehåll som genomgått mindre säkerhetsrensning skickas vidare till bearbetning när detta är aktiverat. Låt detta vara inaktiverat för säkrare standardinställningar och aktivera det endast för betrodda e-postflöden med kontrollerade omvandlingar.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Återanrops-URL för Gmail-hook`},help:{"v1-19fhn6q-4z":`Offentlig återanrops-URL som Gmail eller mellanhänder anropar för att leverera aviseringar till detta hook-flöde. Skydda denna URL med tokenvalidering och begränsad nätverksexponering.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Inkludera meddelandetext i Gmail-hook`},help:{"v1-14cf1c3-52":`När värdet är true hämtas och inkluderas e-postmeddelandets innehåll för efterföljande mappning och agentbearbetning. Behåll false om meddelandetexten inte behövs, eftersom detta ökar datamängdens storlek och känslighet.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Etikett för Gmail-hook`},help:{"v1-9zpdg8-4g":`Valfritt Gmail-etikettfilter som begränsar vilka etiketterade meddelanden som utlöser hook-händelser. Använd snäva filter för att undvika att överbelasta automatiseringar med orelaterad inkorgstrafik.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Maximal meddelandestorlek i byte för Gmail-hook`},help:{"v1-2aaxx1-4b":`Maximalt antal byte i Gmail-datamängden som bearbetas per händelse när includeBody är aktiverat. Använd försiktiga gränser för att minska kostnaderna och riskerna vid bearbetning av alltför stora meddelanden.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Åsidosättning av modell för Gmail-hook`},help:{"v1-1var65t-59":`Valfri åsidosättning av modell för Gmail-utlösta körningar när automatiseringar för brevlådan ska använda ett särskilt modellbeteende. Lämna värdet oangivet för att ärva agentens standardinställningar, om inte brevlådeuppgifterna kräver specialisering.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Push-token för Gmail-hook`},help:{"v1-h1vx01-4o":`Delad hemlig token som krävs vid återanrop till Gmails push-hook innan aviseringar bearbetas. Använd miljövariabelsubstitution och byt token regelbundet om återanropsändpunkterna exponeras externt.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Förnyelseintervall för Gmail-hook (min)`},help:{"v1-pr1z9-49":`Förnyelseintervall i minuter för Gmails bevakningsprenumerationer för att förhindra att de löper ut. Ange ett intervall som är kortare än leverantörens giltighetstid och övervaka misslyckade förnyelser i loggarna.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Lokal server för Gmail-hook`},help:{"v1-hom4wq-54":`Inställningsblock för en lokal callback-server som tar emot Gmail-aviseringar direkt utan ett separat ingresslager. Aktivera endast när den här processen själv ska ta emot webhook-trafiken.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Bindningsadress för Gmail-hookserver`},help:{"v1-55bieu-4d":`Bindningsadress för den lokala HTTP-servern för Gmail-callback som används när hookar hanteras direkt. Begränsa till loopback om inte extern ingress uttryckligen krävs.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Sökväg för Gmail-hookserver`},help:{"v1-1jqhcw4-4h":`HTTP-sökväg på den lokala callback-servern för Gmail där pushaviseringar tas emot. Se till att den stämmer överens med prenumerationskonfigurationen för att undvika förlorade händelser.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Port för Gmail-hookserver`},help:{"v1-1yku7dz-43":`Port för den lokala HTTP-servern för Gmail-callback när serverläget är aktiverat. Använd en dedikerad port för att undvika konflikter med gateway- och kontrollgränssnitt.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Prenumeration för Gmail-hook`},help:{"v1-127h8vg-5b":`Pub/Sub-prenumeration som gatewayen använder för att ta emot aviseringar om Gmail-ändringar från det konfigurerade ämnet. Håll prenumerationens ägarskap tydligt så att flera konsumenter inte oväntat konkurrerar om samma meddelanden.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale för Gmail-hook`},help:{"v1-7jzidp-4l":`Konfigurationsblock för Tailscale-exponering som publicerar Gmail-callbackar via Serve/Funnel-rutter. Använd privata tailnet-lägen innan någon offentlig ingressväg aktiveras.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Tailscale-läge för Gmail-hook`},help:{"v1-vhm395-4u":`Tailscale-exponeringsläge för Gmail-återanrop: "off", "serve" eller "funnel". Använd "serve" för privat leverans via tailnet och "funnel" endast när inkommande trafik från det publika internet krävs.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Tailscale-sökväg för Gmail-hook`},help:{"v1-fr8qi-4m":`Sökväg som publiceras av Tailscale Serve/Funnel för vidarebefordran av Gmail-återanrop när funktionen är aktiverad. Se till att den stämmer överens med Gmails webhook-konfiguration så att förfrågningar når den avsedda hanteraren.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Tailscale-mål för Gmail-hook`},help:{"v1-1twwxge-47":`Lokalt tjänstemål som Tailscale Serve/Funnel vidarebefordrar till (till exempel http://127.0.0.1:8787). Använd uttryckliga loopback-mål för att undvika tvetydig routning.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Åsidosättning av tankenivå för Gmail-hook`},help:{"v1-17owk9q-4z":`Åsidosättning av tankenivå för Gmail-drivna agentkörningar: "off", "minimal", "low", "medium" eller "high". Använd måttliga standardnivåer för rutinmässig automatisering av inkorgen för att hålla kostnader och svarstider nere.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Pub/Sub-ämne för Gmail-hook`},help:{"v1-fdm0kn-4t":`Namn på Google Pub/Sub-ämnet som Gmail-bevakningen använder för att publicera ändringsaviseringar för det här kontot. Kontrollera att ämnets IAM ger Gmail publiceringsbehörighet innan du aktiverar bevakningar.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Interna hookar`},help:{"v1-piq9k-4v":`Körtidsinställningar för interna hookar med medföljande eller anpassade händelsehanterare som läses in från modulsökvägar. Använd detta för betrodda automatiseringar i samma process och begränsa noggrant vilka hanterare som läses in.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Interna hookar aktiverade`},help:{"v1-1wv0289-4c":`Aktiverar bearbetning av interna hookar och konfigurerade poster i körmiljön för interna hookar. Låt vara inaktiverat om inte interna hookar har konfigurerats avsiktligt.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Poster för interna hookar`},help:{"v1-1ovi38l-4o":`Konfigurerade poster för interna hookar som används för att registrera specifika hanterare och metadata i körmiljön. Håll posterna explicita och versionshanterade så att beteendet i produktion kan granskas.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Inläsare för interna hookar`},help:{"v1-11re5ph-4p":`Inställningar för inläsaren för interna hookar som styr var hanterarmoduler hittas vid start. Begränsa rotkatalogerna för inläsning för att minska risken för oavsiktliga modulkonflikter eller att moduler skuggar varandra.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Extra kataloger för interna hookar`},help:{"v1-1xfdqxg-4c":`Ytterligare kataloger där interna hookmoduler söks utöver standardsökvägarna för inläsning. Håll antalet minimalt och under kontroll för att minska risken för att moduler oavsiktligt skuggar varandra.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Hookmappningar`},help:{"v1-frhp3v-5i":`Ordnade mappningsregler som matchar inkommande hookförfrågningar och väljer väcknings- eller agentåtgärder med valfri leveransroutning. Placera specifika mappningar först för att undvika att breda mönsterregler fångar allt.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Åtgärd för hookmappning`},help:{"v1-i2kbzp-4h":`Åtgärdstyp för mappningen: "wake" köar ett meddelande till den ägande sessionen, medan "agent" startar en oberoende agenttur. Sessionsmeddelanden avbryter inte pågående arbete.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Agent-ID för hookmappning`},help:{"v1-l0uioz-4y":`ID för målagenten som ska köra mappningen när åtgärdsroutningen inte ska använda standardvärden. Använd dedikerade automationsagenter för att isolera webhook-beteendet från interaktiva operatörssessioner.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Tillåt osäkert externt innehåll i hook-mappning`},help:{"v1-1np9426-57":`När värdet är true kan mappningsinnehållet inkludera mindre noggrant rensade externa nyttolastdata i genererade meddelanden. Behåll false som standard och aktivera endast för betrodda källor med granskad transformeringslogik.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Leveranskanal för hook-mappning`},help:{"v1-oz7pu5-5s":`Åsidosättning av leveranskanalen för mappningens utdata (till exempel "last", "telegram", "discord", "slack", "signal", "imessage" eller "msteams"). Ange kanalåsidosättningar uttryckligen för att undvika oavsiktliga utskick till andra kanaler.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Leverera svar från hook-mappning`},help:{"v1-12tbbam-5o":`Styr om resultaten från mappningskörningen levereras tillbaka till en kanaldestination eller bearbetas i bakgrunden utan utskick. Inaktivera leverans för bakgrundsautomationer som inte ska publicera utdata för användare.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Fördelningsnyckel för hook-mappning`},help:{"v1-1d593op-7e":`Nyckel till en array på nyttolastens toppnivå som mappningen fördelar körningar över: varje element utlöser en egen åtgärd, och mallar eller transformeringar får en nyttolast vars array endast innehåller det aktuella elementet. Gmail-förinställningen använder forEach: messages så att batchade push-händelser utlöser en körning per e-postmeddelande.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID för hook-mappning`},help:{"v1-q1t4zw-57":`Valfri stabil identifierare för en hook-mappningspost som används för granskning, felsökning och riktade uppdateringar. Använd unika ID:n så att loggar och konfigurationsdifferenser kan hänvisa entydigt till mappningar.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Matchning för hook-mappning`},help:{"v1-6u73k2-5a":`Grupperingsobjekt för mappningens matchningsvillkor, till exempel sökväg och källa, innan åtgärdsroutning tillämpas. Håll matchningskriterierna specifika så att orelaterad webhook-trafik inte utlöser automatiseringar.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Matchningssökväg för hook-mappning`},help:{"v1-1d7dc5j-4k":`Villkor för sökvägsmatchning i en hook-mappning, som vanligtvis jämförs med sökvägen för den inkommande begäran. Använd detta för att styra automatiseringsbeteendet utifrån grupper av sökvägar till webhook-slutpunkter.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Matchningskälla för hook-mappning`},help:{"v1-1nw7um7-4v":`Villkor för källmatchning i en hook-mappning, som vanligtvis anges via betrodda metadata från uppströmskällor eller adapterlogik. Använd stabila källidentifierare så att routningen förblir densamma vid återförsök.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Meddelandemall för hook-mappning`},help:{"v1-m0lqv5-5t":`Mall för att omvandla strukturerade indata för mappningen till det slutliga meddelandeinnehållet som skickas till målets åtgärdssökväg. Se till att samma indata ger samma meddelande så att efterföljande tolkning och beteende förblir stabila.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Åsidosättning av modell för hook-mappning`},help:{"v1-10qyo4j-5e":`Valfri åsidosättning av modell för mappningsutlösta körningar när automatiseringen ska använda en annan modell än agentens standardmodell. Använd detta sparsamt så att beteendet förblir förutsägbart mellan mappningskörningar.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Namn på hook-mappning`},help:{"v1-zrd9tn-4v":`Läsbart visningsnamn för mappningen som används i diagnostik och konfigurationsgränssnitt för operatörer. Håll namnen korta och beskrivande så att routningens syfte är tydligt vid incidentgranskning.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Sessionsnyckel för hook-mappning`},help:{"v1-lfnt1n-58":`Uttrycklig åsidosättning av sessionsnyckeln för meddelanden som levereras via mappningen, för att styra trådkontinuiteten. Använd stabila, avgränsade nycklar så att återkommande händelser kopplas samman utan att läcka in i orelaterade konversationer.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Sessionsläge för hook-mappning`},help:{"v1-1ggtdze-5k":`Styr sessionskontinuiteten för mappningen: "isolated" startar en ny körningssession, medan "persistent" återanvänder den fastställda sessionKey. Behåll isolated om inte integrationen uttryckligen behöver beständig kontext.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Textmall för hook-mappning`},help:{"v1-1rg732b-4y":`Reservmall med enbart text som används när rendering av formaterat meddelandeinnehåll inte önskas eller stöds. Använd denna för att tillhandahålla en kort och enhetlig sammanfattning för leverans i chattgränssnitt.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Åsidosättning av tänkande för hook-mappning`},help:{"v1-17hq8me-57":`Valfri åsidosättning av resonemangsnivån för körningar som utlöses av mappningar, för att balansera svarstid mot resonemangsdjup. Håll nivån låg eller minimal för hookar med hög volym om inte djupare resonemang tydligt behövs.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Tidsgräns för hookmappning (sek)`},help:{"v1-1r44ox2-4i":`Maximal tillåten körtid för mappningens åtgärd innan hantering av överskriden tidsgräns aktiveras. Använd snävare gränser för webhookkällor med hög volym för att förhindra att köer växer.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Leveransmål för hookmappning`},help:{"v1-1p7928e-55":`Målidentifierare i den valda kanalen när mappningens svar ska skickas till ett fast mål. Kontrollera leverantörsspecifika målformat innan du aktiverar mappningar i produktion.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformering för hookmappning`},help:{"v1-118nw83-5j":`Konfigurationsblock för transformering som anger modul/export för förbehandling innan mappningens åtgärd hanteras. Använd endast transformeringar från granskade kodvägar och håll beteendet reproducerbart för reproducerbar automatisering.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Export för hooktransformering`},help:{"v1-atn8v-4b":`Namngiven export som ska anropas från transformeringsmodulen. Om den utelämnas används modulens standardexport. Ange detta när en fil innehåller flera transformeringshanterare.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Modul för hooktransformering`},help:{"v1-56futq-4v":`Relativ sökväg till en transformeringsmodul som läses in från hooks.transformsDir för att skriva om inkommande nyttolaster före leverans. Håll modulerna lokala, granskade och fria från mönster för katalogtraversering.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Väckningsläge för hook-mappning`},help:{"v1-1vp6cpn-6m":`Schemaläggningsläge för väckning: "now" köar en sessionstur omedelbart, medan "next-heartbeat" tilldelar meddelandet till nästa schemalagda automatisering för sessionen som kan ta emot det. Uppskjutna väckningar kräver en aktiverad automatisering som kan ta emot meddelandet.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Sökväg till hook-slutpunkt`},help:{"v1-1l9ijzv-4u":"HTTP-sökväg som används av hook-slutpunkten (till exempel `/hooks`) på gatewayens kontrollserver. Använd en svårgissad sökväg och kombinera den med tokenvalidering för skydd i flera lager."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Förinställningar för hooks`},help:{"v1-dp8m0l-4v":`Namngivna paket med hook-förinställningar som tillämpas vid inläsning för att ange standardmappningar och standardbeteenden. Ange uttryckligen vilka förinställningar som används så att operatörer kan granska vilka automatiseringar som är aktiva.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Autentiseringstoken för hooks`},help:{"v1-1ihf6mv-82":`Delad bearer-token som kontrolleras vid mottagning av hook-anrop för att autentisera förfrågningar innan mappningar körs. Behandla innehavare som fullt betrodda anropare för hook-ingången, inte som en separat roll utan ägarbehörighet. Använd substitution med miljövariabler och rotera token regelbundet när webhook-slutpunkter är tillgängliga via internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Katalog för hook-transformeringar`},help:{"v1-1ayj9p0-4t":`Baskatalog för hook-transformeringsmoduler som refereras av mappningarnas transform.module-sökvägar. Använd en kontrollerad katalog i kodarkivet så att dynamiska importer förblir granskningsbara och förutsägbara.`}},logging:{label:{"v1-rq08xq-7":`Loggning`},help:{"v1-11an9pb-5e":`Inställningar för loggningens allvarlighetsgrad, utdatamål, formatering och maskering av känsliga data. Håll nivåer och maskering tillräckligt strikta för produktion samtidigt som användbar diagnostik bevaras.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Granskningslogg`},help:{"v1-1lauvy2-6w":`Begränsad granskningshistorik med enbart metadata för operatörens granskning. Poster för körningar och verktyg är aktiverade som standard; metadata om meddelandens livscykel är ett separat, integritetskänsligt tillval. Bakgrundsskrivningen sker efter bästa förmåga och är inte ett förlustfritt arkiv för regelefterlevnad.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Granskningslogg aktiverad`},help:{"v1-snknxb-4v":`Registrerar nya granskningshändelser för körningar, verktyg och meddelanden där granskning är aktiverad. Standard: true. Ändringar gäller omedelbart; godkända skrivningar slutförs och sparade rader förblir sökbara tills deras lagringstid löper ut.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Granskning av körningsidentitet`},help:{"v1-1ucirwv-5b":`Sparar begränsade uppgifter om kopplingen till körningsidentitet för granskning av en specifik körning. Standard: false. Kräver logging.audit.enabled och gäller nytillkomna körningar; befintliga kontexter förblir oförändrade.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Omfattning av meddelandegranskning`},help:{"v1-1yg4lc3-76":`Styr poster om meddelandens livscykel utan meddelandeinnehåll: "off" (standard), "direct" för endast kända direktkonversationer eller "all" för direkt-, grupp- och kanalkonversationer samt okända konversationstyper. Kräver logging.audit.enabled. Ändringar gäller efterföljande livscykelhändelser.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Loggnivå för konsolen`},help:{"v1-16badbd-5u":`Konsolspecifik loggtröskel: "silent", "fatal", "error", "warn", "info", "debug" eller "trace" för att styra terminalutdata. Använd detta för att minska mängden utdata i den lokala konsolen och samtidigt behålla mer detaljerad filloggning vid behov.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Format för konsollogg`},help:{"v1-d7u0iq-3q":`Format för konsolutdata: "pretty" eller "json". Använd json för maskinell bearbetning och pretty för terminalarbetsflöden där läsbarhet prioriteras.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Sökväg till loggfil`},help:{"v1-16gaitv-4w":`Valfri filsökväg för sparade loggutdata utöver eller i stället för konsolloggning. Använd en hanterad, skrivbar sökväg och anpassa lagringstid och rotation efter din driftpolicy.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Loggnivå`},help:{"v1-1r5yku0-5o":`Primär loggnivåtröskel för loggutdata under körning: "silent", "fatal", "error", "warn", "info", "debug" eller "trace". Behåll "info" eller "warn" i produktion och använd debug/trace endast vid felsökning.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Anpassade maskeringsmönster`},help:{"v1-11x24rh-8c":`Anpassade regex-strängar ersätter standardlistan med strängar för loggar och diagnostik. Inbyggda skydd för formulärdata, strukturerade autentiseringsuppgifter och fristående AWS-nycklar gäller alltid. Verktygsargument, resultat och chatthistorik maskeras inte. Använd detta för att maskera driftspecifika token och identifierare i diagnostikutdata.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Globala MCP-serverdefinitioner som hanteras av OpenClaw. Inbäddad OpenClaw och andra körmiljöadaptrar kan använda dessa servrar utan att lagra dem i projektspecifika inställningar som tillhör körmiljön.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP-appar`},help:{"v1-amyd91-38":`Stöd för MCP Apps-gränssnitt. När detta är aktiverat kan konfigurerade MCP-servrar tillhandahålla interaktiva HTML-vyer för sina verktygsresultat.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps aktiverat`},help:{"v1-ghqy98-3w":`Valfri rendering av MCP Apps och brygga mellan app och server. Låt detta vara inaktiverat om du inte litar på de konfigurerade MCP-servrar som tillhandahåller resurser för appgränssnitt.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Ursprung för MCP Apps-sandlåda`},help:{"v1-5lqj7v-6s":`Valfritt dedikerat offentligt HTTP(S)-ursprung för MCP Apps. Använd detta bakom en omvänd proxy eller TLS-terminator och vidarebefordra trafiken endast till den konfigurerade sandlådeporten för MCP Apps. Det måste skilja sig från webbappens ursprung och får inte tillhandahålla innehåll som kräver autentisering.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Port för MCP Apps-sandlåda`},help:{"v1-1b8n71l-4p":`Dedikerad lyssningsport för MCP Apps-sandlådan. Standardvärdet är Gateway-porten plus ett. Ange en ledig port om en annan lokal tjänst eller Gateway-profil redan använder den porten.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP-servrar`},help:{"v1-157ozoz-42":`Namngivna MCP-serverdefinitioner. OpenClaw lagrar dem i sin egen konfiguration, och körningsadaptrar avgör vilka transportmetoder som stöds vid körning.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Autentisering för MCP-server`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP-klientcertifikat`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP-klientnyckel`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP-klientcertifikat`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP-klientnyckel`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex MCP-projektion`},help:{"v1-slcmq1-6x":`Projektionsmetadata för OpenClaw enbart för Codex app-server-trådar. Detta påverkar inte ACP-sessioner eller generell konfiguration av Codex körmiljö. Utelämna detta block för att hålla servern tillgänglig för alla Codex app-server-agenter med Codex standardbeteende för MCP-godkännande.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex MCP-agenter`},help:{"v1-1i6v0fm-6a":`Valfria, icke-tomma OpenClaw-agent-ID:n som ska få denna MCP-server i trådkonfigurationen för Codex app-server. Listor utan giltiga agent-ID:n ger ingen åtkomst. Om listan utelämnas görs servern tillgänglig för alla Codex app-server-agenter.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Godkännande av Codex MCP-verktyg`},help:{"v1-1xql0qr-3d":`Codex egen stavning för samma servervisa godkännandeläge för MCP-verktyg. Använd helst defaultToolsApprovalMode i OpenClaw-konfigurationen.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Godkännande av Codex MCP-verktyg`},help:{"v1-y5vsqq-3s":`Valfritt godkännandeläge för Codex MCP-verktyg på denna server: "auto", "prompt" eller "approve". Använd endast för MCP-servrar som du medvetet litar på.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Tidsgräns för MCP-anslutning (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCP-server aktiverad`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Autentiseringsprofil för MCP OAuth`},help:{"v1-fcrb4u-5z":`ID för en autentiseringsprofil med stöd för förnyelse som används för att infoga aktuell bearer-token i denna fjärranslutna MCP-server. När detta anges hämtar och förnyar OpenClaw profilen vid körning utan att vidarebefordra förnyelseuppgifter till efterföljande system.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL för MCP OAuth-klientmetadata`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP OAuth-identitet`},help:{"v1-1ie6ys7-59":`Ägarskap för OAuth-autentiseringsuppgifter för denna server. Utelämna fältet eller använd "shared" för operatörshanterade autentiseringsuppgifter. Använd "per-requester" för att låta varje autentiserad avsändare ansluta sitt eget konto.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`Omdirigerings-URL för MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Behörighetsomfång för MCP OAuth`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Tidsgräns för MCP-begäran (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`TLS-verifiering för MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`TLS-verifiering för MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Parallella MCP-verktygsanrop`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Parallella MCP-verktygsanrop`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Val av MCP-verktyg`},help:{"v1-10poyzb-4v":`Val av MCP-verktyg per server. Använd include för att endast tillgängliggöra valda MCP-verktygsnamn, eller exclude för att dölja valda MCP-verktygsnamn. Posterna accepterar exakta namn och enkla jokerteckenmönster med '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Undantagna MCP-verktyg`},help:{"v1-ijrc5y-1u":`Exakta MCP-verktygsnamn eller enkla globmönster med '*' som ska döljas från den här servern.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Inkluderade MCP-verktyg`},help:{"v1-89fdfq-3o":`Exakta MCP-verktygsnamn eller enkla globmönster med '*' som ska exponeras från den här servern. Om detta utelämnas förblir alla serververktyg tillgängliga om de inte exkluderas.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL för inaktiv MCP-session (ms)`},help:{"v1-j9si74-87":`Valfri tidsgräns i millisekunder för att avveckla inaktiva MCP-körmiljöer i OpenClaw-sessioner. Om värdet inte anges eller är 0 hålls körmiljöerna igång tills sessionen rensas eller Gateway stängs av. Positiva värden avrundas nedåt; aktiva nyttjanderätter och väntande förvärv förhindrar avveckling. Körningsägda körmiljöer avvecklas fortfarande när deras engångskörning avslutas.`}},memory:{label:{"v1-oopaku-6":`Minne`},help:{"v1-1wlx40m-13":`Konfiguration för inbyggt minne (global).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Läge för minneshänvisningar`},help:{"v1-1q6dxr5-4u":`Styr om källhänvisningar visas i svar: "auto" visar hänvisningar när de är användbara, "on" visar dem alltid och "off" döljer dem. Behåll "auto" som standard för en balanserad signal-brusnivå.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Minnessökning`},help:{"v1-1ukbud1-25":`Vektorsökning i MEMORY.md och memory/*.md (åsidosättningar per agent stöds).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Cache för inbäddningar vid minnessökning`},help:{"v1-d8h2e4-5b":`Cachar beräknade inbäddningar för textsegment i SQLite så att omindexering och inkrementella uppdateringar går snabbare (standard: true). Låt detta vara aktiverat om du inte undersöker cachens korrekthet eller minimerar diskanvändningen.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Indatatyp för dokument vid minnessökning`},help:{"v1-1ui33sv-5f":"Valfritt leverantörsspecifikt `input_type`-värde för minnesinbäddningar vid dokumentbearbetning och indexering. Använd detta med OpenAI-kompatibla asymmetriska inbäddningsändpunkter som kräver en etikett för textavsnitt eller dokument."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Aktivera minnessökning`},help:{"v1-14f11b9-4t":`Huvudreglage för indexering och hämtning vid minnessökning i den här agentprofilen. Låt det vara aktiverat för semantisk återkallning och inaktivera det när du vill ha helt tillståndslösa svar.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Sessionsindex för minnessökning (experimentellt)`},help:{"v1-1y8ykw2-3b":`Indexerar chatthistorik för minnessökning. Behåll denna avancerade åsidosättning när arvet för återkallning skiljer sig mellan rotnivån och enskilda agenter.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Extra minnessökvägar`},help:{"v1-ojqokq-7i":`Lägger till extra kataloger eller .md-filer i minnesindexet utöver standardminnesfilerna. Poster kan vara sökvägssträngar eller objekt med ett rotrelativt glob-mönster. När multimodalt minne är aktiverat kan även matchande bild- och ljudfiler under dessa sökvägar indexeras.`}},"memory%2Esearch%2EextraPaths%2E*%2Eevergreen":{label:{"v1-1pdtd1w-r":`Tidlös extra minnessökväg`},help:{"v1-5y3z66-5f":`Undantar matchande referensfiler i extra sökvägar från tidsbaserad nedviktning utifrån filsystemets ändringstid. Detta ändrar endast rangordningen efter aktualitet; det gör inte innehållet betrott, ger det inte högre prioritet och ändrar inte källans ursprung.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Extra minnessökväg`},help:{"v1-b9mbq8-3m":`Anger den extra minneskatalogen eller minnesfilen. Relativa sökvägar utgår från agentens arbetsyta. Direkta filposter indexeras exakt som angivna.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Mönster för extra minnessökväg`},help:{"v1-j8br1v-4e":`Begränsar en katalogpost till filer som stöds och matchar detta rotrelativa glob-mönster, till exempel "runbooks/**/*.md". Utelämna det för att söka igenom alla filer som stöds rekursivt.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Reservleverantör för minnessökning`},help:{"v1-1r6368w-6p":`Reservleverantör som används när den primära inbäddningen misslyckas: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" eller "none". Ange en faktisk reservleverantör för tillförlitlig drift i produktion; använd "none" endast om du föredrar uttryckliga fel.`}},"memory%2Esearch%2EinputFormat":{label:{"v1-1qisc0t-q":`Indataformat för minnessökning`},help:{"v1-xus8vr-b2":`Valfria ordagranna textprefix i par för inbäddning av sökfrågor och dokument, till exempel { query: "query: ", document: "passage: " }. Ersätter automatisk modellformatering, även för modellalias. Båda strängarna krävs; blanksteg och radbrytningar bevaras, och tomma strängar väljer råtext. Ett icke-tomt queryInstruction har företräde för sökfrågor. Om dokumentprefixet ändras krävs omindexering.`}},"memory%2Esearch%2EinputFormat%2Edocument":{label:{"v1-ml4fv9-t":`Dokumentprefix för minnessökning`},help:{"v1-m9hsjw-4q":`Ordagrant prefix för dokumentinbäddningar. En tom sträng väljer rå dokumenttext. Om detta prefix ändras ändras identiteten för indexet och inbäddningscachen, vilket kräver omindexering.`}},"memory%2Esearch%2EinputFormat%2Equery":{label:{"v1-16lu8lu-q":`Sökfrågeprefix för minnessökning`},help:{"v1-hxaub1-3u":`Ordagrant prefix för sökfrågeinbäddningar. Används om inte ett icke-tomt queryInstruction har angetts; en tom sträng inaktiverar automatisk formatering av sökfrågor.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Indatatyp för minnessökning`},help:{"v1-26vbwe-5u":"Använd detta valfria leverantörsspecifika `input_type`-värde endast när samma etikett ska gälla för både fråge- och dokumentinbäddningsanrop. För asymmetriska leverantörer bör du i stället använda queryInputType och documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Sökväg till lokal inbäddningsmodell`},help:{"v1-13ymbnt-5q":"Anger källan till den lokala inbäddningsmodellen för lokal minnessökning, till exempel en sökväg till en GGUF-fil eller en `hf:`-URI. Använd detta endast när provider är `local`, och kontrollera modellens kompatibilitet innan du bygger om stora index."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Modell för minnessökning`},help:{"v1-11pohrl-59":`Åsidosätter inbäddningsmodellen för den valda minnesleverantören när en annan modell än standardmodellen krävs. Ange detta endast när du behöver finjustera återhämtningskvalitet eller kostnad utöver leverantörens standardinställningar.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Multimodal minnessökning`},help:{"v1-1jn02s-9e":'Valfria multimodala minnesinställningar för indexering av bild- och ljudfiler från konfigurerade extra sökvägar. Låt detta vara avstängt om inte din inbäddningsmodell uttryckligen stöder inbäddningar över flera modaliteter, och sätt `memory.search.fallback` till "none" när det är aktiverat. Matchande filer laddas upp till den konfigurerade fjärrleverantören för inbäddningar under indexeringen.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Aktivera multimodal minnessökning`},help:{"v1-1dk5d7o-7e":`Aktiverar indexering av bilder och ljud från extraPaths i minnet. Detta kräver för närvarande Gemini embedding-2, begränsar standardrotkatalogerna för minnet till Markdown, inaktiverar reservleverantörer för minnessökning och laddar upp matchande binärt innehåll till den konfigurerade fjärrleverantören för inbäddningar.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Maximal filstorlek i byte för multimodal minnessökning`},help:{"v1-1mmdrvk-5d":`Anger det maximala antalet byte som tillåts per multimodal fil innan den hoppas över vid minnesindexering. Använd detta för att begränsa uppladdningskostnaden och indexeringstiden, eller höj gränsen för korta ljudklipp med hög kvalitet.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modaliteter för multimodal minnessökning`},help:{"v1-alp4vh-4l":`Väljer vilka multimodala filtyper som indexeras från extraPaths: "image", "audio" eller "all". Begränsa urvalet för att undvika att oavsiktligt indexera stora samlingar av binärdata.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Utdatadimensionalitet för minnessökning`},help:{"v1-jx51wj-dm":"Leverantörsspecifik åsidosättning av utdatavektorns storlek för minnesinbäddningar. Gemini-modeller stöder 128–3072 dimensioner och rekommenderar 768, 1536 eller 3072; Bedrock-familjer som Titan V2, Cohere V4 och Nova har sina egna tillåtna storlekar. OpenAI-kompatibla ändpunkter tar emot värdet som `dimensions` och måste returnera vektorer av exakt den storleken. Hanterade lokala GGUF-inbäddningar trunkeras och normaliseras lokalt. Räkna med en fullständig omindexering när du ändrar värdet, eftersom lagrade vektordimensioner måste förbli enhetliga."}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Leverantör för minnessökning`},help:{"v1-5evseb-71":`Väljer den inbäddningsbackend som används för att skapa och söka i minnesvektorer. Standardvärdet är "openai"; ange "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" eller "local" om du vill använda en annan backend.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Maximalt antal resultat vid minnessökning`},help:{"v1-13ekath-4x":`Maximalt antal minnesträffar som returneras från sökningen innan de rangordnas på nytt och infogas i prompten. Höj värdet för bredare täckning eller sänk det för mer fokuserade promptar och snabbare svar.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Lägsta poäng vid minnessökning`},help:{"v1-1ww231l-4v":`Lägsta relevanspoäng som krävs för att minnesresultat ska inkluderas i det slutliga hämtningsresultatet. Höj värdet för att minska antalet svaga eller brusiga träffar, eller sänk det när du behöver mindre restriktiv hämtning.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Indatatyp för minnessökfrågor`},help:{"v1-831yrv-4q":"Valfritt leverantörsspecifikt `input_type`-värde för minnesinbäddningar vid sökning. Använd detta med OpenAI-kompatibla slutpunkter för asymmetrisk inbäddning som kräver en frågeetikett."}},"memory%2Esearch%2EqueryInstruction":{label:{"v1-izdliq-v":`Frågeinstruktion för minnessökning`},help:{"v1-19u8npy-b1":`Valfritt ordagrant prefix för sökfrågeinbäddningar, till exempel "search_query: ". Ta med nödvändiga blanksteg eller radbrytningar. Icke-tomma värden ersätter inputFormat.query och automatisk formatering av sökfrågor; om värdet inte har angetts eller är tomt används inputFormat.query om det har angetts, annars leverantörens standardvärden. Dokument och indexidentitet förblir oförändrade, så ingen omindexering behövs. Ett tomt agentspecifikt åsidosättningsvärde tar bort den ärvda instruktionen.`}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Kom ihåg mellan konversationer`},help:{"v1-1r9xto0-7s":`Använd relevant kontext från agentens andra privata konversationer genom skyddad återkallning av chatthistorik. Aktiveras som standard endast när den globala inställningen session.dmScope inte är angiven eller är "main" och ingen bindning åsidosätter omfattningen för direktmeddelanden. Om någon isolering av direktmeddelanden har konfigurerats är funktionen avstängd som standard. Ett uttryckligt true eller false har alltid företräde.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`API-nyckel för fjärrinbäddning`},help:{"v1-nfuuu-62":`Anger en separat API-nyckel för fjärranrop som skapar inbäddningar för minnesindexering och sökfrågor. Använd detta när minnesinbäddningar ska använda andra autentiseringsuppgifter än globala standardvärden eller miljövariabler.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Bas-URL för fjärrinbäddningar`},help:{"v1-1ugvqgt-5p":`Åsidosätter API-slutpunkten för inbäddningar, till exempel en OpenAI-kompatibel proxy eller en anpassad bas-URL för Gemini. Använd detta endast vid routning via en egen gateway eller leverantörsslutpunkt; behåll annars leverantörens standardvärden.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Batchbearbetning av fjärrinbäddningar aktiverad`},help:{"v1-1fehqi-5x":`Aktiverar leverantörens batch-API:er för inbäddningsjobb när de stöds (OpenAI/Gemini), vilket ökar genomströmningen vid större indexeringskörningar. Behåll detta aktiverat om du inte felsöker fel i leverantörens batchbearbetning eller kör mycket små arbetsbelastningar.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`HTTP-huvuden för fjärrinbäddningar`},help:{"v1-1uic0kd-5i":`Lägger till anpassade HTTP-huvuden i förfrågningar om fjärrinbäddningar och kombinerar dem med leverantörens standardvärden. Använd detta för proxyautentisering och huvuden för klientorganisationsroutning, och begränsa värdena till det nödvändigaste för att undvika att känsliga metadata läcker.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Källor för minnessökning`},help:{"v1-1xxndig-4q":`Väljer vilka källor som indexeras: "memory" läser MEMORY.md + minnesfiler, och "sessions" inkluderar chatthistorik. Behåll ["memory"] om du inte behöver återkalla information från tidigare chattar.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Vektorindex för minnessökning`},help:{"v1-fbybkj-37":`Styr det semantiska indexet i sqlite-vec. Behåll denna avancerade åsidosättning när vektorpolicyerna på rotnivå och för enskilda agenter skiljer sig åt.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Sökväg till vektortillägg för minnessökning`},help:{"v1-1hysv5q-58":"Åsidosätter den automatiskt identifierade sökvägen till tilläggsbiblioteket sqlite-vec (`.dylib`, `.so` eller `.dll`). Använd detta när körmiljön inte kan hitta sqlite-vec automatiskt eller när du vill låsa till en version som du vet fungerar."}},messages:{label:{"v1-1wwzqad-8":`Meddelanden`},help:{"v1-i5k0iw-5k":`Meddelandeinfrastruktur och standardinställningar som gäller för alla agenter. Likställda poster på rotnivå ansvarar för infrastruktur och agentgemensamma standardinställningar; agents.defaults ansvarar för agentloopens beteende; agentposter kan åsidosätta båda där det stöds.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji för bekräftelsereaktion`},help:{"v1-1iip0zs-1x":`Emojireaktion som används för att bekräfta inkommande meddelanden (tomt värde inaktiverar).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Omfattning för bekräftelsereaktioner`},help:{"v1-1jvdg5n-7s":`När bekräftelsereaktioner ska skickas ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" bekräftar gruppmeddelanden som nämner agenten, oavsett om gruppen kräver omnämnanden eller inte; "group-all" bekräftar varje gruppmeddelande. "off"/"none" inaktiverar bekräftelsereaktioner helt.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Regler för gruppchatt`},help:{"v1-chqsvh-4l":`Inställningar för hantering av gruppmeddelanden, inklusive utlösare för omnämnanden och historikfönstrets storlek. Håll omnämningsmönstren snäva så att inte varje meddelande i gruppkanaler utlöser en åtgärd.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Gräns för grupphistorik`},help:{"v1-1mkbpw-9k":`Maximalt antal tidigare gruppmeddelanden som läses in som kontext per tur i gruppsessioner. Använd högre värden för bättre kontinuitet eller lägre värden för snabbare och billigare svar. Automatisk prompthistorik är begränsad till 200 meddelanden. Det maximala JSON-heltalsvärdet väljer kanalens standardfönster (50 för delad grupphistorik), inte ett obegränsat fönster.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Mönster för omnämnanden i grupper`},help:{"v1-i7h7qc-6f":`Säkra, skiftlägesokänsliga reguljära uttryck som används för att identifiera uttryckliga omnämnanden eller utlösande fraser i gruppchattar. Använd precisa mönster för att minska antalet falska träffar i kanaler med hög trafik; ogiltiga eller osäkra mönster med nästlade upprepningar ignoreras.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Inkommande gruppmeddelanden utan omnämnande`},help:{"v1-17wef8h-5f":`Styr hur löpande gruppkonversationer utan omnämnanden skickas in när ständig bevakning är aktiverad. "user_request" behandlar dem som användarförfrågningar; "room_event" skickar in dem som tyst kontext där synliga svar kräver meddelandeverktyget.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Synliga svar i grupper`},help:{"v1-qa4z1s-aa":`Åsidosätter modellskrivna svar till ursprungskonversationen i grupper och kanaler. Standardvärdet är "automatic" när ingen global policy för synliga svar har angetts. "message_tool" kräver message(action=send) för vanliga assistentsvar och generella medier från verktyg; utdata under körning som uttryckligen ägs av värdsystemet kan fortfarande levereras, utom vid bakgrundshändelser i rummet. "automatic" publicerar vanliga svar som tidigare.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Fördröjd samling av inkommande meddelanden`},help:{"v1-ebyu5x-4a":`Inställningar för fördröjd samling av inkommande direktmeddelanden innan kö- eller turbearbetning startar. Konfigurera detta för leverantörsspecifika skurar av snabba meddelanden från samma avsändare.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Samlingsfördröjning för inkommande meddelanden per kanal (ms)`},help:{"v1-wbz54j-4g":`Kanalspecifika åsidosättningar av samlingsfördröjningen för inkommande meddelanden i millisekunder, med leverantörs-id som nyckel. Använd detta när vissa leverantörer skickar meddelandefragment tätare än andra.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Samlingsfördröjning för inkommande meddelanden (ms)`},help:{"v1-1616yo2-7w":`Tystnadsintervall (ms) för att samla snabba inkommande meddelanden från samma avsändare. Telegram använder 300 ms som standard när varken en global eller kanalspecifik åsidosättning har angetts. Övriga kanaler använder 0 som standard. Noll inaktiverar vanlig samling av meddelandeskurar, men Telegram sammanfogar fortfarande delar av långa meddelanden som ligger nära längdgränsen.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Inkommande kö`},help:{"v1-hm2o31-48":`Köstrategi för inkommande meddelanden som anländer medan en sessionskörning är aktiv. Använd detta för att anpassa styrning, uppskjutna uppföljningar, samling eller avbrott.`}},"messages%2Equeue%2EallowCollaborativeSteering":{label:{"v1-95t3u6-s":`Tillåt gemensam styrning`},help:{"v1-1pyzwb-ip":`Tillåt godkänd mänsklig inmatning i samma konversation att styra med den aktiva turens oförändrade identitet och förberedda behörigheter, även när avsändaren har färre behörigheter (standard: true). WebUI med delade inloggningsuppgifter och kanalinmatning kan också fortsätta exakt samma aktiva session. Vid false kräver det undantaget aktuella administratörsbehörigheter i WebUI och kanalägarbehörigheter; verifierad personlig kontinuitet är också fortsatt tillgänglig. Annars väljer collaborativeSteeringFallback en diskret köad tur som ägs av den som gjort begäran (queue) eller ett strikt avslag (reject). Aktuell åtkomst, aktuella körningsbehörigheter, kontroller av körningsinställningar, kölägen och behörighet för styrning mellan sessioner gäller fortfarande.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Köläge per kanal`},help:{"v1-1vbyy4u-5q":`Kanalspecifika åsidosättningar av köläget med kanal-ID som nyckel, inklusive pluginkanaler (till exempel discord, telegram, x). Använd detta när en kanals trafikmönster kräver ett annat beteende än de globala standardinställningarna.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Kökapacitet`},help:{"v1-16ql8c7-4j":`Maximalt antal inkommande objekt som behålls i kön innan borttagningspolicyn tillämpas. Standardvärdet är 20; håll kapaciteten begränsad i kanaler med mycket trafik så att minnesanvändningen förblir förutsägbar.`}},"messages%2Equeue%2EcollaborativeSteeringFallback":{label:{"v1-3k0wft-v":`Reservåtgärd för gemensam styrning`},help:{"v1-peu9fu-8i":`Vad som händer när en annan person inte kan styra eftersom samarbetsstyrning är inaktiverad: "queue" (standard) kör personens inmatning som en separat tur utan statusmeddelande; "reject" behåller strikt avslag och kräver en ny /followup-begäran. Aktiverar inte samarbetsstyrning och kringgår inte åtkomstkontroller.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Reservfördröjning för kö per kanal (ms)`},help:{"v1-1w7gk9b-54":`Kanalspecifika åsidosättningar av köfördröjningen med kanal-ID som nyckel, inklusive pluginkanaler. Använd detta för att anpassa hanteringen av meddelandetoppar separat för chattytor med olika tempo.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Borttagningsstrategi för kö`},help:{"v1-ydb2rw-6m":`Borttagningsstrategi när kökapaciteten överskrids. "summarize" tar bort de äldsta posterna men bevarar korta sammanfattningar; "old" tar bort de äldsta utan sammanfattningar; "new" avvisar det senaste objektet. Använd "summarize" för långvariga chattar där sammanhanget är viktigt.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Köläge`},help:{"v1-19k7gy1-67":`Köläge för aktiva körningar. Använd "steer" för att infoga promptar i den aktiva körningen, "followup" för att köra senare, "collect" för att samla kompatibla meddelanden för senare batchkörning eller "interrupt" för att avbryta den aktiva körningen innan den senaste prompten startas.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Prefix för utgående svar`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Standardläge för användningsinformation i sidfoten`},help:{"v1-l3shsx-dv":`Standardläge för sidfoten med användningsinformation per svar ("off"|"tokens"|"full"), som tilldelas sessioner som inte har valt ett läge via /usage. Accepterar även "on" som ett äldre alias för "tokens". Accepterar ett enskilt läge eller en mappning per kanal med "default" som reservvärde. Prioritetsordning: sessionsvärde -> kanalpost -> default -> off; ett uttryckligt val via /usage (inklusive off) sparas och åsidosätter standardvärdet. Använd /usage reset (alias: inherit, clear, default) för att ta bort en sessionsspecifik inställning och åter ärva detta konfigurerade standardvärde.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Statusreaktioner`},help:{"v1-193764l-3s":`Statusreaktioner under livscykeln som uppdaterar emojin på det utlösande meddelandet allteftersom agenten arbetar (köad → tänker → verktyg → klar/fel).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Aktivera statusreaktioner`},help:{"v1-1qnmmnc-7x":`Aktivera statusreaktioner under livscykeln på kanaler som stöds. Discord tolkar ett ej angivet värde som aktiverat när bekräftelsereaktioner är aktiva; Slack, Signal, Telegram och WhatsApp kräver att detta är true innan livscykelreaktioner används. Slack använder som standard sin inbyggda status för assistenttrådar för att visa förloppet.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Mall för användningssidfot`},help:{"v1-1xibc23-47":`Anpassad sidfotsmall för /usage full, antingen som ett inline-objekt eller en sökväg till en JSON-fil. Om mallen är ogiltig eller inte tillgänglig används den inbyggda raden med användningsinformation.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Synliga svar`},help:{"v1-7yfwc2-8t":`Styr modellgenererade ursprungssvar i direkt-, grupp- och kanalkonversationer. "message_tool" kräver message(action=send) för vanliga assistentsvar och generiska verktygsmedier; utdata vid körning som uttryckligen ägs av värden kan fortfarande levereras, med undantag för bakgrundshändelser i rummet. "automatic" publicerar vanliga svar som tidigare.`}},meta:{label:{"v1-1xpfxac-m":`Kompatibilitetsmetadata`},help:{"v1-1owqhgn-2w":`Kompatibilitetsmetadata som kan läsas av äldre versioner och behålls så att äldre binärfiler kan avvisa osäkra nedgraderingar av konfigurationen.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Version som senast ändrade konfigurationen`},help:{"v1-qykpv1-1i":`Den OpenClaw-version som senast skrev den här konfigurationen.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Markörer för konfigurationsmigrering`},help:{"v1-burt8q-1q":`Avgränsade kompatibilitetsmarkörer för slutförda konfigurationsmigreringar.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migrering av modellpolicyns tillåtelselista`},help:{"v1-5psop1-1z":`Registrerar att äldre begränsningar i modellmappningen har bevarats eller utvärderats.`}},"meta%2Emigrations%2EskillLibraryToolSplit":{label:{"v1-1x6n7ed-y":`Migrering för uppdelning av färdighetsbibliotekets verktyg`},help:{"v1-jph48r-3s":`Registrerar att verktygspolicyer som omfattar skill_workshop utökades till skill_library när redigering av det personliga biblioteket flyttades till ett eget verktyg.`}},"meta%2Emigrations%2EskillWorkshopPlugin":{label:{"v1-1703542-v":`Migrering av Skill Workshop-tillägg`},help:{"v1-1y4ur5t-2i":`Registrerar att policyn för Skill Workshop-tillägget som skrevs när Workshop var inbyggt har tagits bort.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migrering för separering av hjälpmodeller`},help:{"v1-vzdfqx-2t":`Registrerar att äldre implicit valda primära modeller har bevarats innan valet av hjälpmodell separerades.`}},models:{label:{"v1-hzmwb-6":`Modeller`},help:{"v1-1h1niol-5q":`Modellkatalogens rot för leverantörsdefinitioner, beteende vid sammanslagning eller ersättning samt valfri integration med Bedrock för modellidentifiering. Håll leverantörsdefinitionerna explicita och validerade innan du förlitar dig på reservvägar i produktion.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Uppdatering av modellkatalogen`},help:{"v1-1hess4t-40":`Styr bakgrundsuppdateringar av den medföljande modellkatalogen. Fjärrposter kan uppdatera modellmetadata men inte ändra leverantörernas ändpunkter eller HTTP-huvuden.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Uppdatering av modellkatalog aktiverad`},help:{"v1-1fogpjj-3j":`Hämta uppdateringar av den fjärrlagrade modellkatalogen i bakgrunden (standard: true). Ange false för att inaktivera all fjärrtrafik för modellkatalogen.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL för uppdatering av modellkatalog`},help:{"v1-ai1thy-6o":`Åsidosätt den fjärrlagrade modellkatalogens URL med en egen HTTPS-spegel (HTTP på localhost tillåts för testning). En Gateway som körs slutar använda katalogen från den tidigare källan och börjar använda spegelns vid nästa katalogkontroll, utan omstart.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Modellkatalogläge`},help:{"v1-1ofrnsp-es":`Styr leverantörskatalogens beteende: "merge" behåller inbyggda leverantörer och lägger dina anpassade leverantörer ovanpå, medan "replace" endast använder dina konfigurerade leverantörer. I "merge" bevaras icke-tomma baseUrl-värden i agentens models.json för matchande leverantörs-ID:n, medan apiKey-värden endast bevaras när leverantören inte hanteras via SecretRef i den aktuella konfigurations-/autentiseringsprofilkontexten. Leverantörer som hanteras via SecretRef uppdaterar apiKey från aktuella källmarkörer, och för matchande modellers contextWindow/maxTokens används det högre värdet av de explicita och implicita posterna.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Modellleverantörer`},help:{"v1-7b5l2y-fo":`Konfigurationer för modelländpunkter med leverantörs-ID som nyckel. Välj ett nytt ID, till exempel gpu-a eller my-lab, för en fristående anpassad ändpunkt. Inbyggda ID:n och alias samt de som tillhör tillägg behåller sin integrationssemantik; om du konfigurerar ett sådant tillämpas inställningarna ovanpå den integrationen. ID:t väljer inte kommunikationsprotokollet: det gör api. Flera anpassade ID:n kan använda samma adapter med olika bas-URL:er, autentiseringsuppgifter och modeller. Använd ett separat ID för en fristående server i stället för att återanvända openai bara för att servern är OpenAI-kompatibel. Anpassade poster måste innehålla baseUrl och models.`}},"models%2Eproviders%2E*":{help:{"v1-1sjqhly-54":`En namngiven leverantörskonfiguration. Ersätt * med ditt valda ID eller ett befintligt integrations-ID som du avsiktligt vill åsidosätta. Schemauppslagning fungerar innan ett anpassat ID har konfigurerats.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Körmiljö för modellleverantör`},help:{"v1-1luy4fb-5o":`Valfri lågnivåpolicy för agentens körmiljö för den här leverantören. Använd en körmiljöpolicy per leverantör/modell i stället för att låsa körmiljön för hela agenten. Om värdet utelämnas eller standardvärdet används väljer OpenClaw körmiljön för den valda leverantören.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Körmiljö-ID för modellleverantör`},help:{"v1-1gusd9s-69":`ID för leverantörens agentkörmiljö: "openclaw", "auto", ett registrerat ID för en pluginbaserad agentmotor, till exempel "codex", eller ett alias för en CLI-backend som stöds, till exempel "claude-cli". OpenAI på den officiella ändpunkten använder Codex-agentmotorn som standard om värdet utelämnas.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`API-adapter för modellleverantör`},help:{"v1-jpi8x4-6e":`Adapter för kommunikationsprotokoll, oberoende av leverantörs-ID:t. Chat Completions: openai-completions; Responses: openai-responses; Messages: anthropic-messages. Välj andra adaptrar bland de tillåtna värdena så att de matchar protokollet hos den bakomliggande tjänsten.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`API-nyckel för modellleverantör`},help:{"v1-1p84k96-54":`Autentiseringsuppgift för leverantören som används för API-nyckelbaserad autentisering när leverantören kräver direkt nyckelautentisering. Använd substitution med hemligheter eller miljövariabler och undvik att lagra riktiga nycklar i versionshanterade konfigurationsfiler.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Autentiseringsläge för modellleverantör`},help:{"v1-1g4jg7x-et":`Väljer autentiseringsmetod för leverantören: "api-key" för autentisering med API-nyckel, "token" för autentisering med bearer-token, "oauth" för OAuth-autentiseringsuppgifter, "aws-sdk" för hämtning av AWS-autentiseringsuppgifter och "none" för anpassade openai-completions-slutpunkter som inte kräver autentisering. Ett uttryckligt val av "none" hoppar över autentiseringsuppgifter och skickar ingen Authorization-header; andra adaptrar som faktiskt används avvisas. "native-command" överlåter hanteringen av autentiseringsuppgifter till en uttryckligen konfigurerad Codex-körmiljö för en anpassad HTTPS Responses-leverantör; det kan inte kombineras med API-nycklar, profiler eller åsidosättningar av förfrågningar.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Authorization-header för modellleverantör`},help:{"v1-1gn3lt3-59":`Om värdet är true skickas autentiseringsuppgifter via HTTP-headern Authorization även om alternativ autentisering är möjlig. Använd detta endast när din leverantör eller proxy uttryckligen kräver vidarebefordran av Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Bas-URL för modellleverantör`},help:{"v1-1ku88v8-53":`Bas-URL för den leverantörsslutpunkt som hanterar modellförfrågningar för denna leverantörspost. Använd HTTPS-slutpunkter och håll URL:er miljöspecifika med konfigurationsmallar vid behov.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`HTTP-headers för modellleverantör`},help:{"v1-chg59u-4x":`Statiska HTTP-headers som läggs till i leverantörsförfrågningar för klientorganisationsrouting, proxyautentisering eller anpassade gatewaykrav. Använd detta sparsamt och lagra känsliga headervärden som hemligheter.`}},"models%2Eproviders%2E*%2Eicon":{label:{"v1-1cwoqcc-j":`Ikon för modellleverantör`},help:{"v1-opei4i-9m":`Valfri leverantörsbild: en lokal fil, en offentlig HTTPS-bildadress eller en medföljande ikon. Källor i PNG-, JPEG-, WebP- och GIF-format är begränsade till 2 MiB och 4096 pixlar per sida och tillhandahålls som en sanerad statisk PNG-bild. Relativa filsökvägar utgår från katalogen för den aktiva konfigurationsfilen. Om bilden är ogiltig används leverantörens varumärkesikon eller visningsnamnets första bokstav.`}},"models%2Eproviders%2E*%2Eicon%2Ename":{label:{"v1-btu3z4-r":`Medföljande ikon för modellleverantör`},help:{"v1-14mjg6a-3j":`Namn på en ikon som ingår i webbappen, till exempel server. Vid ett okänt namn används i stället leverantörens inbyggda varumärkesikon eller initialen i visningsnamnet.`}},"models%2Eproviders%2E*%2Eicon%2Epath":{label:{"v1-1pddy1u-o":`Ikonfil för modellleverantör`},help:{"v1-1fgtl8e-73":`Sökväg till en PNG-, JPEG-, WebP- eller GIF-bild lokalt på Gateway. Relativa sökvägar utgår från katalogen som innehåller den aktiva konfigurationsfilen; ~/ expanderas till Gateway-användarens hemkatalog. Endast denna konfigurerade bild exponeras via den leverantörsspecifika resursrutten.`}},"models%2Eproviders%2E*%2Eicon%2Esource":{label:{"v1-13ahm5t-q":`Ikonkälla för modellleverantör`},help:{"v1-173lyjy-3i":`Bildkälla: file för en bild lokalt på Gateway, url för en offentlig HTTPS-bild eller builtin för en ikon som ingår i webbappen.`}},"models%2Eproviders%2E*%2Eicon%2Eurl":{label:{"v1-1euf5yl-n":`Ikon-URL för modellleverantör`},help:{"v1-147pn2x-65":`Offentlig HTTPS-URL till en PNG-, JPEG-, WebP- eller GIF-bild utan inbäddade autentiseringsuppgifter eller fragment. Gateway hämtar och sanerar bilden med skydd mot åtkomst till privata nätverk och omdirigeringar; webbläsaren kontaktar aldrig denna URL direkt.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Infogning av num_ctx för modellleverantör (OpenAI-kompatibel)`},help:{"v1-53rmcr-6n":"Styr om OpenClaw infogar `options.num_ctx` för Ollama-leverantörer som konfigurerats med den OpenAI-kompatibla adaptern (`openai-completions`). Standardvärdet är true. Ange false endast om din proxy eller uppströmsserver avvisar okända `options`-fält i nyttolasten."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Lokal tjänst för modellleverantör`},help:{"v1-9r1lm6-4y":`Valfri lokal modellserverprocess som startas vid behov för denna leverantör. OpenClaw kontrollerar healthUrl, startar kommandot vid behov, väntar tills tjänsten är redo och skickar sedan modellförfrågan.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argument för modellleverantörens lokala tjänst`},help:{"v1-t12wib-27":`Argumentlista som skickas till kommandot för den lokala modellservern utan skalexpansion.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Kommando för modellleverantörens lokala tjänst`},help:{"v1-64k3ef-4h":`Absolut sökväg till den körbara filen för den lokala modellserverprocessen. Ange sökvägen uttryckligen så att leverantörens start är förutsägbar och inte beror på skalets PATH-sökning.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Arbetskatalog för modellleverantörens lokala tjänst`},help:{"v1-fi3xlx-1h":`Arbetskatalog för den lokala modellserverprocessen.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Miljö för modellleverantörens lokala tjänst`},help:{"v1-1lwb9k1-3k":`Ytterligare miljövariabler för den lokala modellserverprocessen. Värden som verkar vara hemliga maskeras i ögonblicksbilder av konfigurationen.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL för hälsokontroll av modellleverantörens lokala tjänst`},help:{"v1-12nvqxl-36":`URL som kontrolleras före modellförfrågningar för att säkerställa att tjänsten är redo. Om den utelämnas använder OpenClaw leverantörens baseUrl med /models tillagt.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Stopp vid inaktivitet för modellleverantörens lokala tjänst`},help:{"v1-1efg054-3z":`Antal millisekunder som en lokal modellserver startad av OpenClaw hålls igång efter att den senaste förfrågan har slutförts. Ange 0 för att hålla den igång tills OpenClaw avslutas.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Tidsgräns för att modellleverantörens lokala tjänst ska bli redo`},help:{"v1-bwmfqa-2r":`Maximal väntetid i millisekunder för kontrollen av att den lokala modellservern är redo efter att processen har startats.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Maximalt antal token för modellleverantör`},help:{"v1-fnj50y-38":`Standardgräns för maximalt antal utdatatoken för modeller hos den här leverantören när en modellpost inte anger maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Modellista för modellleverantör`},help:{"v1-1vbm0gt-63":`Deklarerad modellista för en leverantör med identifierare, metadata, leverantörsspecifika parametrar och valfria uppgifter om kompatibilitet och kostnad. Låt ID:n matcha värdena i leverantörens katalog exakt så att val och reservval fungerar korrekt.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Körmiljö för modell`},help:{"v1-1k70g2n-3g":`Valfri lågnivåpolicy för agentens körmiljö för den här specifika modellen. Modellens körmiljöpolicy åsidosätter leverantörens körmiljöpolicy.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`ID för modellens körmiljö`},help:{"v1-1llzv33-42":`ID för modellagentens körmiljö: "openclaw", "auto", ett registrerat ID för ett plugin-ramverk som "codex", eller ett alias för en CLI-backend som stöds, som "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Medieindata för modell`},help:{"v1-wxtj8e-2x":`Valfria metadata om modellens mediefunktioner som verktyg använder för att välja försiktiga standardinställningar för bildkomprimering.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Bildindata för modell`},help:{"v1-1nviirq-3c":`Valfria begränsningar för bildindata för den här modellen, till exempel maximal sidlängd, maximalt antal pixlar och önskad sidlängd vid komprimering.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Maximal bildstorlek i byte för modellen`},help:{"v1-c2469j-23":`Maximal storlek på kodad bilddata som leverantören accepterar för den här modellen.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Maximalt antal bildpixlar för modellen`},help:{"v1-9d6yqp-1u":`Maximalt antal pixlar i en bild som leverantören accepterar för den här modellen.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Maximal bildsidlängd för modellen`},help:{"v1-1gbci08-1y":`Maximal bildbredd eller bildhöjd som leverantören accepterar för den här modellen.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Önskad bildsidlängd för modellen`},help:{"v1-1u1mpcg-2x":`Önskad sidlängd vid storleksändring av bilder för balanserad komprimering. Lämna värdet oangivet för att använda OpenClaws försiktiga standardvärde.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Läge för bildtokenberäkning för modellen`},help:{"v1-1oy6z7v-1z":`Leverantörens metod för beräkning av bildtoken: "tile", "detail" eller "provider".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EresponseModelEquivalent":{help:{"v1-1hociw2-d7":`Ange true på en användarskapad rad för en anpassad leverantör när en router eller förmedlare själv hanterar detta modell-id. Alla svars-id:n som rapporteras av slutpunkten betraktas då som likvärdiga, även vid interna ersättningar i slutpunkten. Det id som används och användningen registreras fortfarande; OpenClaws meddelanden om reservlösningar och åsidosättningar finns kvar. Medföljande/officiell policy kan inte åsidosättas. Plugin-/katalograder, rader i agentens models.json och models-add-rader kan inte medge likvärdighet. Om värdet utelämnas eller är false behålls normal ruttidentifiering.`}},"models%2Eproviders%2E*%2Ename":{label:{"v1-ioaceo-r":`Visningsnamn för modellleverantör`},help:{"v1-jio82-3z":`Valfritt visningsnamn som visas i leverantörsinställningar och modellväljare. Ändrar inte leverantörens ID, modellreferenser, autentiseringsuppgifter eller routning.`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Körningsparametrar för modelleverantör`},help:{"v1-464sgu-4t":`Leverantörsspecifika körningsparametrar som tolkas av leverantörsplugin. Behåll nycklar som dokumenteras av leverantören och prioritera uttrycklig leverantörsdokumentation framför gemensamma antaganden gjorda ad hoc.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Region för modelleverantör`},help:{"v1-yq7rxk-5h":`Valfri driftsättnings-/API-region för leverantören som tolkas av leverantörer med regionala slutpunkter. Se leverantörens dokumentation för värden som stöds; åsidosättningar via baseUrl har vanligtvis företräde när båda anges.`}},"models%2Eproviders%2E*%2Eremote":{label:{"v1-ih3vfx-11":`Tidsgränser för modellleverantörens övervakning av värdbaserade API:er`},help:{"v1-bsr5s-9g":`Åsidosätter endast övervakningens tidsgränser för lokala reläer framför värdbaserade API:er. När värdet är true använder LLM-övervakningen för inaktivitet och första händelsen tidsgränser för värdbaserade API:er även med en lokal baseUrl, ett lokalt leverantörs-ID, localService eller en lokal autentiseringsmarkör. Om värdet saknas eller är false behålls detekteringen av lokal drift. Explicita timeoutSeconds och tidsbudgetar för körningar eller agenter har fortsatt företräde.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Åsidosättningar av förfrågningar till modelleverantör`},help:{"v1-1lkxryk-87":`Valfria åsidosättningar för förfrågningar till modelleverantörer, inklusive extra huvuden, åsidosättningar av autentisering, proxyroutning, TLS-klientinställningar och valfri allowPrivateNetwork för betrodda slutpunkter med egen drift. Använd dessa endast när den överordnade tjänsten eller företagets nätverksväg kräver anpassning av transporten.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Tillåt privat nätverk för förfrågningar till modelleverantör`},help:{"v1-1nbtcjk-fo":`När värdet är true tillåts HTTP-anrop till modellleverantörer i privata adressområden, CGNAT eller liknande områden genom leverantörens skydd för HTTP-hämtningar (fetchWithSsrFGuard). Anpassade eller lokala bas-URL:er för leverantörer litar redan på det exakt konfigurerade ursprunget, med undantag för ursprung för metadata, länklokala adresser och NAT64 för lokalt bruk (64:ff9b:1::/48). Ange false för att inaktivera denna tillit. OpenAI Responses WebSocket återanvänder request för HTTP-huvuden/TLS men använder inte denna SSRF-skyddade hämtningsväg. Använd true endast för operatörskontrollerade, självhostade slutpunkter som måste nå privata ursprung utanför det konfigurerade baseUrl-ursprunget.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Åsidosättning av autentisering för anrop till modellleverantör`},help:{"v1-ucdgnf-1w":`Åsidosätt autentiseringsbeteendet för anrop till denna leverantör.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Namn på autentiseringshuvud för anrop till modellleverantör`},help:{"v1-1881nqr-1i":`Anpassat namn på autentiseringshuvudet som används när autentiseringsläget är header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Autentiseringsläge för anrop till modellleverantör`},help:{"v1-1lhv8hs-24":`Läge för åsidosättning av autentisering: "provider-default", "authorization-bearer" eller "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Prefix för autentiseringshuvud för anrop till modellleverantör`},help:{"v1-1rbm9lz-21":`Valfritt prefix som läggs före request.auth.value när autentiseringsläget är header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Bearer-token för anrop till modellleverantör`},help:{"v1-6rcasw-1l":`Bearer-token som används när autentiseringsläget är authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Värde för autentiseringsheader i modellleverantörens anrop`},help:{"v1-1v69ej-1j":`Anpassat värde för autentiseringsheader som används när autentiseringsläget är header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Headers för anrop till modellleverantören`},help:{"v1-zj3orj-2i":`Extra headers som slås samman med leverantörsanrop efter att standardattribuering och autentisering har fastställts.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy för anrop till modellleverantören`},help:{"v1-md5uj8-4j":`Valfri åsidosättning av proxy för anrop till modellleverantören. Använd "env-proxy" för att följa miljöns proxyinställningar eller "explicit-proxy" för att dirigera via en specifik proxy-URL.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Proxyläge för anrop till modellleverantören`},help:{"v1-1dx0ozg-29":`Läge för åsidosättning av proxy för anrop till modellleverantören: "env-proxy" eller "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS för proxy vid anrop till modellleverantören`},help:{"v1-rdx62w-1v":`Valfria TLS-inställningar som används vid anslutning till den konfigurerade proxyn.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`TLS-CA för proxy vid anrop till modellleverantören`},help:{"v1-11pg2fd-1s":`Anpassat CA-paket som används för att verifiera proxyns TLS-certifikatkedja.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`TLS-certifikat för proxy vid anrop till modellleverantören`},help:{"v1-x8nk2q-22":`TLS-klientcertifikat som visas för proxyn när ömsesidig TLS krävs.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Hoppa över TLS-verifiering för modellleverantörens förfrågningsproxy`},help:{"v1-12vjdm9-2j":`Hoppar över verifiering av proxyns TLS-certifikat. Använd endast i kontrollerade utvecklingsmiljöer.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`TLS-nyckel för modellleverantörens förfrågningsproxy`},help:{"v1-1skyr56-1w":`Privat nyckel som hör ihop med request.proxy.tls.cert för ömsesidig TLS med proxyn.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`TLS-lösenfras för modellleverantörens förfrågningsproxy`},help:{"v1-wjvoxd-1m":`Valfri lösenfras som används för att dekryptera request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`TLS-servernamn för modellleverantörens förfrågningsproxy`},help:{"v1-b4oabu-22":`Valfri åsidosättning av SNI/servernamn som används när en TLS-anslutning till proxyn upprättas.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`Proxy-URL för modellleverantörens förfrågningar`},help:{"v1-kvbgou-48":`Explicit proxy-URL som används när request.proxy.mode är explicit-proxy. Inloggningsuppgifter inbäddade i URL:en behandlas som känsliga och maskeras i ögonblicksbilder.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS för modellleverantörens förfrågningar`},help:{"v1-16u7v7h-2b":`Valfria TLS-inställningar som används vid direktanslutning till den uppströms modelländpunkten.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`TLS-CA för förfrågningar till modellleverantören`},help:{"v1-ny8y3e-1v":`Anpassad CA-samling som används för att verifiera den uppströms TLS-certifikatkedjan.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`TLS-certifikat för förfrågningar till modellleverantören`},help:{"v1-1lltmhw-2e":`TLS-klientcertifikat som presenteras för den uppströms ändpunkten när ömsesidig TLS krävs.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Hoppa över TLS-verifiering för förfrågningar till modellleverantören`},help:{"v1-1006cuy-2m":`Hoppar över verifiering av uppströms TLS-certifikat. Använd endast i kontrollerade utvecklingsmiljöer.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`TLS-nyckel för förfrågningar till modellleverantören`},help:{"v1-w2agir-1t":`Privat nyckel som hör ihop med request.tls.cert för ömsesidig TLS uppströms.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`TLS-lösenfras för förfrågningar till modellleverantören`},help:{"v1-10ds42f-1g":`Valfri lösenfras som används för att dekryptera request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`TLS-servernamn för förfrågningar till modellleverantören`},help:{"v1-18yt7x9-1y":`Valfri åsidosättning av SNI/servernamn som används när en TLS-anslutning upprättas uppströms.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Tidsgräns för förfrågningar till modellleverantören`},help:{"v1-t3yn8l-ih":`Valfri tidsgräns i sekunder för modellförfrågningar per leverantör. Inställningar för förfrågningar på leverantörsnivå påverkar uttryckligen definierade modellposter som tillhör leverantören; de skapar inga implicita modeller. För anpassade leverantörer anger du detta tillsammans med leverantörens baseUrl och models. Gäller leverantörens HTTP-hämtningar, inklusive anslutning, huvuden, innehåll och hantering av avbrott för hela förfrågan. Höjer även den övre tidsgränsen för övervakning av LLM-inaktivitet och strömning för denna leverantör över det implicita standardvärdet på cirka 120 sekunder. Använd detta för långsamma lokala eller egenhostade modellservrar, eller för molnleverantörer som buffrar resonemangstoken utan att skicka data över anslutningen (Gemini preview, Claude/Opus med stora verktygsdatamängder), i stället för att ändra globala tidsgränser för agenter.`}},"models%2Eusage":{label:{"v1-1frhz6j-e":`Användning hos leverantören`},help:{"v1-hn2n9r-18":`Cacheinställningar för leverantörens rapporterade abonnemangsanvändning.`}},"models%2Eusage%2EcacheTtlMs":{label:{"v1-1g6hvog-t":`TTL för cache med användning hos leverantören (ms)`},help:{"v1-jltn3b-4j":`Återanvänd ögonblicksbilder av användning hos leverantören under så här många millisekunder (standard: 60000). Gäller både vanliga läsningar och läsningar efter körning; 0 inaktiverar återanvändning. Aktiverar inte regelbunden avfrågning i viloläge.`}},nodeHost:{label:{"v1-nb8lk1-9":`Nodvärd`},help:{"v1-8recuz-4z":`Nodvärdsinställningar för funktioner som görs tillgängliga från denna gatewaynod för andra noder eller klienter. Behåll standardinställningarna om du inte avsiktligt vill förmedla lokala funktioner via proxy i ditt nodnätverk.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Agentkörningar på noden`},help:{"v1-4uz5ur-2k":`Aktivera inbyggda agentturer som kräver godkännande på denna nodvärd utan grafiskt gränssnitt. Inaktiverat som standard.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Claude-agentkörningar på noden`},help:{"v1-g8az5y-2l":`Styr om denna nodvärd utan grafiskt gränssnitt får meddela gatewayen att den erbjuder agentturer via Claude CLI.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Claude-agentkörningar på noden aktiverade`},help:{"v1-1ke804l-44":`Meddela att Claude-sessioner kan fortsättas på den parkopplade noden när den lokala binärfilen claude är tillgänglig (standard: false). Körningar kräver fortfarande godkännande för kommandoexekvering på noden.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Automatiska noduppdateringar`},help:{"v1-16xjk4e-5n":`Styr automatiska uppdateringar av den separata körmiljön för paketerade nodvärdar utan grafiskt gränssnitt. Söker efter uppdateringar varje timme och väntar tills allt nodarbete är klart innan omstart. Automatiska omstarter sker med minst 12 timmars mellanrum.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Automatiska noduppdateringar aktiverade`},help:{"v1-1sa0yeg-7w":`Aktivera automatiska stabila uppdateringar eller betauppdateringar för långvarigt körande, paketerade noder utan grafiskt gränssnitt (standard: true). Ange false för att avstå. Inaktiveras även av update.checkOnStart=false eller OPENCLAW_NO_AUTO_UPDATE=1. Uppdateringar tillämpas inte automatiskt för utcheckad källkod, inbyggda appar, privata arbetare, dev eller extended-stable.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Nodens webbläsarproxy`},help:{"v1-2xrew7-4f":`Samlar inställningar för webbläsarproxyn som gör lokal webbläsarstyrning tillgänglig via nodroutning. Aktivera endast när arbetsflöden på fjärrnoder behöver dina lokala webbläsarprofiler.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Tillåtna profiler för nodens webbläsarproxy`},help:{"v1-1ew5dkm-8b":`Valfri tillåtelselista med namn på webbläsarprofiler som görs tillgängliga via nodens proxyroutning. Lämna tomt för att behålla standardåtkomsten till alla profilfunktioner, inklusive rutter för att skapa och ta bort profiler. När listan anges begränsar OpenClaw profilåtkomsten enligt principen om minsta behörighet och blockerar skapande och borttagning av beständiga profiler via proxyn.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Nodens webbläsarproxy aktiverad`},help:{"v1-pa04pd-5b":`Gör den lokala servern för webbläsarstyrning tillgänglig via nodens proxyroutning så att fjärrklienter kan använda den här värdens webbläsarfunktioner. Låt vara inaktiverat om inte fjärrautomatisering uttryckligen kräver det.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`Nodvärdens MCP`},help:{"v1-1mdhrwl-48":`Använd MCP-servrar som startas av nodvärden utan grafiskt gränssnitt och publiceras till dess parkopplade Gateway som agentverktyg. Starta om nodvärden efter att du har ändrat det här avsnittet.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Nodvärdens MCP-servrar`},help:{"v1-19m002f-3x":`Namngivna MCP-serverdefinitioner som är lokala för den här noden. Använder samma serverstruktur som mcp.servers; OAuth-servrar stöds inte av nodvärden.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Nodvärdens Skills`},help:{"v1-v8txza-41":`Använd det här avsnittet för att publicera färdigheter installerade i ~/.openclaw/skills från nodvärden utan grafiskt gränssnitt. Starta om nodvärden efter att du har ändrat färdighetsfiler.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Nodvärdens Skills aktiverade`},help:{"v1-1ggpkqb-36":`Sök efter och publicera färdigheter som finns på noden efter anslutning (standard: true). Ange false för att inaktivera publicering av nodens färdigheter.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Arbetarkörningar på noden`},help:{"v1-1w83rox-2p":`Aktivera värdskap för fullständiga OpenClaw-arbetarsessioner från paket som hanteras av Gateway. Inaktiverat som standard.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Kapacitet för arbetarkörningar på noden`},help:{"v1-10nvk8f-3w":`Maximalt antal samtidiga arbetarsessioner på den här noden (standard: antalet tillgängliga CPU-kärnor). Måste vara ett heltal från 1 till 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Containeravbildning för arbetarkörningar på noden`},help:{"v1-1tmr1le-5y":`Valfri Node 24.22.1+- eller 26.12.1+-avbildning för containerisolerade arbetare (standard: "node:24.22.1-slim"). Använd vid behov en avbildning som är låst till en digest, finns i ett privat register eller är förinläst; saknade avbildningar hämtas vid första användningen.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Worker-körningar på noden aktiverade`},help:{"v1-b3t0xp-2t":`Tillåt att denna parkopplade nod är värd för sessioner från exakt de paket som installerats av dess Gateway (standard: false).`}},"nodeHost%2EworkerRuns%2Efolders":{label:{"v1-1waimc-r":`Mappar för worker-sessioner på noden`},help:{"v1-ald547-9v":`Valfria rotkataloger som begränsar sessioner på plats till dessa kataloger och deras underkataloger. Om inget anges tillåts alla befintliga kataloger utom filsystemsrötter och privat worker-lagring; [] inaktiverar sessioner i enhetsmappar. Använd absoluta sökvägar eller sökvägar med ~/. Befintliga filer stannar på enheten; dessa mappar tas aldrig bort när en session raderas. Kräver workerRuns.enabled.`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Isolering av worker-körningar på noden`},help:{"v1-19i6swo-58":`Välj processgräns för worker-sessioner: "none" kör direkt på nodvärden (standard); "container" kräver en fungerande Docker-kompatibel motor och faller aldrig tillbaka på körning på värden.`}},plugins:{label:{"v1-10renyj-7":`Insticksprogram`},help:{"v1-1qbev2k-5c":`Inställningar för insticksprogramsystemet för att aktivera tillägg, begränsa vad som läses in, konfigurera poster och spåra installationer. Håll policyn för insticksprogram uttrycklig och tillämpa principen om minsta behörighet i produktionsmiljöer.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Tillåtelselista för insticksprogram`},help:{"v1-1w1dsc3-ek":`Valfri tillåtelselista med plugin-ID:n. En lista som inte är tom begränsar inläsningen, med undantag för valt minnesplugin (inklusive standardvalet memory-core), context-engine-pluginer med samma ID och medföljande chattkanaler som uttryckligen aktiverats. Ägare till context-engine med andra namn måste aktiveras eller tillåtas separat och finnas med i tillåtelselistan om den inte är tom. Verktyg som tillhör pluginer utanför tillåtelselistan förblir otillgängliga. Använd plugins.deny eller plugins.entries.<id>.enabled: false för att blockera ett plugin oavsett slot-val.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Spärrlista för insticksprogram`},help:{"v1-4gyt4z-4i":`Valfri spärrlista med plugin-ID:n som blockeras även om de ingår i tillåtelselistor eller sökvägar. Använd spärrregler för akut återställning och ovillkorlig blockering av riskabla pluginer.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Aktivera pluginer`},help:{"v1-pnygd7-50":`Aktivera eller inaktivera inläsning av pluginer/tillägg globalt vid start och omladdning av konfigurationen (standard: true). Låt detta vara aktiverat endast när din driftsättning kräver tilläggsfunktioner.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Pluginposter`},help:{"v1-cn74rf-54":`Inställningar per plugin med plugin-ID som nyckel, inklusive aktivering och pluginspecifik körningskonfiguration. Använd detta för att finjustera enskilda pluginer utan att ändra den globala inläsningspolicyn.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`API-nyckel för plugin`},help:{"v1-ctytg2-53":`Valfritt API-nyckelfält som används av pluginer som stöder direkt konfiguration av nycklar i postens inställningar. Använd substitution via hemligheter eller miljövariabler och undvik att checka in verkliga autentiseringsuppgifter i konfigurationsfiler.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Pluginkonfiguration`},help:{"v1-1he672p-51":`Konfigurationsdata definierade av pluginen som tolkas enligt pluginens eget schema och egna valideringsregler. Använd endast pluginens dokumenterade fält för att undvika att inställningar ignoreras eller är ogiltiga.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin aktiverad`},help:{"v1-12soc0h-9a":`Åsidosättning av aktivering för en specifik pluginpost, som tillämpas utöver den globala pluginpolicyn. Med hybridläget för omladdning, som är standard, laddas pluginens körmiljö om direkt för nya agentturer utan att Gateway startas om, såvida inte pluginen kräver omstart för den här ändringen. Använd detta för att gradvis införa pluginer i olika miljöer.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Miljövariabler för insticksprogram`},help:{"v1-p39pu4-52":`Mappning av miljövariabler per insticksprogram som endast injiceras i det insticksprogrammets körningskontext. Använd detta för att begränsa leverantörens autentiseringsuppgifter till ett insticksprogram i stället för att dela den globala processmiljön.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Hookpolicy för insticksprogram`},help:{"v1-1oslnrf-4c":`Policyinställningar per insticksprogram för typade hookar och säkerhetskontroller som upprätthålls av kärnan. Använd detta för att begränsa hookkategorier med stor påverkan utan att inaktivera hela insticksprogrammet.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Tillåt hookar med konversationsåtkomst`},help:{"v1-xqz31z-7e":"Styr om detta insticksprogram får läsa obearbetat konversationsinnehåll från typade hookar som `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` och `agent_end`. För insticksprogram som inte ingår måste detta aktiveras uttryckligen."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptModification":{label:{"v1-1ufndoc-e":`Ändra promptar`},help:{"v1-10llywv-8b":`Tillåter att detta insticksprogram lägger till eller ändrar kontexten och instruktionerna som skickas till modellen, vilket kan påverka dess svar. Tillåt endast detta för insticksprogram som du litar på. Tillåtet som standard. Ange false för att blockera hookar som ändrar promptar, promptvägledning för verktyg, promptbidrag till nästa tur och styrning av pågående körningar.`}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Tidsgräns för insticksprogrammets hookar (ms)`},help:{"v1-4ra6b7-74":`Standardtidsgräns i millisekunder för detta insticksprograms typade hookar, med ett maxvärde på 600000. Om inget värde anges använder varje hook insticksprogrammets deklarerade tidsgräns eller den hookspecifika policyn i Gateway; det finns inget enhetligt fast standardvärde. Hookspecifika värden i hooks.timeouts har företräde.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Åsidosättningar av tidsgränser för insticksprogrammets hookar`},help:{"v1-yphl9b-5s":`Åsidosättningar av tidsgränser per hook i millisekunder, med typade hook-namn som nycklar och ett maxvärde på 600000. Använd riktade åsidosättningar för kända långsamma hooks som before_prompt_build eller agent_end i stället för att höja tidsgränsen för alla hooks.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`LLM-policy för insticksprogram`},help:{"v1-dlca6c-4j":`Inställningar per insticksprogram för api.runtime.llm.complete som styr behörigheten att åsidosätta modell och agent. Lämna detta oangivet om inte ett insticksprogram uttryckligen måste styra värdens kompletteringsanrop.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Tillåt insticksprogram att åsidosätta LLM-agent`},help:{"v1-k8c08b-4n":`Tillåter uttryckligen att detta insticksprogram begär api.runtime.llm.complete med ett annat agent-id än standardvärdet. Behåll false om inte insticksprogrammet är betrott för modellåtkomst över agentgränser.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Tillåt insticksprogram att åsidosätta LLM-autentiseringsprofil`},help:{"v1-9ityw9-4x":`Tillåter att detta insticksprogram väljer en annan autentiseringsprofil än standardprofilen för kompletteringar i en isolerad agentkörningsmiljö. Behåll false om inte insticksprogrammet är betrott för uttrycklig, isolerad routning av autentiseringsuppgifter.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Tillåtna LLM-kompletteringsmodeller för insticksprogram`},help:{"v1-1kgxs8j-55":`Tillåtna mål för varje LLM-komplettering från insticksprogram, angivna som fullständiga "provider/model"-referenser, inklusive standardvärden och åsidosättningar som värden fastställer. Använd "*" endast när du avsiktligt tillåter alla modeller.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Tillåtna LLM-modeller för insticksprogram`},help:{"v1-h9m5ew-48":`Tillåtna modellåsidosättningar för betrodda tilläggs LLM-anrop, som fullständiga "provider/model"-referenser. Använd "*" endast när du avsiktligt tillåter åsidosättning med valfri modell.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Tillåt tillägg att åsidosätta LLM-modell`},help:{"v1-uw4jmc-47":`Tillåter uttryckligen detta tillägg att begära modellåsidosättningar i api.runtime.llm.complete. Behåll false om inte tillägget är betrott att styra modellvalet.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Policy för tilläggets underagenter`},help:{"v1-wbf4m1-4d":`Körningsinställningar för underagenter per tillägg som styr behörighet att åsidosätta modeller och listor över tillåtna modeller. Lämna detta oangivet om inte ett tillägg uttryckligen måste styra underagenternas modellval.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Tillåtna modeller för tilläggets underagenter`},help:{"v1-hdzz51-43":`Tillåtna modellåsidosättningar för betrodda tilläggs underagentkörningar, som fullständiga "provider/model"-referenser. Använd "*" endast när du avsiktligt tillåter valfri modell.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Tillåt tillägg att åsidosätta underagentmodell`},help:{"v1-1r5tzm1-4g":`Tillåter uttryckligen detta tillägg att begära åsidosättningar av provider/model vid underagentkörningar i bakgrunden. Behåll false om inte tillägget är betrott att styra modellvalet.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Tilläggsladdare`},help:{"v1-1myjwbi-52":`Konfigurationsgrupp för tilläggsladdaren där sökvägar i filsystemet anges för sökning efter tillägg. Använd uttryckligen angivna och granskade sökvägar för att undvika oavsiktlig inläsning av obetrodda tillägg.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Sökvägar för inläsning av insticksprogram`},help:{"v1-o689p1-4z":`Ytterligare filer eller kataloger med insticksprogram som inläsaren söker igenom utöver de inbyggda standardplatserna. Använd särskilda tilläggskataloger och undvik breda sökvägar med orelaterat körbart innehåll.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Platser för insticksprogram`},help:{"v1-zx6crl-5f":`Väljer vilka insticksprogram som har exklusiva platser under körning, till exempel för minne, så att endast ett insticksprogram tillhandahåller funktionen. Tilldela platser uttryckligen för att undvika överlappande leverantörer med motstridiga beteenden.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-tp8do7-h":`Kontextmotorns ID`},help:{"v1-1ww2hr0-4h":`Väljer den registrerade kontextmotorns ID. Insticksprogram med olika ID:n för insticksprogram och motor anger contextEngineIds i sitt manifest så att OpenClaw kan läsa in det insticksprogram som äger motorn.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Minnesinsticksprogram`},help:{"v1-6kb575-6d":`Välj aktivt minnesplugin via ID (standard: memory-core), eller "none" för att inaktivera minnespluginer. Det valda pluginet kan läsas in även om det inte finns med i plugins.allow. plugins.deny och uttrycklig inaktivering av enskilda pluginer har fortfarande företräde.`}},presence:{label:{"v1-10fdwo4-8":`Närvaro`}},proxy:{label:{"v1-ji57pa-d":`Hanterad proxy`},help:{"v1-vui6bx-58":`Operatörshanterad routning via utgående proxy för HTTP, HTTPS, WebSocket och stödda vägar för rå utgående trafik i OpenClaw under körning. Använd detta när central kontroll av utgående trafik ingår i driftsmiljöns avgränsning.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Hanterad proxy aktiverad`},help:{"v1-1456xdw-49":`Uttrycklig åsidosättning för hanterad proxy. Om en URL finns aktiveras routning som standard. Ange false för att ignorera proxy-URL:er från konfigurationen eller miljön utan att ta bort dem.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Loopback-läge för hanterad proxy`},help:{"v1-1kaiuh0-3c":`Styr routningen av Gateways kontrollplan via loopback när läget för hanterad proxy är aktivt: "gateway-only", "proxy" eller "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL för hanterad proxy`},help:{"v1-p36b5l-3v":`URL för hanterad framåtproxy. Använd http:// för en vanlig CONNECT-proxy eller https:// när anslutningen till själva proxyändpunkten måste använda TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS för hanterad proxy`},help:{"v1-6i0vu-3q":`TLS-inställningar som används vid anslutning till den hanterade proxyändpunkten. Dessa inställningar gäller TLS för proxyn, inte TLS för destinationen efter CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`CA-fil för hanterad proxys TLS`},help:{"v1-1ntzjia-2p":`Sökväg i filsystemet till en anpassad CA-samling som används för att verifiera certifikatet för en hanterad HTTPS-proxyändpunkt.`}},repositoryBranchPrefix:{label:{"v1-1sxh9u9-o":`Grenprefix för kodarkiv`},help:{"v1-10w2bot-41":`Prefix för nya sessionsgrenar i fjärrkodarkivet. Standardvärdet är openclaw; grenar använder <prefix>/<workspace GUID>. Befintliga grenar ändras inte.`}},secrets:{label:{"v1-1sihgpy-7":`Hemligheter`},help:{"v1-jgn0o9-2l":`Leverantörer av hemlighetsreferenser, beteende för delad lagring och valfritt skydd för underprocessers utgående trafik.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Utgående proxy för hemligheter`},help:{"v1-1qfgid-4n":`Loopback-proxy som ägs av Gateway och ersätter markörer för hemligheter i delad lagring först när utgående förfrågningar skickas. Starta om Gateway efter ändringar i detta avsnitt, som läses in vid start.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Tillåtna värdar för utgående proxy för hemligheter`},help:{"v1-9ypodl-6t":`Valfri tillåtelselista för trafik via förfrågningar och CONNECT-tunnlar. När listan finns måste destinationer finnas i den, i en värdbindning för en enskild hemlighet eller i bypassHosts. En tom lista tillåter endast bundna eller undantagna värdar. Starta om Gateway efter ändringar.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Undantagna värdar för utgående proxy för hemligheter`},help:{"v1-1oiiomv-57":`Exakta värdnamn som använder autentiserade blinda CONNECT-tunnlar för klienter med certifikatlåsning. Markörerna förblir krypterade och kommer att underkännas vid leverantörens autentisering i stället för att exponera klartext.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Utgående proxy för hemligheter aktiverad`},help:{"v1-u99b1i-2h":`Aktiverar ersättning av hemligheter i utgående trafik för agentunderprocesser som körs på Gateway. Standard: false.`}},"security%2Eaudit":{label:{"v1-16w033o-e":`Säkerhetsgranskning`}},"security%2Eaudit%2Esuppressions":{label:{"v1-1l4qjwk-i":`Granskningsundantag`},help:{"v1-1deyl5p-4f":`Accepterade säkerhetsanmärkningar som ska utelämnas från den aktiva sammanfattningen och listan över anmärkningar. Matchande anmärkningar finns fortfarande tillgängliga under suppressedFindings i JSON-utdata.`}},"security%2Eaudit%2Esuppressions%2E*%2EcheckId":{label:{"v1-pfzkxp-e":`ID för granskningskontroll`}},"security%2Eaudit%2Esuppressions%2E*%2EdetailIncludes":{label:{"v1-ykrpzg-n":`Anmärkningens detaljer innehåller`}},"security%2Eaudit%2Esuppressions%2E*%2Ereason":{label:{"v1-1581z0k-i":`Orsak till undantag`}},"security%2Eaudit%2Esuppressions%2E*%2EtitleIncludes":{label:{"v1-18y11at-m":`Anmärkningens titel innehåller`}},"security%2EinstallPolicy":{label:{"v1-1dbuvhm-e":`Installationspolicy`}},"security%2EinstallPolicy%2Eenabled":{label:{"v1-bfdyp9-l":`Aktivera installationspolicy`},help:{"v1-67yonn-4i":`Aktivera ett betrott lokalt policykommando för installation och uppdatering av färdigheter och insticksprogram. Om detta aktiveras utan ett konfigurerat kommando blockeras installationsmål som stöds.`}},"security%2EinstallPolicy%2Eexec":{label:{"v1-433033-m":`Kommando för installationspolicy`},help:{"v1-1hyg77m-46":`Betrott lokalt kommando som returnerar installationsbeslutet "allow", "warn" eller "block". Ange en absolut sökväg till en körbar fil; OpenClaw kör den utan ett skal.`}},"security%2EinstallPolicy%2Eexec%2Eargs":{label:{"v1-17c9br2-o":`Argument för policykommando`}},"security%2EinstallPolicy%2Eexec%2Ecommand":{label:{"v1-l86c0l-h":`Körbar fil för policy`}},"security%2EinstallPolicy%2Eexec%2Eenv":{label:{"v1-f7gtc3-s":`Miljövariabler för policy`}},"security%2EinstallPolicy%2Eexec%2EmaxOutputBytes":{label:{"v1-1jz3qk1-r":`Gräns för policyutdata (byte)`}},"security%2EinstallPolicy%2Eexec%2EnoOutputTimeoutMs":{label:{"v1-bu8clf-o":`Tidsgräns för inaktivitet i policyn (ms)`}},"security%2EinstallPolicy%2Eexec%2EpassEnv":{label:{"v1-uzu2wx-12":`Ärvda miljövariabler för policyn`}},"security%2EinstallPolicy%2Eexec%2Esource":{label:{"v1-wv29f-l":`Källa för policykommandot`}},"security%2EinstallPolicy%2Eexec%2EtimeoutMs":{label:{"v1-i9ag7r-j":`Tidsgräns för policyn (ms)`}},"security%2EinstallPolicy%2Eexec%2EtrustedDirs":{label:{"v1-1kkqbtr-q":`Betrodda kataloger för policyn`}},"security%2EinstallPolicy%2Etargets":{label:{"v1-ss3w1g-m":`Mål för installationspolicyn`},help:{"v1-1ar6u6h-2v":`Tillämpa installationspolicyn på "skill", "plugin" eller båda. Utelämna listan för att omfatta alla mål som stöds.`}},session:{label:{"v1-8yh9jr-7":`Session`},help:{"v1-j86s32-5d":`Globala inställningar för sessionsroutning, återställning, leveranspolicy och underhåll som styr konversationshistorikens beteende. Behåll standardinställningarna om du inte behöver striktare krav på isolering, lagringstid eller leverans.`}},"session%2Ecommunication":{label:{"v1-133tjjf-u":`Standardinställningar för sessionskommunikation`},help:{"v1-1y4eege-63":`Standardinställningar för nya meddelanden mellan sessioner. Varje riktning accepterar always, ask eller never och har always som standard. Sessioner ärver dessa värden tills en människa väljer att åsidosätta dem. Befintliga åtkomstbegränsningar gäller fortfarande.`}},"session%2Ecommunication%2Ereceive":{label:{"v1-efg2gh-10":`Ta emot meddelanden från andra sessioner`},help:{"v1-t6w901-5q":`Standardinställning för att ta emot nya meddelanden från andra sessioner: always tillåter, ask kräver godkännande av en människa innan indata skickas till modellen eller nytt arbete påbörjas, och never blockerar. Detta ändrar inte historikens synlighet eller människors åtkomst.`}},"session%2Ecommunication%2Esend":{label:{"v1-1chq2bl-v":`Skicka meddelanden till andra sessioner`},help:{"v1-92cfz7-65":`Standardinställning för att initiera meddelanden till andra sessioner: always tillåter, ask kräver godkännande av en människa före sändning, och never blockerar. Begärda svar och godkänd kommunikation för delegerade uppgifter behåller sina befintliga behörigheter.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Omfattning för DM-sessioner`},help:{"v1-ql362c-5l":`Omfattning för DM-sessioner: "main" bevarar kontinuiteten, medan "per-peer", "per-channel-peer" och "per-account-channel-peer" ökar isoleringen. Använd isolerade lägen för delade inkorgar eller driftsättningar med flera konton.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Omfattning för gruppsessioner`},help:{"v1-1fdezx2-6i":`Omfattning för grupp-/kanalsessioner: "per-group" håller rum åtskilda medan agentens huvudsession bevakar dem i bakgrunden, oberoende av dmScope; "main" sammanför rummens kontext med huvudsessionen och kräver ingen bevakning. Använd "main" endast för betrodda rum.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Identitetskopplingar för sessioner`},help:{"v1-4mwmyr-5k":`Kopplar gemensamma identiteter till motparts-ID:n med leverantörsprefix så att samma användare samlas i en enda DM-tråd (exempel: telegram:123456). Använd detta när samma person förekommer i flera kanaler eller konton.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Huvudnyckel för sessioner`},help:{"v1-18p638h-3q":`Accepteras men ignoreras: suffixet för varje agents huvudsession är alltid "main". Utelämna detta fält; global sessionsomfattning använder "global" i stället.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Sessionsunderhåll`},help:{"v1-hdyrb-68":`Inställningar för automatiskt underhåll av sessionslagret: arkivering av appsessioner, åldersgräns för rensning, maximalt antal poster, lagringstid för återställningsarkiv och rensning utifrån diskutrymmesbudget. Börja i läget warn för att se effekten och byt sedan till enforce när tröskelvärdena har justerats.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Arkivera inaktiva sessioner på instrumentpanelen efter`},help:{"v1-1krn130-60":"Arkiverar inaktiva sessioner som startats i OpenClaw-appen efter denna tidsperiod (till exempel `7d`), så att de förblir tillgängliga utan att fylla listan över aktiva sessioner. Ange `false` eller `0` för att inaktivera denna automatiska arkivering."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-ogfwwy-h":`Kallagring av chattar`},help:{"v1-kqjx1d-5m":`Flyttar inaktiva chattar till komprimerade JSONL-arkiv och behåller sessionernas metadata. Arkivfilerna blir en nödvändig del av historiken och måste ingå i säkerhetskopior. Ändringar tillämpas utan att Gateway startas om.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Arkivera efter antal inaktiva dagar`},help:{"v1-1f9pk9f-55":`Arkivera chattar efter så här många dagars inaktivitet (positivt heltal, standardvärde 30). Pågående arbete skyddas. Ändringar av gränsen börjar gälla vid bakgrundsprocessens nästa körning utan att Gateway behöver startas om.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-17fys4q-v":`Arkivera gamla chattar automatiskt`},help:{"v1-1sdhnti-5s":`Aktiverar arkivering av chattar i bakgrunden (standardvärde true). Ange false för att inaktivera framtida extrahering. En bakgrundsprocess söker varje minut efter chattar som uppfyller villkoren. Denna arkiveringspolicy är separat från radering och rensning utifrån diskutrymmesbudgeten.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Övre målnivå för sessioners diskutrymme`},help:{"v1-143vh09-7z":`Målstorlek efter rensning för att hålla diskbudgeten (övre gränsvärde). Standardvärdet är 80 % av maxDiskBytes. Ange ett uttryckligt värde för att frigöra mer utrymme på diskar med begränsad kapacitet. Ett värde som beräknas till noll ersätts med standardvärdet. Negativa värden är ogiltiga. Inaktivera budgeten med maxDiskBytes i stället.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Maximal diskbudget för sessioner`},help:{"v1-ocx4rx-cl":'Budget för fysiskt diskutrymme per agent som omfattar SQLite-huvuddatabasen/WAL och de artefakter i sessionskatalogen som räknas med (till exempel `500mb`). Standardvärdet är `10gb`; skyddade data kan göra att användningen ligger över målet. När budgeten överskrids rapporterar läget warn utrymmesbrist, medan läget enforce tar bort gamla artefakter från återställning/radering, historik utan referenser och därefter arkiv som skapats på grund av postgränsen. Manuella arkiv, arkiv från åldersbaserad lagring och appsessioner samt återställningsarkiv och äldre arkiv förblir skyddade. Ange `false`, `0` eller `"0"` för att inaktivera.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Maximalt antal sessionsposter`},help:{"v1-1w2egrh-7u":`Begränsar antalet oarkiverade sessionsposter (standardvärde 5000). Beständiga konversationer som överskrider gränsen och uppfyller villkoren arkiveras med sin historik; tillfälliga automatiseringsposter tas bort. Befintliga arkiv räknas inte mot gränsen. Skyddade aktiva poster räknas fortfarande och kan hålla lagringen över gränsen.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Underhållsläge för sessioner`},help:{"v1-qhc707-7c":`Avgör om åtgärder enligt policyerna för gallring och diskutrymmesbudget endast rapporteras ("warn") eller faktiskt genomförs ("enforce"). Behåll "warn" under utrullningen och byt till "enforce" efter att ha kontrollerat att tröskelvärdena är säkra. Kallagring är aktiverad som standard och har en egen inställning för att inaktiveras.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Bevara senaste sessioner`},help:{"v1-138q5wx-89":"Skyddar interaktiva sessioner som varit aktiva inom denna tidsperiod (till exempel `7d`) från automatisk borttagning av historik baserat på ålder, antal och diskbudget. Om värdet inte anges eller är `false` behålls den vanliga principen att ta bort äldst först. Syntetiska rader för modellkörningar, cron, hook, heartbeat, ACP och underagenter kan fortfarande omfattas av begränsad rensning."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Rensa sessioner efter`},help:{"v1-1xn50w7-76":"Arkiverar beständiga konversationer som uppfyller villkoren och tar bort tillfälliga automatiseringsposter som är äldre än den här tidsperioden (standard `30d`; till exempel `12h`). Arkiverade konversationer behåller sin historik och kan återställas; skyddade eller routningsbara konversationer förblir aktiva."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Lagringstid för arkiv från sessionsåterställningar`},help:{"v1-3rw301-7l":"Åldersbaserad lagringstid för arkiverade chattar (`*.reset.<timestamp>` och `*.deleted.<timestamp>`). Som standard behålls arkiven tills diskutrymmesgränsen kräver att de tas bort, med de äldsta först. Ange en tidsperiod (till exempel `30d`) för att aktivera tidsbaserad radering, eller `false` för att uttryckligen inaktivera den."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Meddela Home när en session skapas`},help:{"v1-14mr1ov-8m":`Köa ett systemmeddelande i den ansvariga agentens hemsession när en session skapas (standard: true). Meddelandena innehåller tillgänglig titel och metadata om skaparen och läses vid nästa tur i hemsessionen eller vid nästa schemalagda automatisering. Ange false för att inaktivera; utkast, inkognitosessioner, interna sessioner och schemalagda cron-körningar undantas.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Policy för sessionsåterställning`},help:{"v1-1hmt7n3-6r":`Definierar standardobjektet för återställningspolicyn som används när ingen typspecifik eller kanalspecifik åsidosättning gäller. Som standard återställs sessioner inte automatiskt; aktivera detta med dagliga eller inaktivitetsbaserade scheman, medan /new och /reset alltid är tillgängliga.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Timme för daglig sessionsåterställning`},help:{"v1-wry8cv-59":`Anger timgränsen i lokal tid (0–23) för daglig återställning så att sessioner byts vid förutsägbara tidpunkter. Använd med mode=daily och anpassa till operatörens förväntade tidszon för ett lättbegripligt beteende.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Inaktivitetsminuter före sessionsåterställning`},help:{"v1-1kzj0id-5e":`Anger inaktivitetsperioden före återställning i inaktivitetsläget och kan även fungera som en extra säkerhetsåtgärd i det dagliga läget. Använd högre värden för att bevara kontinuiteten eller lägre värden för fräschare, kortlivade trådar.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Läge för sessionsåterställning`},help:{"v1-e5ie4w-5b":`Väljer återställningsstrategi: "none" inaktiverar automatisk återställning (standard), "daily" återställer vid en konfigurerad timme och "idle" återställer efter inaktivitet. /new och /reset är tillgängliga i alla lägen.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Sessionsåterställning per kanal`},help:{"v1-1uxsulx-5h":`Tillhandahåller kanalspecifika åsidosättningar av återställningen med leverantörs-/kanal-id som nyckel för detaljerad styrning av beteendet. Använd endast detta när en kanal behöver ett särskilt återställningsbeteende utöver policyerna på typnivå.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Sessionsåterställning per chattyp`},help:{"v1-ypdr7u-52":`Åsidosätter återställningsbeteendet per chattyp (direktchatt, grupp, tråd) när standardinställningarna inte räcker till. Använd detta när grupp- eller trådtrafik behöver en annan återställningsfrekvens än direktmeddelanden.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Sessionsåterställning (direktchatt)`},help:{"v1-22e702-54":`Definierar återställningspolicyn för direktchattar och åsidosätter grundkonfigurationen session.reset för den typen. Använd detta som den aktuella åsidosättningen för direktmeddelanden i stället för det äldre aliaset dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Sessionsåterställning (grupp)`},help:{"v1-hl1200-4u":`Definierar återställningspolicyn för gruppchattsessioner där kontinuitet och brusmönster skiljer sig från direktmeddelanden. Använd kortare inaktivitetsperioder för aktiva grupper om kontextförskjutning blir ett problem.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Sessionsåterställning (tråd)`},help:{"v1-1hgpeke-4w":`Definierar återställningspolicyn för trådbundna sessioner, inklusive fokuserade arbetsflöden i kanaltrådar. Använd detta när trådsessioner ska upphöra snabbare eller långsammare än andra chattyper.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Utlösare för sessionsåterställning`},help:{"v1-rcabsw-5a":`Listar meddelandeutlösare som tvingar fram en sessionsåterställning när de matchar inkommande innehåll. Använd sparsamt för uttryckliga återställningsfraser så att kontext inte försvinner oväntat under vanliga samtal.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Sessionens omfattning`},help:{"v1-axt4ds-5z":`Anger grundstrategin för sessionsgruppering: "per-sender" isolerar efter avsändare och "global" delar en session per kanalkontext. Behåll "per-sender" för säkrare beteende med flera användare, såvida inte delad kontext uttryckligen krävs.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Sändningspolicy för sessioner`},help:{"v1-17zdvww-61":`Styr leverans i sessioner med regler för att tillåta eller neka som utvärderas mot channel, chatType och nyckelprefix. Detta är separat från tillåtelsekontrollen för inkommande och utgående meddelanden mellan parter; använd session.communication för dessa standardinställningar.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Standardåtgärd för sessioners sändningspolicy`},help:{"v1-15plhut-53":`Anger standardåtgärden när ingen sendPolicy-regel matchar: "allow" eller "deny". Behåll "allow" för enklare konfigurationer eller välj "deny" när du kräver uttryckliga tillåtelseregler för varje destination.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Regler för sessionens sändningspolicy`},help:{"v1-o217za-5h":'Ordnade regler för att tillåta eller neka som utvärderas före standardåtgärden, till exempel `{ action: "deny", match: { channel: "discord" } }`. Placera de mest specifika reglerna först så att breda regler inte åsidosätter undantag.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Åtgärd för sessionens sändningsregel`},help:{"v1-178vm80-54":`Definierar regelns beslut som "allow" eller "deny" när motsvarande matchningskriterier är uppfyllda. Placera nekanderegler först när du tillämpar strikta gränser med uttryckliga undantag som tillåter sändning.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Matchning för sessionens sändningsregel`},help:{"v1-18qh5qg-5d":`Definierar valfria matchningsvillkor för regeln som kan kombinera begränsningar för channel, chatType och nyckelprefix. Håll matchningarna snäva så att policyns avsikt förblir tydlig och felsökningen enkel.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Kanal för sessionens sändningsregel`},help:{"v1-u5erwx-50":`Begränsar regelns tillämpning till ett specifikt kanal- eller leverantörs-id (till exempel discord, telegram, slack). Använd detta när en kanal ska tillåta eller neka leverans oberoende av andra.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Chattyp för sessionens sändningsregel`},help:{"v1-7cv4f9-4z":`Matchar regelns tillämpning mot chattyp (direct, group, thread) så att beteendet varierar med samtalsformen. Använd detta när destinationer för direktmeddelanden och grupper kräver olika säkerhetsgränser.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Nyckelprefix för sessionens sändningsregel`},help:{"v1-ac4dee-5n":`Matchar ett normaliserat sessionsnyckelprefix efter interna nyckelnormaliseringssteg i komponenter som tillämpar policyn. Använd detta för allmän prefixstyrning och välj i första hand rawKeyPrefix när exakt matchning av hela nyckeln krävs.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Rått nyckelprefix för sessionens sändningsregel`},help:{"v1-1g9w044-5e":`Matchar det råa, onormaliserade sessionsnyckelprefixet för att rikta policyn exakt utifrån hela nyckeln. Använd detta när normaliserat keyPrefix är för brett och du behöver precision baserad på agentprefix eller specifik transport.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Delningslägen för sessioner`},help:{"v1-xbh52d-5a":`Styr vilka samarbetslägen sessionsägare och administratörer får välja. Utelämnade booleska värden är aktiverade som standard. Sätt ett läge till false för att ta bort det från väljaren och avvisa nya val av det.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Tillåt utkastsessioner`},help:{"v1-1lzap27-2p":`Tillåter synlighet som utkast, vilket döljer sessioner för operatörer som varken är ägare eller administratörer. Standard: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Tillåt skrivskyddade sessioner`},help:{"v1-upl3nu-21":`Tillåter att sessioner görs skrivskyddade för personer som inte deltar. Standard: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Tillåt sessioner i förslagsläge`},help:{"v1-4i8owu-4g":`Tillåter synlighet för förslag. I den här fasen tillämpas samma åtkomstpolicy som för skrivskyddat läge; förslagsköer konfigureras av en senare funktion. Standard: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Sökväg för sessionslagring`},help:{"v1-hreznz-56":`Anger sökvägen till lagringsfilen som används för att bevara sessionsposter mellan omstarter. Använd en explicit sökväg endast när du behöver anpassad disklayout, styrning av säkerhetskopiering eller lagring på en monterad volym.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Trådbindningar för sessioner`},help:{"v1-zbzihu-4s":`Gemensamma standardinställningar för att skapa och dirigera trådbundna sessioner i kanaler som stöds. Konfigurera globala standardinställningar här och åsidosätt dem per kanal endast när beteendet skiljer sig åt.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Kontext för att skapa trådbundna sessioner`},help:{"v1-gnhqsg-46":`Standardkontext för inbyggda underagenter som skapas med trådbindning. Använd "fork" för att utgå från den begärande chatten eller "isolated" för en underagent med tom kontext. Standard: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Trådbindning aktiverad`},help:{"v1-foomtc-3f":`Global huvudinställning för att skapa och dirigera trådbundna sessioner samt leverera till dem. Inaktivera för att stänga av trådbindning globalt.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Inaktivitetstidsgräns för trådbindning (timmar)`},help:{"v1-gffnx3-3h":`Standardgräns för inaktivitet i timmar för trådbundna sessioner hos olika leverantörer och i olika kanaler (0 inaktiverar avslut vid inaktivitet). Standard: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Maximal ålder för trådbindning (timmar)`},help:{"v1-1xfcyhw-39":`Valfri absolut maxålder i timmar för trådbundna sessioner hos alla leverantörer och i alla kanaler (0 inaktiverar den absoluta gränsen). Standard: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Skapande av trådbundna sessioner`},help:{"v1-1lqwbdl-46":`Global standardinställning som styr om trådbundna arbetssessioner får skapas via sessions_spawn och ACP-trådskapanden. Standard: true när trådbindningar är aktiverade.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Tillåtna mål för symboliska länkar till färdigheter`},help:{"v1-xzybiq-4t":`Betrodda faktiska målrotkataloger som symboliska länkar till färdigheter får peka in i när målen ligger utanför den konfigurerade källrotkatalogen. Begränsa detta till ett snävt urval, till exempel en färdighetskatalog i ett intilliggande repo.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Extra färdighetskataloger`},help:{"v1-11o7opu-53":`Ytterligare delade rotkataloger för färdigheter som ska genomsökas med lägst prioritet. Använd detta för intilliggande repon eller delade färdighetspaket som ska vara tillgängliga utan att kopieras till OpenClaw-arbetsytan.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Bevaka Skills`},help:{"v1-1g8a3b0-8g":`Aktivera upptäckt av färdigheter som utlöses av filsystemet, med en extra genomsökning var 30:e minut för att fånga upp missade händelser. Även om detta inaktiveras uppdateras färdigheter omedelbart vid uttryckliga ändringar av färdigheter i OpenClaw, relevanta konfigurationsändringar och start av Gateway. Befintliga sessioner använder ändrade ögonblicksbilder vid nästa agenttur.`}},storage:{label:{"v1-eop0jq-7":`Lagring`},help:{"v1-j0mwbg-4w":`Återanvändbara lagringsplatser för OpenClaw-artefakter. Den centrala lagringsfunktionen ansvarar för platsidentitet, kryptering och hälsostatus; leverantörer transporterar objekt och konsumenter avgör vad som ska behållas.`}},"storage%2Elocations":{label:{"v1-uok3ae-h":`Lagringsplatser`},help:{"v1-1ipmwky-5k":`Namngivna lagringsdestinationer. Namnen innehåller 1–63 gemener, siffror eller bindestreck och börjar med en bokstav eller siffra. Varje destination har en initieringsmarkör som aldrig skapas av skrivningar under körning.`}},"storage%2Elocations%2E*":{label:{"v1-1pbn8xd-g":`Lagringsplats`},help:{"v1-7yhxyl-4n":`En namngiven lagringsdestination med leverantörsinställningar och ett uttryckligt val av kryptering. Initiera en ny destination med openclaw storage init innan du skriver objekt.`}},"storage%2Elocations%2E*%2Eencryption":{label:{"v1-1qp46kf-i":`Lagringskryptering`},help:{"v1-19oj6cx-6d":`Obligatoriskt krypteringsval: ett lösenfrasobjekt krypterar objekt före uppladdning; "none" inaktiverar uttryckligen kryptering. Säkerhetskopior kan innehålla inloggningsuppgifter, så använd "none" endast när destinationen redan ger lämpligt skydd.`}},"storage%2Elocations%2E*%2Eencryption%2Epassphrase":{label:{"v1-1x3jq0t-t":`Lösenfras för lagringskryptering`},help:{"v1-1o63v7d-4o":`Lösenfras som används för att kryptera denna lagringsplats. Använd helst en SecretRef och spara en kopia som går att återställa: om lösenfrasen går förlorad eller ändras blir befintliga krypterade objekt oläsbara.`}},"storage%2Elocations%2E*%2Eprovider":{label:{"v1-1dujppr-g":`Lagringsleverantör`},help:{"v1-16srbor-3w":`Lagringsleverantörens id, till exempel "filesystem". Om du refererar till en medföljande leverantör aktiveras dess insticksmodul automatiskt, såvida inte policyn för insticksmoduler inaktiverar den.`}},"storage%2Elocations%2E*%2Esettings":{label:{"v1-268wio-p":`Inställningar för lagringsleverantör`},help:{"v1-drbso5-5t":`Avgränsade JSON-inställningar som ägs av leverantören. Värden som innehåller hemligheter måste använda SecretRef-objekt, som leverantören slår upp endast vid behov. Leverantören filesystem kräver en absolut sökväg till en befintlig katalog.`}},surfaces:{label:{"v1-exl2ye-g":`Policyer för ytor`},help:{"v1-vgtjbs-50":`Åsidosättningar av meddelandepolicyn per yta, med den identifierade leveransytans id som nyckel. Använd detta endast när en driftsatt yta behöver striktare hantering av tysta svar än agentens standardinställning.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Policy för tysta svar på ytan`},help:{"v1-1un880p-4z":`Åsidosätter gruppens policy för tysta svar för en identifierad leveransyta. Fält som inte har angetts ärver agents.defaults.silentReply. Direktchattar och interna sessioner kräver alltid ett svar.`}},talk:{label:{"v1-15ukbjj-4":`Tal`},help:{"v1-1gx10xa-5g":`Inställningar för röstsyntes i talläget: röstidentitet, modellval, utdataformat och avbrottsbeteende. Använd det här avsnittet för att anpassa röstupplevelsen för användaren och samtidigt hålla svarstider och kostnader under kontroll.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Talagent`},help:{"v1-iee5l9-2b":`Agent som äger talsessioner som skapas utan en uttrycklig agentspecifik sessionsnyckel.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Snabbläge för talkonsultationer`},help:{"v1-syf3xk-2o":`Använd detta för att ange true eller false för snabbläget vid den vanliga agentkörningen bakom tallägets realtidskonsultationer.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Tänkenivå för talkonsultationer`},help:{"v1-1ft5njw-2o":`Använd detta för att åsidosätta tänkenivån för den vanliga agentkörningen bakom tallägets realtidskonsultationer.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Avbryt vid tal i talläget`},help:{"v1-8n9q4o-3l":`Om true (standardvärdet) avbryts assistentens tal när användaren börjar prata i talläget. Låt detta vara aktiverat för naturlig turtagning i samtalet.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Aktiv talleverantör`},help:{"v1-wgnxhg-1g":`ID för den aktiva talleverantören (till exempel "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Inställningar för talleverantörer`},help:{"v1-oh0yuv-30":`Leverantörsspecifika talinställningar med leverantörs-ID som nyckel. Använd i första hand detta i stället för äldre talk.*-nycklar vid migrering.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Konfiguration för talleverantör`},help:{"v1-36pblg-1r":`Leverantörens egna konfigurationsfält för tal för motsvarande leverantörs-ID.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`API-nyckel för talleverantör`},help:{"v1-1a1p9wp-v":`Leverantörens API-nyckel för Talk-läget.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk i realtid`},help:{"v1-c2re7j-3z":`Leverantör, modell, röst, läge, transport och resonemangsstrategi för Talk i realtid. Behåll konfigurationen för tal-/TTS-leverantören i talk.provider och talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Resonemang för Talk i realtid`},help:{"v1-opsatw-37":`Resonemangsstrategi för Talk: agent-consult för agenthjälp förmedlad via Gateway, direct-tools för lokala verktygsanrop eller none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Konsultationsroutning för Talk i realtid`},help:{"v1-10qjcvk-5f":`Reservväg via Gateway för slutliga transkriptioner av användarens tal när realtidsleverantören hoppar över openclaw_agent_consult. provider-direct bevarar leverantörens svar; force-agent-consult dirigerar via OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Instruktioner för Talk i realtid`},help:{"v1-1jaaj84-5p":`Ytterligare systeminstruktioner som läggs till i OpenClaws inbyggda prompt för Talk i realtid. Använd detta för röststil, ton och annat realtidsbeteende hos leverantören, samtidigt som vägledningen för agent-consult behålls intakt.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Läge för Talk i realtid`},help:{"v1-1u2xui1-1l":`Körläge för Talk: realtime, stt-tts eller transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Modell för Talk i realtid`},help:{"v1-amou5a-27":`Åsidosättning av realtidsleverantörens modell-id för Talk-sessioner i webbläsaren eller som ägs av Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Inledande utfyllnad för Talk i realtid (ms)`},help:{"v1-1cwg07n-22":`Antal millisekunder ljud som sparas innan röstaktivitet detekteras i realtid.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Realtidsleverantör för Talk`},help:{"v1-wwsmpt-1o":`ID för den aktiva realtidsröstleverantören, till exempel openai eller google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Inställningar för realtidsleverantörer för Talk`},help:{"v1-ruagcu-1r":`Leverantörsspecifika inställningar för realtidsröst med leverantörs-ID som nyckel.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Konfiguration av realtidsleverantör för Talk`},help:{"v1-edfpxm-1u":`Leverantörens konfiguration för realtidsröst för motsvarande leverantörs-ID.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`API-nyckel för realtidsleverantör för Talk`},help:{"v1-1fbmgpx-z":`Leverantörens API-nyckel för Talk i realtid.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Resonemangsnivå för Talk i realtid`},help:{"v1-157xd3e-2t":`Leverantörsspecifik resonemangsnivå för Talk-sessioner i realtid, till exempel minimal, low, medium eller high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Tystnadens varaktighet för Talk i realtid (ms)`},help:{"v1-1grnu06-1y":`Antal millisekunder av tystnad innan användarens tur i Talk i realtid markeras som avslutad.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Talarröst för Talk i realtid`},help:{"v1-1kgb166-2h":`Åsidosättning av realtidsleverantörens talarröstnamn för Talk-sessioner i webbläsaren eller som hanteras av Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Talarröst-ID för Talk i realtid`},help:{"v1-1k8w6vk-2f":`Åsidosättning av realtidsleverantörens röst-id för Talk-sessioner i webbläsaren eller som ägs av Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Realtidstransport för Talk`},help:{"v1-2otjgn-2g":`Byte-/sessionstransport för Talk: webrtc, provider-websocket, gateway-relay eller managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`VAD-tröskel för Talk i realtid`},help:{"v1-nf5l2t-2j":`Tröskel för detektering av röstaktivitet i realtid från 0 (mest känslig) till 1 (minst känslig).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Tidsgräns för tystnad i Talk (ms)`},help:{"v1-1kim32f-59":`Antal millisekunder som användaren är tyst innan Talk-läget slutför och skickar den aktuella transkriptionen. Lämna utan värde för att behålla plattformens standardpaus (700 ms på macOS och Android, 900 ms på iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Språk och region för tal i Talk`},help:{"v1-1un3x4l-4c":`BCP 47-språk-id för taligenkänning i Talk på enhetsnoder och för systemrösten som reservlösning i iOS, till exempel "ru-RU". Lämna utan värde för att använda varje enhets standardinställning.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetri`},help:{"v1-1o5tru3-55":`Uttryckligt samtycke till anonym funktionsstatistik som bifogas den dagliga uppdateringskontrollen. Funktionsstatistik är inaktiverad som standard och innehåller aldrig meddelanden, autentiseringsuppgifter eller identifierare.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Tidsstämpel för samtycke till funktionsstatistik`},help:{"v1-1t051az-3t":`ISO-tidsstämpel som registrerar när operatören godkände eller avböjde anonym funktionsstatistik. Förhindrar att installationsguiden frågar igen.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Anonym funktionsstatistik`},help:{"v1-1ptrwuq-4r":`Delar namn på aktiverade kanaler och leverantörer, antal insticksprogram och antal senaste sessioner vid den dagliga uppdateringskontrollen. Inaktiverat som standard och alltid inaktiverat när DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Verktyg`},help:{"v1-1el54kl-5h":`Verktygsinfrastruktur och standardinställningar för samverkan mellan agenter. Poster på rotnivån styr infrastrukturen och standardinställningarna för samverkan mellan agenter; agents.defaults styr agentloopens beteende; agentposter kan åsidosätta båda där detta stöds.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Verktygsåtkomst mellan agenter`},help:{"v1-1ynpa5f-cf":`Policy för sessionsverktygsanrop mellan agenter: sändning, listning, historik, sökning och statusavläsning (standard: aktiverat). Använd allow för att begränsa agentpar; enabled=false blockerar vanlig åtkomst mellan agenter. Inbyggda underagentsessioner och underordnade ACP-sessioner som ägs av den begärande agenten förblir åtkomliga med synligheten tree eller all. För strikt åtskillnad ställer du in tools.sessions.visibility på agent eller self (tree tillåter fortfarande inbyggda underagentsessioner och underordnade ACP-sessioner som ägs av den begärande agenten), eller använder separata gatewayer.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Tillåtelselista för målagenter vid åtkomst mellan agenter`},help:{"v1-1jt2ari-76":`Agent-id:n eller *-mönster som får delta i anrop mellan agenter; både den begärande agenten och målagenten måste matcha. Åtkomst mellan agenter är aktiverad som standard, och om allow utelämnas eller är tomt tillåts alla par. Ange en uttrycklig lista för att begränsa åtkomsten; tomma poster nekar åtkomst.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Aktivera verktyg för åtkomst mellan agenter`},help:{"v1-w950oq-ba":`Aktiverar åtkomst till sessionsverktyg mellan agenter (standard: true); om allow utelämnas eller är tomt tillåts alla agentpar. Ange false för att blockera vanlig åtkomst mellan agenter; inbyggda underagentssessioner och underordnade ACP-sessioner som ägs av den begärande agenten förblir åtkomliga med synligheten tree eller all. För strikt åtskillnad, sätt tools.sessions.visibility till agent eller self (tree tillåter fortfarande inbyggda underagentssessioner och underordnade ACP-sessioner som ägs av den begärande agenten), eller använd separata gateways.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Tillåtelselista för verktyg`},help:{"v1-1is3eaq-4v":`Absolut tillåtelselista för verktyg som ersätter profilbaserade standardinställningar för strikta miljöer. Använd detta endast när du avsiktligt vill använda en noggrant utvald delmängd av verktygsfunktionerna.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Tillägg till tillåtelselistan för verktyg`},help:{"v1-1xw9zp8-57":`Extra poster i tillåtelselistan för verktyg som läggs till utöver den valda verktygsprofilen och standardpolicyn. Håll listan kort och tydlig så att avsiktliga policyundantag snabbt kan identifieras vid granskningar.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Verktygspolicy per leverantör`},help:{"v1-c1lj2f-bh":`Leverantörsspecifika åsidosättningar av vilka verktyg som tillåts eller nekas, med kanal-/leverantörs-ID som nyckel, för att anpassa funktionerna efter gränssnitt. Använd detta när en leverantör behöver striktare kontroller än den globala verktygspolicyn. exec.mode anger en övre gräns för exec-körning på värden som endast kan begränsa behörigheter för turer hos den leverantören eller kombinationen av leverantör/modell (det tar aldrig bort obligatoriska godkännanden eller lättar på ett striktare läge), så läget "auto" låter endast den modellens exec-anrop som inte matchar reglerna gå via exec-granskaren.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Kodläge`},help:{"v1-1ecc39k-6k":'Generellt kodläge i OpenClaw. Om det utelämnas globalt används `"auto"` som standard; ett uttryckligen angivet objekt utan `enabled` förblir avstängt. Agentkörningar där läget är aktiverat exponerar endast `exec` och `wait` för modellen och kommer åt vanliga verktyg via katalogbryggan.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Aktivera kodläge`},help:{"v1-c7oqjw-ah":'Global aktivering av OpenClaw Code Mode. Om den globala inställningen saknas helt används `"auto"` som standard; ett angivet objekt utan `enabled` förblir inaktiverat. `"auto"` aktiverar läget för modeller som föredras i katalogen, medan `true` aktiverar det för körningar med verktygsstöd. Aktiveringsinställningar för agenter och modeller har företräde. En körning där läget är aktiverat blockeras om körmiljön inte är tillgänglig, i stället för att hela verktygslistan exponeras.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Exekverare för Code Mode`},help:{"v1-4tbmdg-7h":`JavaScript-exekverare: "node" (standard) använder Node vm för betrodd kod och är inte en säkerhetssandlåda; "quickjs" använder det medföljande QuickJS WASM-tillägget för härdad gästkörning. Verktygsbehörigheter gäller för båda. Code Mode kan inte köras om den valda exekveraren inte är tillgänglig.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Utdatagräns för Code Mode`},help:{"v1-1hmij9q-1n":`Maximalt antal serialiserade byte som returneras via utdata från kodläget.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Gräns för väntande verktygsanrop i Code Mode`},help:{"v1-3b5tyd-2i":`Maximalt antal samtidiga nästlade verktygsanrop som en virtuell maskin i kodläget kan starta innan den måste återupptas senare.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Maximalt antal sökresultat i Code Mode`},help:{"v1-1gpue5r-28":`Maximalt antal sökresultat från den dolda katalogen som ett program i kodläget kan begära.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Gräns för ögonblicksbilder i Code Mode`},help:{"v1-1mmgkqy-1x":`Maximalt antal serialiserade byte som sparas för en ögonblicksbild av en pausad QuickJS-körning.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Minnesgräns för Code Mode`},help:{"v1-xetora-6n":`Gräns för QuickJS-gästens heap eller ungefärlig V8-heapbudget för Node-arbetstråden i byte. Overhead från Node-körmiljön och motorns minsta allokeringar påverkar den faktiska budgeten; externa buffertar och processens RSS ingår inte. Detta är ingen säkerhetsgaranti.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Gränssnitt för kodläge`},help:{"v1-dsp2b9-2x":'Gränssnitt mot modellen. Endast "only" stöds: exponera kodlägets `exec` och `wait` och dölj vanliga verktyg.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Standardantal sökresultat i kodläge`},help:{"v1-1io42lu-2m":"Standardantal sökresultat från den dolda katalogen som returneras av `catalog.search` i kodläge."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`TTL för ögonblicksbilder i kodläge`},help:{"v1-1nxfczz-28":"Hur länge pausade körningar i kodläge kan återupptas med `wait` innan de löper ut."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Tidsgräns för kodläge`},help:{"v1-8csycm-1p":"Maximalt antal millisekunder för ett enskilt anrop till `exec` eller `wait` i kodläge."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Spärrlista för verktyg`},help:{"v1-wilr1b-4p":`Global spärrlista för verktyg som blockerar listade verktyg även när profil- eller leverantörsregler skulle tillåta dem. Använd spärrregler för akuta blockeringar och långsiktigt skydd i flera lager.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Verktygsåtkomst med utökade behörigheter`},help:{"v1-ehcm0r-5a":`Kontroller för verktygsåtkomst med utökade behörigheter till privilegierade kommandogränssnitt som endast bör vara tillgängliga för betrodda avsändare. Håll detta inaktiverat om inte operatörens arbetsflöden uttryckligen kräver åtgärder med utökade behörigheter.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Tillåtelseregler för verktyg med utökade behörigheter`},help:{"v1-1u9bhih-54":`Regler för tillåtna avsändare för verktyg med utökade behörigheter, vanligtvis med nycklar i kanalens eller leverantörens identitetsformat. Använd snävt avgränsade, uttryckliga identiteter så att kommandon med utökade behörigheter inte kan utlösas av obehöriga användare.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Aktivera verktygsåtkomst med utökade behörigheter`},help:{"v1-1n8oyal-4l":`Aktiverar verktygskörning med utökade behörigheter när avsändar- och policykontrollerna godkänns. Håll detta inaktiverat i offentliga eller delade kanaler och aktivera det endast i betrodda sammanhang som styrs av ägaren.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Exec-verktyg`},help:{"v1-p5piic-56":`Policygrupp för Exec-verktygets värd för skalkörning, säkerhetsläge, godkännandebeteende och körningsbindningar. Behåll försiktiga standardinställningar i produktion och begränsa körning med utökade behörigheter.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Lista över tillåtna modeller för apply_patch`},help:{"v1-4q5ovf-1x":`Valfri lista över tillåtna modell-id:n (t.ex. "gpt-5.4" eller "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Aktivera apply_patch`},help:{"v1-1erkir4-31":`Aktivera eller inaktivera apply_patch för OpenAI- och OpenAI Codex-modeller när verktygspolicyn tillåter det (standard: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch endast inom arbetsytan`},help:{"v1-1m4u5cn-4l":`Begränsa sökvägar för apply_patch på värden till arbetsytekatalogen (standard: false). Ange true för åtkomst endast till arbetsytan; obligatoriska rotkataloger och sessionsbegränsningar gäller fortfarande.`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Meddelande om pågående körning efter Exec-godkännande (ms)`},help:{"v1-1gwwann-4z":`Fördröjning i millisekunder innan ett meddelande om pågående körning visas efter att en exec-körning har godkänts. Öka värdet för att minska flimmer vid snabba kommandon, eller sänk det för snabbare återkoppling till operatören.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Fråga vid exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Kommandofärgning för exec`},help:{"v1-kyxd4o-4n":`Visa parserbaserad kommandofärgning i godkännandeförfrågningar för exec (standard: false). Aktivera detta för att visa färgad kommandotext utan att ändra godkännandepolicyn för exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Giltighetstid för stående tillstånd (dagar)`},help:{"v1-5uxe2j-6r":`Standardgiltighetstid i dagar (1–3650) för stående tillstånd som skapas av allow-always vid godkännande av automatiseringar. Om värdet inte anges förblir tillstånden giltiga tills de återkallas eller den tillhörande automatiseringen ändras. Villkoren låses när tillståndet skapas, så ändringar här påverkar endast framtida tillstånd.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Körningsmål för exec`},help:{"v1-rno1mf-5q":`Väljer strategi för körningsmål för skalkommandon. Använd "auto" för ett beteende som anpassas till körmiljön (sandbox när den är tillgänglig, annars gateway), eller ange sandbox/gateway/node uttryckligen när du behöver en fast körmiljö.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Exec-läge`},help:{"v1-1qscgnt-5q":`Normaliserad väljare för exec-policy. Använd "auto" för klassificerargranskning när godkännande saknas, "ask" för mänsklig granskning när godkännande saknas, "allowlist" för kommandon som godkänns av fasta regler eller "full" för betrodd lokal körning.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Nodbindning för exec`},help:{"v1-rfnz54-4s":`Konfiguration av nodbindning för exec-verktyg när kommandokörning delegeras via anslutna noder. Använd explicit nodbindning endast när routning mellan flera noder krävs.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Exec-avisering vid avslut`},help:{"v1-eyedrx-3r":`När värdet är true (standard) köas en uppföljning för ursprungssessionen när exec-sessioner i bakgrunden avslutas och vid livscykelhändelser för exec på noder.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Exec-avisering vid lyckat avslut utan utdata`},help:{"v1-l4v70o-6g":`När värdet är true (standard) väcks den ursprungliga sessionen även när exec-körningar i bakgrunden avslutas utan fel och med tom utdata, så att en tyst väntande process rapporterar tillbaka. Ange false för att inte avisera om lyckade körningar utan utdata; agenten hämtar dem då med process poll.`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Tillägg först i PATH för exec`},help:{"v1-s1aimc-1r":`Kataloger som ska läggas först i PATH för exec-körningar (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Exec-granskare`},help:{"v1-12y548k-4x":`Modellbaserad exec-granskare som används i automatiskt läge innan mänskligt godkännande begärs som reservlösning. Ange ett separat modellval här om du vill hålla exec-granskningen åtskild från huvudagentens modell.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Snabbläge för exec-granskare`},help:{"v1-175bx14-8u":`Valfritt snabbläge för godkännandegranskningar i OpenClaw: true begär prioriterad bearbetning via OpenAI Responses- och ChatGPT/OAuth-rutter som stöds; false begär standardbearbetning. Utelämna för att behålla leverantörens standardinställningar. Snabbläget kan kosta mer och beror på tillgängligheten hos leverantören. Konfigurerar inte den inbyggda Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Modell för exec-granskare`},help:{"v1-1lltiy5-3i":`Valfri åsidosättning av leverantör/modell för exec-granskningsagenten. Utelämna för att återanvända den konfigurerade primära modellen för målagenten.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Resonemang för exec-granskare`},help:{"v1-yg2gby-6u":`Valfri resonemangsnivå för modellbaserade godkännandegranskningar i OpenClaw: minimal, low, medium, high, xhigh eller max. Utelämna för att behålla leverantörens standardvärden. Nivåerna som stöds normaliseras för den valda modellen. Konfigurerar inte inbyggda Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Tidsgräns för exec-granskare (ms)`},help:{"v1-1o30chi-3w":`Tidsgräns per steg för exec-granskaren i millisekunder för modellförberedelse och slutförande innan mänskligt godkännande begärs i stället (standard: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Profiler för säkra binärfiler i exec`},help:{"v1-4cdcwe-29":`Valfria säkerhetsprofiler per binärfil (begränsningar för positionsargument + tillåtna/nekade flaggor).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Säkra binärfiler i exec`},help:{"v1-1of1m2s-21":`Tillåt att säkra binärfiler som endast använder stdin körs utan uttryckliga poster i tillåtelselistan.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Betrodda kataloger för säkra binärfiler i exec`},help:{"v1-zljbcn-2v":`Ytterligare uttryckligen betrodda kataloger för sökvägskontroller av säkra binärfiler (poster i PATH blir aldrig automatiskt betrodda).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Säkerhet för exec`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Kräv godkännande för inline-utvärdering`},help:{"v1-jkmgo7-5z":"Kräv uttryckligt godkännande för inline-eval-former i tolkar, såsom `python -c`, `node -e`, `ruby -e` eller `osascript -e`. Förhindrar tyst återanvändning av tillåtelselistan och ändrar ”tillåt alltid” till ”fråga varje gång” för dessa former."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Tidsgräns för körning (sekunder)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Filsystemverktyg begränsade till arbetsytan`},help:{"v1-1mhuvka-2s":`Begränsa filsystemverktyg (read/write/edit/apply_patch) till arbetsytekatalogen (standard: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI-identitet och Git-författare`},help:{"v1-1fl77im-5s":`Hanterad lokal GitHub CLI-profil och valfri Git-författare för agentverktyg. Utelämna detta objekt för att behålla det befintliga kontot och den befintliga författaren för användaren som kör Gateway; autentiseringsuppgifter för fjärrarkiv åsidosätts aldrig.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Git-författarens e-postadress`},help:{"v1-kol5g6-1i":`Valfri processlokal e-postadress för Git-författare och committer.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Git-författarens namn`},help:{"v1-z5bl1f-1h":`Valfritt processlokalt namn för Git-författare och committer.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Typ av GitHub-autentiseringsuppgifter`},help:{"v1-qi3qun-3q":`Markerar en hanterad OAuth-profil vars roterande autentiseringsuppgift för förnyelse ägs av Gateway. Profiler där detta utelämnas använder en personlig åtkomsttoken.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub-profilversion`},help:{"v1-4lzl0-27":`Opak genererad profilversion som används för att byta hanterade autentiseringsuppgifter atomärt.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Aktivera länkförståelse`},help:{"v1-23t2io-59":`Aktivera automatisk förbearbetning för länkförståelse så att URL:er kan sammanfattas före agentens resonemang. Låt vara aktiverat för fylligare kontext och inaktivera när strikt minimal bearbetning krävs.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Maximalt antal länkar för länkförståelse`},help:{"v1-ksxmcv-52":`Maximalt antal länkar som expanderas per tur vid länkförståelse. Använd lägre värden för att begränsa svarstid och kostnad i trådar med många meddelanden och högre värden när kontext från flera länkar är avgörande.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modeller för länkförståelse`},help:{"v1-6j3mnw-5a":`Lista över föredragna modeller för länkförståelse, som prövas i turordning som reservalternativ när det stöds. Använd lättviktiga modeller först för rutinmässig sammanfattning och tyngre modeller endast vid behov.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Omfattning för länkförståelse`},help:{"v1-183cwpa-55":`Styr när länkförståelse körs utifrån samtalskontext och meddelandetyp. Begränsa omfattningen för att undvika onödiga hämtningar i meddelanden där länkar inte är användbara.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Tidsgräns för länkförståelse (sek)`},help:{"v1-61v30o-4p":`Tidsgräns i sekunder för länkförståelse per länk innan länkar som inte kunnat bearbetas hoppas över. Håll tidsgränsen begränsad för att undvika långa väntetider när externa webbplatser är långsamma eller inte kan nås.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-108r5c7-h":`Skydd mot upprepade verktygsanrop`},help:{"v1-wrvlew-5k":`Styr skyddet mot upprepade verktygsanrop. Skyddet lägger till en uppmaning att byta tillvägagångssätt vid det tredje identiska verktygsanropet i följd och avslutar turen vid det tjugonde. Utelämna inställningen eller ange true för att behålla skyddet aktiverat. Ange false för att inaktivera det.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Policy för bilagor vid ljudförståelse`},help:{"v1-1s3t9s5-3o":`Välj vilka matchande ljudbilagor som ska bearbetas. Bearbeta endast den första om du inte avsiktligt vill transkribera flera bilagor.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Format för återgivning av transkription`},help:{"v1-glpdzh-3i":`Formatera den återgivna transkriptionen med platshållaren {transcript}. Behåll platshållaren oförändrad så att transkriptionen inkluderas vid leverans.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Återge transkription i chatten`},help:{"v1-1dedp8c-3r":`Återge ljudtranskriptionen i den ursprungliga chatten innan agenten bearbetar den. Aktivera detta när användare behöver kontrollera vad systemet hörde.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Aktivera ljudförståelse`},help:{"v1-1v0x7te-2m":`Aktivera ljudförståelse så att röstmeddelanden eller ljudklipp kan transkriberas och användas som kontext för agenten.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Språk för ljudförståelse`},help:{"v1-1ruqt97-3z":`Standardledtråd om språk för leverantörer av ljudtranskription. Ange den när det huvudsakliga talade språket är känt och leverantörens språkidentifiering är opålitlig.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Maximalt antal byte för ljudförståelse`},help:{"v1-1mcckc8-43":`Standardgräns för storleken på ljudindata för konfigurerade och automatiskt identifierade modeller. Ange storleken på den största inspelning som dina leverantörer och ditt nätverk ska acceptera.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Maximalt antal tecken för ljudförståelse`},help:{"v1-eo1dp-43":`Standardvärde för maximal transkriptionslängd för konfigurerade och automatiskt identifierade modeller. Använd ett lägre värde för att förhindra att långa röstanteckningar utökar agentens kontext.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Föredragen modell för ljudförståelse`},help:{"v1-1n5zya1-3c":`Prioritera en post i tools.media.models som är taggad med funktioner för ljudtranskription framför övriga kompatibla reservalternativ.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Prompt för ljudförståelse`},help:{"v1-1v5jtay-4b":`Standardprompt för ljudtranskription när en modellpost inte åsidosätter den. Håll instruktionen oförändrad när efterföljande arbetsflöden är beroende av transkriptionens stil.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Omfattning för ljudförståelse`},help:{"v1-1pptfg0-3w":`Begränsa ljudförståelse efter kanal, chattyp eller källnyckel. Håll omfattningen snäv där automatisk transkription är känslig eller kostsam.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Tidsgräns för ljudförståelse (sek)`},help:{"v1-n8wc6c-3b":`Standardtidsgräns för förfrågningar om ljudförståelse. Öka den för långa inspelningar eller långsammare lokala transkriptionsmodeller.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Parallellitet för medieförståelse`},help:{"v1-13kr9np-58":`Maximalt antal samtidiga medieförståelseoperationer per tur för bild-, ljud- och videouppgifter sammanlagt. Sänk detta i driftsmiljöer med begränsade resurser för att förhindra överbelastning av processor eller nätverk.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Bilagepolicy för bildförståelse`},help:{"v1-11hofbw-3e":`Välj vilka matchande bildbilagor som ska bearbetas. Bearbeta endast den första om inte avsikten är att analysera flera bilder.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Aktivera bildförståelse`},help:{"v1-1b2zw34-50":`Aktivera bildförståelse så att bifogade eller refererade bilder kan tolkas till textbaserad kontext. Inaktivera om du endast behöver textbaserad funktion eller vill undvika kostnader för bildbearbetning.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Maximalt antal byte för bildförståelse`},help:{"v1-jwwpd1-3v":`Standardgräns för storleken på indatabilder för konfigurerade och automatiskt identifierade modeller. Anpassa värdet efter leverantörens gränser för nyttolast och driftsmiljöns bandbredd.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Maximalt antal tecken för bildförståelse`},help:{"v1-ebnxhk-3q":`Standardvärde för maximal längd på bildbeskrivningar. Använd ett lägre värde för kompakt kontext eller ett högre värde för detaljerad OCR och scenanalys.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Föredragen modell för bildförståelse`},help:{"v1-1o2uwo6-3c":`Prioritera en post i tools.media.models som är märkt med stöd för bildförståelse framför övriga kompatibla reservalternativ.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt för bildförståelse`},help:{"v1-3a7piy-3p":`Standardprompt för bildförståelse när en post inte åsidosätter den. Använd en fast prompt när mottagande system är beroende av konsekventa beskrivningar.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Omfattning för bildförståelse`},help:{"v1-tievo1-3s":`Begränsa bildförståelse efter kanal, chattyp eller källnyckel. Håll omfattningen snäv i kanaler med hög aktivitet eller låg tillförlitlighet för att styra bearbetningen.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Tidsgräns för bildförståelse (sek)`},help:{"v1-1wcm84x-31":`Standardtidsgräns för förfrågningar om bildförståelse. Öka den för stora bilder eller långsammare lokala bildmodeller.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Gemensamma modeller för medieförståelse`},help:{"v1-1bbsp4f-3x":`Lista över modeller för medieförståelse. Använd kapacitetstaggar för bild, ljud eller video på varje post så att varje bearbetningsflöde endast väljer kompatibla reservalternativ.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Bilagepolicy för videoförståelse`},help:{"v1-1qm1qrc-3e":`Välj vilka matchande videobilagor som ska bearbetas. Bearbeta endast den första om du inte avsiktligt vill analysera flera videor.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Aktivera videoförståelse`},help:{"v1-1ltx5gl-58":`Aktivera videoförståelse så att klipp kan sammanfattas till text för efterföljande resonemang och svar. Inaktivera om videobearbetning strider mot policyn eller är för kostsam för din driftsmiljö.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Maximalt antal byte för videoförståelse`},help:{"v1-2mp77v-3v":`Standardgräns för storleken på videoindata för konfigurerade och automatiskt identifierade modeller. Anpassa den efter leverantörens gränser för datamängd och driftsmiljöns bandbredd.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Maximalt antal tecken för videoförståelse`},help:{"v1-1j0x40b-3j":`Förvald maximal längd för videobeskrivningar. Använd ett lägre värde för kompakt kontext eller ett högre värde för detaljerade scensammanfattningar.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Föredragen modell för videoförståelse`},help:{"v1-1cygq5k-3c":`Prioritera en funktionsmärkt post i tools.media.models för videoförståelse före övriga kompatibla reservalternativ.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt för videoförståelse`},help:{"v1-692dhv-3m":`Förvald prompt för videoförståelse när en post inte åsidosätter den. Använd en fast prompt när mottagande system är beroende av enhetliga sammanfattningar.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Omfattning för videoförståelse`},help:{"v1-7gfrx3-3s":`Begränsa videoförståelse efter kanal, chattyp eller källnyckel. Håll omfattningen snäv i aktiva eller icke betrodda kanaler för att styra bearbetningen.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Tidsgräns för videoförståelse (sek)`},help:{"v1-e8rzsy-33":`Förvald tidsgräns för begäranden om videoförståelse. Öka den för längre klipp eller långsammare lokala analysmodeller.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Lista över tillåtna meddelandeåtgärder`},help:{"v1-1iceqwa-5c":`Global lista över tillåtna meddelandeåtgärder för meddelandeverktyget. Använd endast när hela körmiljön ska tillgängliggöra och acceptera en begränsad uppsättning åtgärder. För offentliga eller sandlådeskyddade agenter bör du i stället använda separata tillåtelselistor per agent.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Aktivera massutskick av meddelanden`},help:{"v1-1ms74z7-14":`Aktivera åtgärden för massutskick (standard: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Tillåt kommunikation mellan kontexter (olika leverantörer)`},help:{"v1-276qxo-2s":`Tillåt sändning mellan olika leverantörer (standard: true). Ange false för att blockera meddelanden mellan leverantörer.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Tillåt kommunikation mellan kontexter (samma leverantör)`},help:{"v1-1sg4x49-1z":`Tillåt sändning till andra kanaler hos samma leverantör (standard: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Markör för kommunikation mellan kontexter`},help:{"v1-1fg6jrp-1z":`Lägg till en synlig ursprungsmarkör vid sändning mellan kontexter (standard: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Prefix för markör för kommunikation mellan kontexter`},help:{"v1-eblsru-1p":`Textprefix för markörer för kommunikation mellan kontexter (stöder "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Suffix för markör för kommunikation mellan kontexter`},help:{"v1-1nk0jub-1p":`Textsuffix för markörer för kommunikation mellan kontexter (stöder "{channel}").`}},"tools%2Eopenclaw":{label:{"v1-m2tz7g-j":`Delegering till OpenClaw`},help:{"v1-4bdi5v-26":`Godkännandepolicy för bestående ändringar som delegeras till systemagenten OpenClaw.`}},"tools%2Eopenclaw%2EautoApproveChanges":{label:{"v1-1arx74u-u":`Godkänn delegerade ändringar automatiskt`},help:{"v1-1gy96r5-br":`Stående tillstånd för tillåten delegerad administration, inklusive konfiguration som kan köra kod på Gateway-värden. true tillåter ändringar utan individuellt godkännande, även när verktyg för direkt körning nekas; false kräver alltid godkännande. Om inställningen utelämnas används uttryckligen beviljad fullständig åtkomst eller oberoende verifierad obegränsad körning på Gateway. Begränsningar för filsystem, sandlåda, åtgärder och den aktuella körningen gäller fortfarande.`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Verktygsprofil`},help:{"v1-h6k98q-5k":`Globalt verktygsprofilnamn som används för att välja en fördefinierad grundpolicy för verktyg innan undantag för tillåtelse eller nekande tillämpas. Använd detta för en enhetlig miljökonfiguration för alla agenter och håll profilnamnen oförändrade.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Verktygspolicy för sandlåda`},help:{"v1-ea7awo-4k":`Omslutande verktygspolicy för agentkörningar i sandlåda, så att dessa körningar kan ha egna gränser för tillåtna funktioner. Använd detta för att upprätthålla högre säkerhet i sandlådekontexter.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Policy för tillåtna och nekade verktyg i sandlådan`},help:{"v1-ub701o-4t":`Policy för att tillåta eller neka verktyg som tillämpas när agenter körs i sandlådemiljöer. Håll policyerna minimala så att uppgifter i sandlådan inte kan eskalera till onödiga externa åtgärder.`}},"tools%2Esessions%2EallowThreadTargets":{label:{"v1-1o1dl7e-p":`Tillåt trådar som sändningsmål`},help:{"v1-1ppcmoz-6v":`Tillåt att sessions_send riktas till chattsessioner som är avgränsade till trådar eller ämnen, till exempel forumämnen i Telegram eller trådar i Slack/Discord (standard: false). Målet körs i den sessionen; allt det skickar med meddelandeverktyget hamnar i tråden som användaren ser.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Synlighet för sessionsverktyg`},help:{"v1-1p13n9k-fm":`Styr vilka sessioner som kan nås med sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all", standard = alla sessioner på Gateway, inklusive andra agenters och användares; "agent" = alla sessioner under det aktuella agent-id:t; "self" = endast den aktuella; "tree" = den aktuella sessionen + startade underagenters sessioner). Åtkomst mellan agenter är aktiverad som standard och avgränsas av tools.agentToAgent; använd snävare synlighet för att begränsa läsning och vanliga sändningar. Uttryckliga destinationer i agents.entries.<id>.tools.agentToAgent.send kan tillåta sändningar utan att utöka läsåtkomsten.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Verktygspolicy för underagenter`},help:{"v1-1xoug01-4z":`Övergripande verktygspolicy för startade underagenter som begränsar eller utökar verktygstillgången jämfört med den överordnade agentens standardinställningar. Använd detta för att hålla delegerade agenters funktioner avgränsade till uppgiftens syfte.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Policy för tillåtna och nekade verktyg för underagenter`},help:{"v1-7vxsbf-5d":`Policy för tillåtna och nekade verktyg som tillämpas på startade underagenters körmiljöer. Håll denna mer restriktiv än den överordnade agentens behörigheter. Verktyg som ägs av den överordnade agenten, såsom progress_card, nekas alltid, även via allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Svärm`},help:{"v1-1q96vvs-45":`Orkestrering av underagenter i insamlingsläge. Aktiverat som standard; ange false för att inaktivera. Verktygsbehörigheter gäller fortfarande för agents_wait och svärmens startalternativ.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Standardagent för svärm`},help:{"v1-p4alpg-2m":`Standardmålagent för svärmstarter där agentId utelämnas. Listan över tillåtna underagenter gäller fortfarande.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Aktivera svärm`},help:{"v1-1nnnrq9-2e":`Aktiverar underagenter i insamlingsläge och agents_wait. Aktiverat som standard; ange false för att inaktivera.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Aktiva underagenter per svärmgrupp`},help:{"v1-kfx6qp-1c":`Maximalt antal aktiva underagenter i insamlingsläge per svärmgrupp.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1a16wrf-z":`Samtidiga underagenter per svärmgrupp`},help:{"v1-1ednj37-70":`Maximalt antal underagenter i insamlingsläge som körs i varje svärmgrupps separata körningsspår (standard: 32), oberoende av den vanliga samtidighetsgränsen för underagenter. Varje underagent som körs använder en modellström och en isolerad arbetsinstans i Code Mode. Gruppens antagningsgränser gäller fortfarande.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Totalt antal underagenter per svärmgrupp`},help:{"v1-1gc9vl1-1e":`Maximalt antal starter av underagenter i insamlingsläge under en svärmgrupps livstid.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Maximal väntetidsgräns för svärm`},help:{"v1-bog18y-1g":`Maximal tidsgräns som accepteras av agents_wait, i sekunder.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Verktygssökning`},help:{"v1-g2rpl8-80":`Komprimera stora verktygskataloger för OpenClaw, MCP och klienter. OpenClaws körmiljöer använder automatiskt strukturerad verktygssökning när inställningen inte är angiven; aktiverat kodläge har företräde och Codex använder sin inbyggda sökning. Ange false för att inaktivera funktionen, true för strukturerad sökning eller använd objektformen för att välja ett läge.`}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Aktivera verktygssökning`},help:{"v1-1naa8jz-3v":`Aktiverar verktygssökning. När funktionen är på döljer OpenClaw stora verktygskataloger bakom strukturerade verktyg för sökning, beskrivning och anrop vid körningar i den inbäddade körmiljön.`}},"tools%2EtoolSearch%2Eexclude":{label:{"v1-1040rv9-t":`Exkluderingsselektorer för verktygssökning`},help:{"v1-pmx6vl-60":`Verktyg som ska förbli direkt synliga i stället för att katalogiseras. Använder samma selektorer som include; exkludering har företräde. Om värdet utelämnas eller är [] exkluderas inget. Ger inga behörigheter och åsidosätter inte verktyg som endast får anropas direkt eller som krävs vid körning.`}},"tools%2EtoolSearch%2Eexclude%5B%5D%2Ename":{label:{"v1-7sh15i-i":`Exkluderat verktygsnamn`},help:{"v1-ke0ysb-4v":`Registrerat verktygsnamn eller globmönster med * som ska förbli direkt tillgängligt, med normalisering enligt verktygspolicyn. Selektorer med enbart namn matchar oavsett källa; ange även källa för att undvika oavsiktliga matchningar.`}},"tools%2EtoolSearch%2Eexclude%5B%5D%2Esource":{label:{"v1-1u3p208-k":`Exkluderad verktygskälla`},help:{"v1-1r3h9ad-2x":`Ursprung som ska exkluderas från katalogisering: "openclaw", "mcp" eller "client". Kombineras med name med logiskt OCH när båda anges.`}},"tools%2EtoolSearch%2Einclude":{label:{"v1-130v30b-t":`Inkluderingsselektorer för verktygssökning`},help:{"v1-1567ter-7t":`Presentationsselektorer för policygodkända verktyg som kan katalogiseras. Om värdet utelämnas väljs alla kvalificerade verktyg; [] väljer inga. Fält inom en selektor kombineras med logiskt OCH; selektorer kombineras med logiskt ELLER. Verktyg som inte väljs kan fortfarande anropas direkt. Påverkar inte oberoende Code Mode eller inbyggd sökning i Codex.`}},"tools%2EtoolSearch%2Einclude%5B%5D%2Ename":{label:{"v1-ewc3qk-i":`Inkluderat verktygsnamn`},help:{"v1-8gy1xg-4o":`Registrerat verktygsnamn eller globmönster med *, med normalisering enligt verktygspolicyn (inklusive alias). Selektorer med enbart namn matchar oavsett källa. Inget stöd för reguljära uttryck eller expansion av verktygsgrupper.`}},"tools%2EtoolSearch%2Einclude%5B%5D%2Esource":{label:{"v1-31fgve-k":`Inkluderad verktygskälla`},help:{"v1-19ewj5n-52":`Verktygets ursprung: "openclaw" för kärnverktyg och insticksprogram som inte är MCP-baserade, "mcp" för registrerade MCP-verktyg eller "client" för verktyg som tillhandahålls av klienten. Ange en källa tillsammans med namnen för att undvika matchningar med snarlika namn.`}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Maximalt antal resultat för verktygssökning`},help:{"v1-7du4kh-32":`Maximalt antal resultat från verktygssökning som en modell kan begära. Körmiljön begränsar värden till det tillåtna intervallet 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Gränssnitt för verktygssökning`},help:{"v1-1uvcg7i-6z":`Välj det gränssnitt som modellen ser: "tools" (standard) tillgängliggör strukturerade verktyg för sökning, beskrivning och anrop; "directory" håller en begränsad verktygskatalog synlig, tillgängliggör en begränsad uppsättning scheman som sannolikt behövs eller krävs och gör resten tillgängliga via sökning, beskrivning och anrop.`}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Standardantal resultat för verktygssökning`},help:{"v1-1uchq7t-39":"Antal resultat från verktygssökning som returneras som standard när modellen inte anger någon gräns. Körmiljön begränsar detta till `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Aktivera verktyg för strukturerad planering`},help:{"v1-1xgegme-4o":"Enhetligt statusverktyg för `progress_card` för beständiga planer och löpande anteckningar i överordnade sessioner. Aktiverat som standard; ange false för att inaktivera. Alltid otillgängligt för underagenter."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Webbverktyg`},help:{"v1-fpsy5-4y":`Gruppering av policyinställningar för webbverktyg som styr sök- och hämtningsleverantörer, gränser och reservbeteende. Se till att aktiverade inställningar stämmer överens med tillgången till API-nycklar och policyn för utgående nätverkstrafik.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`Cache-TTL för webbhämtning (min)`},help:{"v1-1hk89qp-17":`Cache-TTL i minuter för resultat från web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Aktivera verktyget för webbhämtning`},help:{"v1-yrswld-1f":`Aktivera verktyget web_fetch (enkel HTTP-hämtning).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Begärandehuvuden för webbhämtning`},help:{"v1-16bjkv5-me":"Extra begärandehuvuden som skickas med direkta web_fetch-begäranden, till exempel huvuden för gateway-routning eller autentisering. Varje konfigurerat värde behandlas som känsligt och maskeras i exponerad konfiguration och insamlad felsökningsdata. Värdena är vanliga strängar, stöder ${VAR}-substitution och den globala escape-sekvensen $${VAR} för bokstavliga värden, och skickas till URL:er som modellen väljer. Poster valideras när begäran byggs i stället för när konfigurationen läses in, så ett ogiltigt namn eller ett värde som inte kan skickas tas bort och loggas i stället för att funktionen inaktiveras; Accept, Accept-Language, User-Agent och inramningshuvuden som Transfer-Encoding tas också bort. Använd tools.web.fetch.userAgent för att ändra användaragenten. Omdirigeringar mellan olika ursprung behåller endast huvuden på guarded-fetch-listan över tillåtna säkra huvuden, och ändringar av de huvuden som faktiskt skickas delar upp hämtningscachen."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Maximalt antal tecken för webbhämtning`},help:{"v1-12d1fw7-1d":`Maximalt antal tecken som returneras av web_fetch (trunkeras).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Absolut teckengräns för webbhämtning`},help:{"v1-cl2mf1-1v":`Absolut övre gräns för maxChars i web_fetch (gäller konfiguration och verktygsanrop).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Maximalt antal omdirigeringar för webbhämtning`},help:{"v1-t6eak9-1h":`Maximalt antal tillåtna omdirigeringar för web_fetch (standard: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Maximal nedladdningsstorlek för webbhämtning (byte)`},help:{"v1-q6ld9c-10":`Maximal nedladdningsstorlek före trunkering.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Leverantör för webbhämtning`},help:{"v1-6pb3nv-v":`ID för reservleverantör för webbhämtning.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Extrahering med Readability för webbhämtning`},help:{"v1-19exqzx-2c":`Använd Readability för att extrahera huvudinnehållet från HTML (använder enkel HTML-rensning som reservmetod).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`SSRF-policy för webbhämtning`},help:{"v1-qtn7zx-3c":`Avgränsade åsidosättningar av SSRF-policyn för web_fetch. Begränsa omfattningen och aktivera endast för kända proxymiljöer i lokala nätverk.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Tillåtna värdnamn för webbhämtning`},help:{"v1-1j9ctya-35":`Exakta värdnamn eller IP-adressliteraler som tillåts för web_fetch, inklusive mål som annars blockeras. Håll listan så kort som möjligt.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Tillåt IPv6-intervallet för unika lokala adresser vid webbhämtning`},help:{"v1-1eyz55i-3b":`Tillåt unika lokala IPv6-adresser (fc00::/7) för kompatibilitet med betrodda fake-IP-proxyer som sing-box, Clash eller Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Webbhämtning: tillåt testintervallet enligt RFC 2544`},help:{"v1-u5asdb-2y":`Tillåt IP-adresser i testintervallet enligt RFC 2544 (198.18.0.0/15) för kompatibilitet med fake-IP-proxyer som Clash eller Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Webbhämtning: blockerade värdnamn`},help:{"v1-1164vvk-66":`Värdnamnsmönster som blockeras före DNS och tillåtelseregler vid varje omdirigering i web_fetch. Stöder exakta värdnamn och "*.example.com" för enbart underdomäner; lägg till "example.com" separat för att blockera rotdomänen. Ett tomt eller ej angivet värde lägger inte till några blockeringar.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Webbhämtning: tillåt privat nätverk (riskabelt)`},help:{"v1-2s6mv7-3t":`Ger web_fetch åtkomst till mål i privata och interna nätverk. Låt vara inaktiverat om inte URL:er som väljs av modellen är betrodda i den här driftsmiljön.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Webbhämtning: tidsgräns (sek)`},help:{"v1-1c3yfr4-16":`Tidsgräns i sekunder för web_fetch-förfrågningar.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`Webbhämtning: User-Agent`},help:{"v1-s7pe8j-1e":`Åsidosätt User-Agent-headern för web_fetch-förfrågningar.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Webbhämtning: betrodd proxy från miljövariabler`},help:{"v1-1ypkqj7-54":`Dirigera web_fetch via en betrodd HTTP(S)-proxy som anges via miljövariabler och låt proxyn hantera DNS-uppslagning. Aktivera endast om proxyn kontrolleras av operatören och tillämpar regler för utgående trafik efter DNS-uppslagning.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL för webbsökningscache (min)`},help:{"v1-6trzlf-18":`TTL för cachelagrade web_search-resultat i minuter.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Aktivera webbsökningsverktyget`},help:{"v1-n1cm4y-27":`Aktivera hanterad web_search och valfri inbyggd Codex-sökning för modeller som stöds.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Maximalt antal webbsökningsresultat`},help:{"v1-mrw7mi-z":`Antal resultat som ska returneras (1–10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Tillåtna domäner för Codex`},help:{"v1-1cv4y44-43":`Lista över tillåtna domäner för inbyggd web_search i Codex. Under turer med inbyggd, värdbaserad sökning begränsar den även hanterad web_fetch; turer med hanterad leverantör påverkas inte.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Kontextstorlek för Codex-sökning`},help:{"v1-antack-1u":`Vägledande kontextstorlek för inbyggd Codex-sökning: "low", "medium" eller "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Aktivera inbyggd webbsökning i Codex`},help:{"v1-ek2jzd-1k":`Aktivera inbyggd webbsökning i Codex för modeller med Codex-stöd.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Läge för webbsökning i Codex`},help:{"v1-1ahyq9f-32":`Inställning för inbyggd webbsökning i Codex: "cached" (standard; i Codex-turer utan begränsningar används live) eller "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Codex-användarens stad`},help:{"v1-1y95orp-1d":`Ungefärlig stad som skickas till den inbyggda webbsökningen i Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Codex-användarens land`},help:{"v1-1xkm5ms-1g":`Ungefärligt land som skickas till den inbyggda webbsökningen i Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Codex-användarens region`},help:{"v1-lhar02-1l":`Ungefärlig region/delstat som skickas till den inbyggda webbsökningen i Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Codex-användarens tidszon`},help:{"v1-fgv9fh-1h":`Ungefärlig tidszon som skickas till den inbyggda webbsökningen i Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Webbsökningsleverantör`},help:{"v1-10omglr-1x":`Sökleverantörens id. Identifieras automatiskt utifrån tillgängliga API-nycklar om det utelämnas.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Tidsgräns för webbsökning (sek)`},help:{"v1-i0egvw-17":`Tidsgräns i sekunder för web_search-förfrågningar.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transkriptioner`},help:{"v1-1i0sc09-66":`Grundläggande inställningar för insamling av transkriptioner för mötesanteckningar, agentverktyg med inspelningsfunktion och konfigurerade källor för automatisk start av livemöten. Mötesinsticksprogram sparar beständiga anteckningar som standard; ställ in enabled på false för att inaktivera detta globalt.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Källor för automatisk start av transkriptioner`},help:{"v1-1mzsl79-5s":`Källor för livetranskription som hanteras automatiskt från det att Gateway startar. Varje post aktiveras genom att finnas med; ta bort en post för att inaktivera den källan. Källorna samlar in kontinuerligt om inte whenOccupied är aktiverat.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Konto-ID för transkription`},help:{"v1-6g2kjj-4b":`Valfri identifierare för leverantörskonto eller arbetsyta för transkriptionskällor som behöver särskilja konton. Använd leverantörens dokumenterade format för konto-ID.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Kanal-ID för transkription`},help:{"v1-1lk9d5o-4u":`Leverantörens kanal-ID för livetranskriptionskällan, till exempel en röstkanal i Discord eller en kanal för spontanmöten i Slack. Kontrollera vad ID:t avser hos den aktuella leverantören innan du aktiverar automatisk start.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Server-ID för Discord`},help:{"v1-fyfgnk-4l":`Valfritt server-ID för Discord för källor som transkriberar röst i Discord. Konfigurera detta med motsvarande channelId när leverantören behöver slå upp röstkanaler inom en viss server.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`Mötes-URL för transkription`},help:{"v1-1xtt9ci-4f":`Valfri mötes-URL för leverantörer som ansluter via URL i stället för kanal-ID. Använd endast betrodda möteslänkar eftersom automatisk start kan ansluta till och spela in mötet.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Leverantörs-ID för transkriptionskälla`},help:{"v1-1uur06p-3s":`ID för transkriptionskällans leverantör, till exempel en leverantör för Discord-röstkanaler eller framtida Slack-huddles. Använd det exakta ID som leverantörens insticksprogram tillhandahåller.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Sessions-ID för transkription`},help:{"v1-xyo4x5-5o":`Valfritt fast sessions-ID för transkription för denna automatiskt startade källa. Ignoreras när whenOccupied är true. Lämna värdet osatt för att generera ID:n, såvida du inte behöver en stabil daglig väljare och kan undvika kollisioner samma dag.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Transkriptionstitel`},help:{"v1-ycjnmp-5y":`Valfri titel för framtida transkriptionsinsamlingar. Om endast titlar ändras fortsätter pågående insamlingar utan att deras ursprungliga titel eller sparade anteckningar byter namn. Andra ändringar av källan hanteras som vanligt vid omstart.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Transkriptionsinsamling vid närvaro`},help:{"v1-34jid4-78":`Starta en ny transkriptionssession varje gång människor är närvarande i källan och stoppa den (och generera anteckningar) när den sista personen lämnar. Kräver en leverantör som rapporterar närvaro, till exempel discord-voice. Standard: false (samla in kontinuerligt från det att Gateway startar).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transkriptioner aktiverade`},help:{"v1-fyqqr0-6d":`Aktiverar beständiga automatiska mötesanteckningar, agentverktyget transcripts och konfigurerade automatiskt startade källor. Standard: true. Ange false för att inaktivera beständig lagring och verktyget; uttryckligt transkriptionsläge för möten behåller sin begränsade livevy av det senaste innehållet.`}},tts:{label:{"v1-bmxkk9-e":`Text till tal`},help:{"v1-1o27tk2-4n":`Policy för text-till-tal för uppläsning av agentsvar i röst- eller ljudgränssnitt som stöds. Låt vara inaktiverad om röstuppspelning inte ingår i operatörens eller användarens arbetsflöde.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS-persona`},help:{"v1-1r0opcb-29":`Standard-id för TTS-persona. Lokala inställningar för TTS-persona kan åsidosätta detta per värddator.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS-personor`},help:{"v1-19aybhl-2l":`Namngivna TTS-personor som definierar en konsekvent röstidentitet samt leverantörsspecifika talkopplingar.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS-persona`},help:{"v1-10s52ah-2l":`En TTS-persona. Använd leverantörsspecifika kopplingar för exakta röster/modeller och promptmallar.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Leverantörskopplingar för TTS-persona`},help:{"v1-993jop-3e":`Leverantörsspecifika kopplingar för TTS-personor med talleverantörens id som nyckel. Dessa slås samman med tts.providers och har företräde för den aktiva personan.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Inställningar för TTS-leverantör`},help:{"v1-1k80nl4-4y":`Leverantörsspecifika TTS-inställningar med talleverantörens id som nyckel. Använd detta i stället för medföljande leverantörsspecifika nycklar på toppnivå så att talinsticksprogram förblir frikopplade från kärnans konfigurationsschema.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Konfiguration för TTS-leverantör`},help:{"v1-dwapva-3d":`Leverantörsspecifik TTS-konfiguration för ett talleverantörs-id. Begränsa fälten till insticksprogrammet som ansvarar för den leverantören.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`API-nyckel för TTS-leverantör`},help:{"v1-1m2fj0i-2o":`Leverantörens API-nyckel som används av talleverantören när dess insticksprogram kräver autentiserad TTS-åtkomst.`}},tui:{label:{"v1-c8hus1-b":`Terminalgränssnitt`},help:{"v1-1fg9vw2-3s":`Visningsinställningar för terminalgränssnittet. Använd det här avsnittet för presentationsinställningar som bara gäller terminalen utan att ändra beteendet för Gateway eller andra gränssnitt.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Terminalgränssnittets sidfot`},help:{"v1-6e12l3-3k":`Visningsinställningar för terminalgränssnittets sidfot. Håll valfri kontext kompakt så att information om session, modell, mål och token förblir lättläst.`}},ui:{label:{"v1-ye4dff-2":`Gränssnitt`},help:{"v1-dt1924-42":`Presentationsinställningar för gränssnittets accenter och operatörens visningspreferenser. Använd detta för att anpassa läsbarheten utan att ändra beteendet vid körning.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Användarens accentfärg`},help:{"v1-mpxaka-4y":`Webbappens accentfärg: #RRGGBB för en anpassad färg eller 'theme' för det valda temats palett. Åsidosätter ui.seamColor; rensa värdet för att använda den konfigurerade accentfärgen eller temats standardfärg.`}},"ui%2Eprefs%2Elocale":{label:{"v1-sk0cbe-i":`Gränssnittsspråk`},help:{"v1-6mqtbz-6x":`Språk för webbappen, angivet som ett språk-ID som stöds, till exempel en, de eller zh-CN. Lämna värdet tomt för att följa webbläsarens eller systemets språk. Ställ in det via Inställningar → Utseende → Språk. Detta ställer inte in assistentens tidszon (agents.defaults.userTimezone).`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Accentfärg`},help:{"v1-14q3r4h-4g":`Primär accentfärg som används i gränssnittet för framhävning, märken och visuella identitetsmarkörer. Använd färgvärden med hög kontrast som förblir lättlästa i både ljusa och mörka teman.`}},update:{label:{"v1-k12u1x-7":`Uppdateringar`},help:{"v1-11c5k8v-5c":`Inställningar för uppdateringskanal och kontroll vid start som håller OpenClaw uppdaterat. Använd försiktigare kanaler i produktion och mer experimentella kanaler endast i kontrollerade miljöer.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Automatisk uppdatering aktiverad`},help:{"v1-49xs2h-3c":`Aktivera automatisk uppdatering i bakgrunden för paketinstallationer från stable och beta; uppdateringar från extended-stable tillämpas aldrig automatiskt (standard: false).`}},"update%2Eauto%2Eschedule":{label:{"v1-1t6cr06-p":`Schema för automatiska uppdateringar`},help:{"v1-zuf1kc-5y":`Valfritt cron-uttryck för när Gateways automatiska uppdateringskampanjer startar, i Gateway-värdens tidszon. Utelämna för att behålla det befintliga timintervallet. Fördröjningar vid utrullning och nedräkningar vid inaktivitet gäller fortfarande; missade tidsfönster hoppas över.`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Uppdateringskanal`},help:{"v1-lqtdvf-5b":`Uppdateringskanal för git- och npm-installationer ("stable", "extended-stable", "beta" eller "dev"). extended-stable gäller endast paket: installation sker endast i förgrunden, med valfria skrivskyddade tips vid start.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Sök efter uppdateringar vid start`},help:{"v1-qy3q9g-5v":`Söker efter uppdateringar när Gateway startar, inklusive skrivskyddade tips för extended-stable (standard: true). Ange false för att inaktivera automatiska uppdateringskontroller, installation av uppdateringar och anonyma uppdateringspingar för Gateway och noder utan användargränssnitt.`}},voicewake:{label:{"v1-txt1wb-a":`Röstaktivering`}},web:{label:{"v1-1ae9z56-b":`Webbkanal`}},wizard:{label:{"v1-28jonk-h":`Konfigurationsinställningar`},help:{"v1-14jh6rm-3b":`Användarägda konfigurationsinställningar. Maskinägd guidehistorik och bekräftelsestatus lagras i den delade tillståndsdatabasen.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Åtkomst för identifiering vid konfiguration`},help:{"v1-1nqxt0w-38":`Samtycke till identifiering under guidad konfiguration: "full" söker utan att fråga, medan "guarded" frågar innan lokala program granskas.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Apprekommendationer vid konfiguration`},help:{"v1-ub8uoi-30":`Styr om guidad konfiguration får använda etiketter för installerade program för att rekommendera relevanta insticksprogram och färdigheter.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Tidsstämpel för guidens senaste körning`},help:{"v1-1y0fbk-1k":`Tidsstämpel för den senaste guidekörningen som sparades utan fel.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Kommando för guidens senaste körning`},help:{"v1-x2pfkk-15":`Kommandot som startade guidens senaste körning.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit för guidens senaste körning`},help:{"v1-h0jkmt-1i":`Källkodscommit som användes vid den senaste körningen av utvecklingsguiden.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Läge vid guidens senaste körning`},help:{"v1-16508qy-1r":`Om guidens senaste körning avsåg konfiguration i läget "local" eller "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Version vid guidens senaste körning`},help:{"v1-1tr4z9d-19":`OpenClaw-version som användes vid guidens senaste körning.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Tidsstämpel för guidens säkerhetsbekräftelse`},help:{"v1-86i182-2a":`Tidsstämpel för säkerhetsbekräftelsen under konfigurationen, sparad tillsammans med målkonfigurationen.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Acceleration av arbetsträd`},help:{"v1-9es3gc-4r":`Använd filsystemsacceleration för nya hanterade arbetsträd när det stöds (standard: true). Ange false för att använda vanlig Git-utcheckning och filkopiering. Gäller endast nya arbetsträd.`}},worktreeMaxCount:{label:{"v1-1gj5fhm-p":`Maximalt antal hanterade arbetsträd`},help:{"v1-6z5l36-7q":`Maximalt antal befintliga hanterade arbetsträd för alla agenter och kodarkiv (standard: 4096). Tar först bort grenar som slagits samman eller squashats, därefter de äldsta inaktiva arbetsträden, inklusive osparade data. Pågående körningar skyddas; höj värdet om de fyller gränsen. Kravet på tillräckligt diskutrymme gäller fortfarande.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Rotkatalog för arbetsträd`},help:{"v1-1tgti9j-5d":`Global katalog för nya hanterade arbetsträd. Använd en absolut sökväg eller ~ för din hemkatalog; standardvärdet är <state-dir>/worktrees. Befintliga arbetsträd behåller sina registrerade sökvägar när detta ändras.`}}}}})))()}export{n,i as t};